const colegioExams = {"1": [{"number": 1, "axis": "Formación Ciudadana", "text": "De acuerdo con la teoría política clásica, la organización de la República de Chile se basa en la separación de los poderes públicos, lo que significa que la gestión del Estado se distribuye en distintos órganos. En este sentido, ¿cuál es una de las principales funciones del Poder Legislativo?", "answers": [{"letter": "A", "text": "Proponer los principales cargos públicos del Estado."}, {"letter": "B", "text": "Verificar la aplicación de las leyes en el territorio nacional."}, {"letter": "C", "text": "Defender la implementación de políticas gubernamentales."}, {"letter": "D", "text": "Debatir proyectos de ley emanados por iniciativa presidencial."}], "correctAnswer": null}, {"number": 2, "axis": "Formación Ciudadana", "text": "La libertad de expresión es un derecho consagrado en la Constitución Política de Chile, que comprende la libertad de emitir opiniones y de informar, sin censura previa, en cualquier forma y medio. ¿Cuál de las siguientes situaciones da cuenta de la aplicación de este derecho en el país?", "answers": [{"letter": "A", "text": "La detención de un periodista por publicar información sin autorización."}, {"letter": "B", "text": "La emisión de un documental que denuncia actos de corrupción en el país."}, {"letter": "C", "text": "La prohibición de la publicación de una caricatura que satiriza al presidente."}, {"letter": "D", "text": "La sanción a un canal televisivo por difundir noticias que afectan a un alcalde."}], "correctAnswer": null}, {"number": 3, "axis": "Formación Ciudadana", "text": "La ley de probidad en la función pública, publicada en enero de 2016, fue una de las iniciativas aprobadas por el gobierno de Michelle Bachelet, en medio de una de las mayores crisis de credibilidad de la clase política en el último tiempo. En este contexto, ¿cuál es el principal objetivo que persigue esta ley?", "answers": [{"letter": "A", "text": "Fomentar el clientelismo en la administración pública del país."}, {"letter": "B", "text": "Proteger los derechos de propiedad de los servidores públicos."}, {"letter": "C", "text": "Apoyar las decisiones del sistema de partidos políticos chilenos."}, {"letter": "D", "text": "Promover una conducta honesta entre los funcionarios estatales."}], "correctAnswer": null}, {"number": 4, "axis": "Formación Ciudadana", "text": "A fines del siglo XVIII, se expandió progresivamente la idea del Estado de Derecho, con elementos y características claramente definidos. A partir de lo anterior, ¿cuál de las siguientes alternativas corresponde a un elemento del Estado de Derecho?", "answers": [{"letter": "A", "text": "El régimen de partido único."}, {"letter": "B", "text": "El desarrollo de golpes de Estado."}, {"letter": "C", "text": "La separación de los poderes del Estado."}, {"letter": "D", "text": "La existencia de una monarquía absoluta."}], "correctAnswer": null}, {"number": 5, "axis": "Formación Ciudadana", "text": "Desde la década de 1960, las Organizaciones No Gubernamentales (ONG) han sido una parte importante de la sociedad civil a nivel mundial. En Chile, las ONG han tenido un papel significativo en el desarrollo social. Considerando lo anterior, ¿cuál es una de las principales características de este tipo de organizaciones?", "answers": [{"letter": "A", "text": "Son organizaciones gubernamentales que ofrecen servicios sociales."}, {"letter": "B", "text": "Son una herramienta del Estado para llevar a cabo políticas públicas."}, {"letter": "C", "text": "Son entidades con fines de lucro que buscan maximizar sus beneficios."}, {"letter": "D", "text": "Son autónomas del Estado para realizar actividades de beneficio social."}], "correctAnswer": null}, {"number": 6, "axis": "Formación Ciudadana", "text": "Chile se reconoce como un Estado democrático que garantiza los derechos fundamentales de la sociedad. En este mismo marco y desde una perspectiva de derecho civil, la ciudadanía también debe cumplir con sus propias responsabilidades. A partir de lo anterior, ¿cuál de los siguientes elementos representa una responsabilidad propia de la ciudadanía?", "answers": [{"letter": "A", "text": "Elaborar formas de representación de distintos grupos sociales."}, {"letter": "B", "text": "Mantener actitudes que cumplan con las leyes y normas establecidas."}, {"letter": "C", "text": "Dirigir instituciones estatales que aseguren la soberanía dentro del territorio."}, {"letter": "D", "text": "Generar instancias de diálogo con los representantes políticos de otros países."}], "correctAnswer": null}, {"number": 7, "axis": "Formación Ciudadana", "text": "La ley N° 20.285, más conocida como Ley de Transparencia permite mantener un principio del Estado de Derecho. Con respecto al significado fundamental de esta normativa, ¿cuál es su principal objetivo?", "answers": [{"letter": "A", "text": "Garantizar el acceso a la base de datos de las empresas privadas."}, {"letter": "B", "text": "Establecer el principio de intrascendencia de la información oficial."}, {"letter": "C", "text": "Permitir el derecho de las personas al acceso a información pública."}, {"letter": "D", "text": "Direccionar los procedimientos administrativos de la gestión estatal."}], "correctAnswer": null}, {"number": 8, "axis": "Formación Ciudadana", "text": "Los partidos políticos son asociaciones, cuyo objetivo es obtener el poder político dentro de una comunidad y así llevar a cabo sus programas. Considerando lo anterior, ¿cuál es un desafío de este tipo de organizaciones?", "answers": [{"letter": "A", "text": "Obtener respaldo popular para acceder a cargos políticos."}, {"letter": "B", "text": "Controlar la legislación del país imponiendo diversos proyectos."}, {"letter": "C", "text": "Otorgar a las personas una justicia oportuna en búsqueda de la paz."}, {"letter": "D", "text": "Difundir las estadísticas oficiales del país para implementar políticas."}], "correctAnswer": null}, {"number": 9, "axis": "Formación Ciudadana", "text": "En Chile se manifiestan los tres poderes del Estado y cada uno de ellos tiene funciones y atribuciones específicas, permitiendo el equilibrio fundamental para la democracia en el país. Considerando lo anterior, ¿Cuál de las siguientes afirmaciones es una de las atribuciones del Poder Ejecutivo en Chile?", "answers": [{"letter": "A", "text": "Emitir decretos con fuerza de ley en casos de urgencia y necesidad."}, {"letter": "B", "text": "Declarar la guerra a otros países obviando el parecer del parlamento."}, {"letter": "C", "text": "Destituir a los parlamentarios del Congreso Nacional ante corrupción."}, {"letter": "D", "text": "Modificar la Constitución sin necesidad de aprobación de otros poderes."}], "correctAnswer": null}, {"number": 10, "axis": "Formación Ciudadana", "text": "Lea el siguiente texto: “Hoy existe un amplio consenso en que el nivel local representa el espacio por excelencia para hacer efectiva la participación, porque en él es posible el encuentro cierto entre los ciudadanos y sus representantes y entre las necesidades de la población y las decisiones de la autoridad. La participación de los ciudadanos fortalece la gestión local, ya que incrementa la eficiencia y la eficacia de las decisiones”. Fernández, I. (2006) Participación ciudadana en el nivel local: Desafíos para la construcción de una ciudadanía activa. Santiago, Chile. La autora explica la importancia de la participación ciudadana a nivel municipal y algunas de sus repercusiones. De acuerdo con la información del párrafo, ¿cuál es el objetivo de este tipo de participación?", "answers": [{"letter": "A", "text": "Desvincular a las organizaciones locales en la toma de decisiones."}, {"letter": "B", "text": "Fortalecer la gestión de los municipios al conocer demandas ciudadanas."}, {"letter": "C", "text": "Desarrollar una participación ciudadana que fortalezca la gestión del Estado."}, {"letter": "D", "text": "Transferir atribuciones desde las municipalidades hacia las juntas de vecinos."}], "correctAnswer": null}, {"number": 11, "axis": "Formación Ciudadana", "text": "En Chile, los ciudadanos tienen la posibilidad de involucrarse en la política a través de medios tradicionales y no tradicionales, que les permiten tomar decisiones en asuntos que afectan a sus comunidades. En este sentido, ¿qué opción refleja una participación no tradicional?", "answers": [{"letter": "A", "text": "Adherir y hacer campaña en un partido político."}, {"letter": "B", "text": "Postular para concejal de la comuna en la que habita."}, {"letter": "C", "text": "Participar en los diversos tipos de procesos electorales."}, {"letter": "D", "text": "Recolectar firmas para promover la solución de un conflicto."}], "correctAnswer": null}, {"number": 12, "axis": "Formación Ciudadana", "text": "En los estados democráticos, la participación ciudadana es clave, pues otorga a la ciudadanía el poder de elegir a sus representantes. En los procesos electorales, ¿cuál de las siguientes instancias corresponde a una facultad ciudadana?", "answers": [{"letter": "A", "text": "La fiscalización del proceso electoral."}, {"letter": "B", "text": "La determinación de la fecha de los comicios."}, {"letter": "C", "text": "La definición de las normas que rigen las elecciones."}, {"letter": "D", "text": "La proposición del monto de financiamiento de las campañas."}], "correctAnswer": null}, {"number": 13, "axis": "Formación Ciudadana", "text": "Las municipalidades son órganos encargados de la administración local, cuya finalidad es satisfacer las necesidades de su comunidad, así como asegurar la participación en el progreso económico, social y cultural de su territorio. Al respecto, ¿cuál de las siguientes opciones constituye un desafío para estas corporaciones?", "answers": [{"letter": "A", "text": "Fiscalizar las decisiones políticas a nivel nacional."}, {"letter": "B", "text": "Legislar considerando los requerimientos de la región."}, {"letter": "C", "text": "Resolver problemáticas de la población en su territorio."}, {"letter": "D", "text": "Aumentar el presupuesto regional para recibir recursos."}], "correctAnswer": null}, {"number": 14, "axis": "Formación Ciudadana", "text": "En una sociedad democrática, los ciudadanos tienen la responsabilidad de proteger los derechos y la integridad humana, además de cumplir con varios deberes que promuevan la 5 buena convivencia en sociedad. En relación con lo anterior, ¿cuál corresponde a un deber de la sociedad civil?", "answers": [{"letter": "A", "text": "Respetar las leyes y normas establecidas en la sociedad."}, {"letter": "B", "text": "Gestionar la investigación científica y la innovación tecnológica."}, {"letter": "C", "text": "Constituir la seguridad ciudadana y la lucha contra la delincuencia."}, {"letter": "D", "text": "Ejercer la libertad de culto y expresión religiosa en el ámbito público."}], "correctAnswer": null}, {"number": 15, "axis": "Formación Ciudadana", "text": "El Estado de Derecho se define por una serie de características, que permiten vivir en democracia. Considerando el marco legal en Chile, ¿qué condición es necesaria para la existencia de este tipo de Estado?", "answers": [{"letter": "A", "text": "El autoritarismo en las decisiones políticas por parte del poder ejecutivo."}, {"letter": "B", "text": "El compromiso ciudadano de participar en elecciones con voto voluntario."}, {"letter": "C", "text": "El actuar de las Fuerzas Armadas en el cumplimiento de la institucionalidad."}, {"letter": "D", "text": "El desempeño apegado al marco legal existente por parte de los gobernantes."}], "correctAnswer": null}, {"number": 16, "axis": "Formación Ciudadana", "text": "En la mayoría de los países occidentales, incluido Chile, la estrategia de gobierno que prevalece es la democracia existiendo ciertos principios fundamentales que son comunes en todos ellos. A partir de lo anterior, ¿cuál es un principio común en las democracias occidentales?", "answers": [{"letter": "A", "text": "Desestimar a la oposición política del gobierno."}, {"letter": "B", "text": "Gobernar imponiendo a un selecto grupo de expertos."}, {"letter": "C", "text": "Elegir a las autoridades mediante elecciones periódicas."}, {"letter": "D", "text": "Mantener el poder político en un grupo reducido de personas."}], "correctAnswer": null}, {"number": 17, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “La principal meta política de los liberales era el estado constitucional como garante de la seguridad jurídica y de la participación ciudadana en las tareas del Estado. (…) Para la mayor parte de ellos era deseable que existiera el parlamentarismo como forma de gobierno, en la que las relaciones de mayoría existentes en el Parlamento determinaran la composición y la política del gobierno. (…) En lo referente a la forma de Estado, los liberales europeos no mantenían una actitud en común. Pero en general sus preferencias se inclinaban del lado de la monarquía, aunque controlada por un Parlamento (...). En cualquier caso, también transigían con la república, como lo demuestra el ejemplo francés”. Fradera J. y Millán J. (2000). Las burguesías europeas del siglo XIX. Sociedad civil, política y cultura. España. El texto expone la importancia del parlamentarismo y las constituciones en el desarrollo de los Estados liberales europeos del siglo XIX. De su análisis es correcto afirmar que", "answers": [{"letter": "A", "text": "los liberales europeos pretendían desarrollar un sistema de gobierno de tipo monárquico."}, {"letter": "B", "text": "la república como forma de Estado era la meta que pretendían desarrollar los liberales europeos de la época."}, {"letter": "C", "text": "la idea del constitucionalismo representa políticamente el inicio del Estado parlamentario como forma de gobierno."}, {"letter": "D", "text": "existe una idea diversificada entre los liberales de la época, respecto de la forma de Estado que se pretende llevar a cabo."}], "correctAnswer": null}, {"number": 18, "axis": "Historia: Mundo, América y Chile", "text": "El proceso de emancipación de Chile dejó significativas repercusiones en la economía, política y en la sociedad. Con relación a la esfera política, ¿qué impacto provocó el periodo de organización de la República?", "answers": [{"letter": "A", "text": "La promulgación de constituciones de larga duración."}, {"letter": "B", "text": "La disminución de la hegemonía de la élite terrateniente."}, {"letter": "C", "text": "La incorporación del estamento indígena a la esfera política."}, {"letter": "D", "text": "La división aristocrática en un bando conservador y otro liberal."}], "correctAnswer": null}, {"number": 19, "axis": "Historia: Mundo, América y Chile", "text": "Durante el proceso de conformación del Estado nación, la idea de soberanía popular fue una fuerza impulsora en los movimientos políticos y sociales en América Latina. Respecto a lo anterior, ¿cómo se reflejó la idea de soberanía en Latinoamérica durante el siglo XIX?", "answers": [{"letter": "A", "text": "Proponiendo la unificación de América Latina en una sola nación."}, {"letter": "B", "text": "Declarando la lucha por la autonomía de las naciones latinoamericanas."}, {"letter": "C", "text": "Protegiendo los derechos de las minorías étnicas y religiosas del continente."}, {"letter": "D", "text": "Instaurando la creación de una monarquía constitucional en América Latina."}], "correctAnswer": null}, {"number": 20, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “Lo que [los liberales clásicos de la segunda mitad del siglo XVIII] pretendían era un proyecto de sociedad que alcanzara un amplio espacio de libertad personal, económica, religiosa o de expresión; un espacio, en fin, mucho mayor que el que se había reivindicado en el pasado inmediato. (...) Cuando los liberales trataron de definir a finales del siglo XVIII su movimiento, lo presentaron como la antítesis del viejo orden al aspirar a crear una sociedad de ciudadanos, (…) libres e iguales”. Castells, I. Cruz, M & Robledo, R. (2003). Los liberalismos, una mirada desde la Historia. El texto anterior expone el ideario que aborda el liberalismo en Europa durante el siglo XIX. Respecto al liberalismo, ¿cuál es una propuesta de esta ideología? 8", "answers": [{"letter": "A", "text": "Expresa una unión absoluta de ideales desde lo clásico a lo moderno."}, {"letter": "B", "text": "Implica una contraposición al proyecto ideado por los liberales clásicos."}, {"letter": "C", "text": "Promueve el espacio limitado de libertad personal, económica y religiosa."}, {"letter": "D", "text": "Reconoce espacios de libertad y derechos individuales entre las sociedades."}], "correctAnswer": null}, {"number": 21, "axis": "Historia: Mundo, América y Chile", "text": "En la primera mitad del siglo XIX, sucedieron una serie de revoluciones que generaron importantes cambios políticos en la Europa del período. Considerando lo anterior, ¿cuál es uno de los cambios desarrollados tras estas revoluciones?", "answers": [{"letter": "A", "text": "Promovieron el liderazgo político de los sectores obreros."}, {"letter": "B", "text": "Marcaron el fin del Antiguo Régimen instalando repúblicas."}, {"letter": "C", "text": "Incorporaron a una parte del clero y la nobleza de la época."}, {"letter": "D", "text": "Impulsaron la lucha de clases para alcanzar la igualdad social."}], "correctAnswer": null}, {"number": 22, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “Pero es sólo por su propio provecho que un hombre emplea su capital en apoyo de la industria; por tanto, siempre se esforzará en usarlo en la industria cuyo producto tienda a ser de mayor valor o en intercambiarlo por la mayor cantidad posible de dinero u otros bienes (...) En esto está, como en otros muchos casos, guiado por una mano invisible para alcanzar un fin que no formaba parte de su intención. Y tampoco es lo peor para la sociedad que esto haya sido así. Al buscar su propio interés, el hombre a menudo favorece el de la sociedad mejor que cuando realmente desea hacerlo”. Smith. A. La riqueza de las naciones. En Manual básico de economía. El fragmento corresponde al libro \"La riqueza de las naciones\" de Adam Smith, economista escocés que estableció los fundamentos del pensamiento económico liberal. A partir de su lectura, ¿cuál de las opciones describe un principio del liberalismo?", "answers": [{"letter": "A", "text": "La búsqueda del interés personal beneficia al resto de la sociedad."}, {"letter": "B", "text": "Las empresas estatales producen una serie de ventajas para la nación."}, {"letter": "C", "text": "La producción industrial acarrea pérdidas al vincular los intereses del país."}, {"letter": "D", "text": "Los hombres que fomentan el bienestar social causan más perjuicio al país."}], "correctAnswer": null}, {"number": 23, "axis": "Historia: Mundo, América y Chile", "text": "Durante el siglo XIX se desarrolló la unificación italiana gracias al nacionalismo, que se apoyó del vínculo histórico y racial entre los reinos de la península italiana y el apoyo de la 9 burguesía, dado el potencial económico que ésta representaba. En base a lo anterior, ¿cuál de las siguientes opciones fue un obstáculo en el proceso de construcción de este país?", "answers": [{"letter": "A", "text": "La resistencia de la Iglesia católica a renunciar a sus territorios."}, {"letter": "B", "text": "La oposición enérgica de las clases trabajadoras al nacionalismo."}, {"letter": "C", "text": "Las disparidades étnicas entre los distintos reinos de la península."}, {"letter": "D", "text": "La resistencia de los burgueses, quienes financiaron la unificación."}], "correctAnswer": null}, {"number": 24, "axis": "Historia: Mundo, América y Chile", "text": "Tras la proclamación de su independencia en 1818, el Estado de Chile inició un proceso de organización no exento de dificultades, especialmente en materia económica. La agricultura se encontraba en una situación precaria, a pesar de ser la principal actividad productiva del país. ¿Qué factor contribuyó a mantener dicha condición en la década de 1820?", "answers": [{"letter": "A", "text": "La prolongación de los conflictos bélicos en el sur del país."}, {"letter": "B", "text": "El cierre definitivo de Argentina como principal mercado externo."}, {"letter": "C", "text": "La interrupción de las innovaciones tecnológicas aplicadas en el campo."}, {"letter": "D", "text": "La restricción de las exportaciones nacionales en Europa y Norteamérica."}], "correctAnswer": null}, {"number": 25, "axis": "Historia: Mundo, América y Chile", "text": "En el transcurso del siglo XIX, América experimentó un proceso de construcción de estados-nación liderado por las élites de cada país, cuyo objetivo era reformar la estructura política, abandonando las monarquías. A partir de lo anterior, ¿cuál de los siguientes enunciados representa un desafío para los estados-nación?", "answers": [{"letter": "A", "text": "Crear reglas que fortalezcan las acciones realizadas por la monarquía."}, {"letter": "B", "text": "Unificar los poderes públicos en una figura dictatorial que ostente el poder."}, {"letter": "C", "text": "Redactar una constitución que establezca los poderes del estado nacional."}, {"letter": "D", "text": "Promover la propagación de las ideas conservadoras en los diferentes países."}], "correctAnswer": null}, {"number": 26, "axis": "Historia: Mundo, América y Chile", "text": "En 1823, se instituye la doctrina Monroe, cuya política fue establecida en un contexto histórico en el que muchos países de América Latina se estaban independizando de las potencias coloniales y formado los Estado nación. Considerando lo anterior, ¿cuál es una de principales ideas de esta doctrina?", "answers": [{"letter": "A", "text": "Evitar la intervención europea en los países del continente americano."}, {"letter": "B", "text": "Dirigir la unificación política de América bajo la guía de los Estados Unidos."}, {"letter": "C", "text": "Promover la economía libre y el intercambio comercial entre los americanos."}, {"letter": "D", "text": "Proteger los derechos humanos y la democracia entre los países americanos."}], "correctAnswer": null}, {"number": 27, "axis": "Historia: Mundo, América y Chile", "text": "Después de su independencia, Chile tuvo que enfrentar el desafío de construir una 10 república que ofreciera mejores condiciones políticas y sociales que las que existían durante el dominio español. Sin embargo, este desafío fue asumido por un pequeño grupo social, la élite económica chilena, quienes crearon un país a su medida. Considerando estas características, ¿cuál de las siguientes opciones corresponde a un aspecto de la política chilena del siglo XIX?", "answers": [{"letter": "A", "text": "La baja participación política de las clases populares en el país."}, {"letter": "B", "text": "La construcción de obras públicas en beneficio de la clase obrera."}, {"letter": "C", "text": "El acceso universal a la educación pública en Chile a partir de 1833."}, {"letter": "D", "text": "El interés político por mejorar las condiciones de vida de los trabajadores."}], "correctAnswer": null}, {"number": 28, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “En Chile la ley no sirve para otra cosa que no sea para producir la anarquía, la ausencia de sanciones, el libertinaje, el pleito eterno, el compadrazgo y la amistad. Si yo, por ejemplo, apreso a un individuo que sé que está urdiendo una conspiración, violo la ley. ¡Maldita ley, entonces, si no deja al brazo del Gobierno proceder libremente en el momento oportuno! Este respeto por el delincuente, o presunto delincuente, acabará con el país en poco tiempo. El Gobierno parece dispuesto a perpetuar una orientación de esta especie, enseñando una consideración a la ley que me parece sencillamente indigna. De mí sé decirle que con ley o sin ella, esa señora que llaman la Constitución, hay que violarla cuando las circunstancias son extremas”. Portales, D. Carta a Antonio Garfias, 1834. La fuente adjunta alude al pensamiento del ministro Diego Portales a inicios de la década de 1830. En este sentido, ¿qué principio político se deriva del fragmento?", "answers": [{"letter": "A", "text": "La ampliación de la participación democrática."}, {"letter": "B", "text": "La restricción a las atribuciones del Poder Judicial."}, {"letter": "C", "text": "La aplicación de sanciones para mantener el gobierno."}, {"letter": "D", "text": "La defensa de libertades individuales ante la acción estatal."}], "correctAnswer": null}, {"number": 29, "axis": "Historia: Mundo, América y Chile", "text": "El sistema de votación establecido en la Constitución política de 1833 en Chile, conocido 11 como voto censitario, permitía la participación ciudadana a los hombres que poseían propiedad y cumplían con ciertos requisitos. Esta restricción era justificada por la ideología liberal, la cual argumentaba, que algunos grupos sociales estaban más capacitados que otros para participar en la democracia. Considerando la descripción anterior, ¿cuál de las siguientes opciones representó un avance en la construcción de un sistema democrático chileno más amplio durante el siglo XIX?", "answers": [{"letter": "A", "text": "La inclusión de las mujeres al sistema electoral."}, {"letter": "B", "text": "La supresión de los partidos políticos de izquierda."}, {"letter": "C", "text": "La eliminación de los criterios económicos para votar."}, {"letter": "D", "text": "La apertura de los registros electorales a los no videntes."}], "correctAnswer": null}, {"number": 30, "axis": "Historia: Mundo, América y Chile", "text": "Las reformas al funcionamiento productivo y comercial de Chile, implementadas en la década de 1830, contribuyeron a la reactivación económica, pues dieron impulso al desarrollo de la minería y la agricultura. Entre otros aspectos, ¿qué consecuencia tuvo el crecimiento de estos rubros productivos hacia mediados del siglo XIX?", "answers": [{"letter": "A", "text": "La eliminación de la deuda externa del país."}, {"letter": "B", "text": "La activa intervención del Estado en el sector primario."}, {"letter": "C", "text": "El aumento del comercio exterior vinculado a materias primas."}, {"letter": "D", "text": "La exportación de bienes manufacturados a mercados vecinos."}], "correctAnswer": null}, {"number": 31, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “El símbolo de progreso que más rápidamente quedó en evidencia fue la revolución del transporte que acompañó a la expansión del comercio de ultramar, para la que fue una condición indispensable. (...) Obviamente, el vapor revolucionó también el transporte por tierra. La primera vía férrea chilena (con 80 kilómetros) fue tendida en 1851 para unir Copiapó con el puerto de Caldera. Fue construida por (...) [William] Wheelwright y financiada por un grupo de ricos mineros y comerciantes”. Sater, W. y Collier, S. (2018). Historia de Chile, 1808-2017 El texto se refiere a la evolución de los medios de transporte en el siglo XIX en el mundo como también en Chile. Considerando lo recién expuesto, ¿cuál fue una consecuencia asociada a la innovación tecnológica?", "answers": [{"letter": "A", "text": "La estatización de empresas del rubro ferroviario."}, {"letter": "B", "text": "El aumento de la capacidad de transporte de recursos."}, {"letter": "C", "text": "El desplazamiento de la actividad minera hacia la costa."}, {"letter": "D", "text": "La construcción de carreteras en la zona central del país."}], "correctAnswer": null}, {"number": 32, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “La intervención electoral debe ser considerada el principal antecedente de la revolución de 1891. Todos los gobiernos habían venido ejercitándola desde 1810. En un principio se 12 le aceptó como una necesidad, dada la escasísima preparación política de los ciudadanos. Más tarde se le toleró como una tradición; pero, finalmente, llegó a ser considerada como un abuso por algunos de los mismos a quienes favorecía su ejercicio y a ser rechazada como intolerable vejamen por los que padecían las consecuencias de la usurpación de un derecho apreciado ya en su justo alcance”. Irarrázaval, M. (1940) El presidente Balmaceda. La reseña anterior corresponde a una interpretación sobre el origen de la Guerra Civil de 1891. A partir de su análisis, ¿cuál fue una de las causas del conflicto aludido?", "answers": [{"letter": "A", "text": "La limitada participación de los sectores proletarios."}, {"letter": "B", "text": "La intervención del catolicismo sobre el orden público."}, {"letter": "C", "text": "La ineficiente iniciativa del Congreso en el orden legislativo."}, {"letter": "D", "text": "La permanente manipulación del gobierno en las elecciones."}], "correctAnswer": null}, {"number": 33, "axis": "Historia: Mundo, América y Chile", "text": "Durante los decenios conservadores (1831-1861) gobernaron los presidentes José Joaquín Prieto, Manuel Bulnes y Manuel Montt. Considerando la ideología de este sector político, ¿cuál fue una característica de este periodo de la Historia de Chile?", "answers": [{"letter": "A", "text": "El establecimiento de un sistema de gobierno federal."}, {"letter": "B", "text": "La industrialización de las actividades productivas del país."}, {"letter": "C", "text": "La fuerte influencia del catolicismo en la vida política nacional."}, {"letter": "D", "text": "El desarrollo de programas de asistencia entre los campesinos."}], "correctAnswer": null}, {"number": 34, "axis": "Historia: Mundo, América y Chile", "text": "En el siglo XIX, Chile se integró al sistema capitalista mundial al proveer sus recursos naturales, a los centros industriales del mundo. Considerando lo anterior, ¿cuál de las siguientes fue una consecuencia de este modelo para el país?", "answers": [{"letter": "A", "text": "La activación de la industria nacional al exportar manufacturas."}, {"letter": "B", "text": "La formulación de políticas que disminuyeran la pobreza del país."}, {"letter": "C", "text": "El aumento de los ingresos estatales dados los impuestos del salitre."}, {"letter": "D", "text": "El retroceso económico experimentado por la clase dirigente del país."}], "correctAnswer": null}, {"number": 35, "axis": "Historia: Mundo, América y Chile", "text": "En 1850, se fundó en Chile la Sociedad de la Igualdad, cuyo objetivo era acabar con las desigualdades sociales y políticas. ¿Cuál fue el desafío que esta organización planteó para alcanzar sus metas? 13", "answers": [{"letter": "A", "text": "Crear un sistema de castas que incentivara la igualdad social."}, {"letter": "B", "text": "Impulsar la educación y la cultura para todas las clases sociales."}, {"letter": "C", "text": "Fomentar la migración a países que tuvieran sociedades igualitarias."}, {"letter": "D", "text": "Implementar un sistema ideológico comunista en el territorio nacional."}], "correctAnswer": null}, {"number": 36, "axis": "Historia: Mundo, América y Chile", "text": "Durante la guerra contra la Confederación Perú-Boliviana, tuvo lugar la Batalla de Yungay, que es considerada un momento crucial para el desarrollo social del país. ¿Cómo afectó esta batalla en el ámbito social?", "answers": [{"letter": "A", "text": "Fomentó el imperialismo dada la superioridad del país."}, {"letter": "B", "text": "Fortaleció el sentimiento nacional en la sociedad chilena."}, {"letter": "C", "text": "Produjo una crisis de identidad nacional ante la unión altiplánica."}, {"letter": "D", "text": "Disminuyó la autonomía de Chile al buscar aliados en otras naciones."}], "correctAnswer": null}, {"number": 37, "axis": "Historia: Mundo, América y Chile", "text": "Bajo la influencia del liberalismo se produjo el ascenso de un sector político que promovió cambios en el país. Considerando el ideario liberal, ¿cuál fue una propuesta política de este grupo?", "answers": [{"letter": "A", "text": "Incrementar el poder del clero en la sociedad."}, {"letter": "B", "text": "Promover la centralización del poder en el país."}, {"letter": "C", "text": "Defender derechos de los sectores aristocráticos."}, {"letter": "D", "text": "Reformar aspectos autoritarios de la carta magna."}], "correctAnswer": null}, {"number": 38, "axis": "Historia: Mundo, América y Chile", "text": "Hacia fines del siglo XIX, el Estado chileno comenzó a recibir grandes cantidades de dinero provenientes de los impuestos generados por la industria salitrera nacional. Estos ingresos se destinaron principalmente a mejorar la infraestructura y transporte. Sin embargo, hubo críticas porque durante este período también se vivía la \"cuestión social\". De acuerdo con lo anterior, ¿cuál de las siguientes alternativas expresa un problema en el país a fines del siglo XIX y principios del siglo XX?", "answers": [{"letter": "A", "text": "La carencia de recursos para invertir en viviendas para la población."}, {"letter": "B", "text": "El escaso esfuerzo del Estado por ofrecer oportunidades a la oligarquía."}, {"letter": "C", "text": "La escasa voluntad política por solucionar los problemas del proletariado."}, {"letter": "D", "text": "El deterioro de las Fuerzas Armadas que no contó con insumos para defensa."}], "correctAnswer": null}, {"number": 39, "axis": "Historia: Mundo, América y Chile", "text": "En el Valparaíso de 1890 surgió la Sociedad de Unión y Fraternidad de Obreras, cuyo objetivo fue ofrecer mayor seguridad para las proletarias. Paralelo a ello, otras mujeres, de diferente condición social, accedieron a la educación superior, destacando las primeras en acceder al título de médicas; Eloísa Díaz y Ernestina Pérez. Considerando estos avances, ¿cuál fue el principal desafío de las mujeres chilenas a comienzos del siglo XX?", "answers": [{"letter": "A", "text": "Alcanzar derechos políticos como el acceso al voto."}, {"letter": "B", "text": "Generar mejores ingresos superando al de los hombres."}, {"letter": "C", "text": "Fortalecer la maternidad con beneficios como el posnatal. 14"}, {"letter": "D", "text": "Promover la paridad en las instituciones estatales chilenas."}], "correctAnswer": null}, {"number": 40, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “En 1890, el inmigrante español Manuel Chinchilla creó las primeras organizaciones anarquistas entre los obreros tipógrafos de Valparaíso y Santiago, labor que continuaron Carlos Jorquera, Magno Espinosa y Alejandro Escobar. Los ácratas influyeron de manera importante en la etapa de conformación de las organizaciones de los trabajadores, difundiendo los ideales del asociacionismo obrero y la conciencia de clase. En este sentido, impulsaron el desarrollo de las mancomunales, las federaciones gremiales y las sociedades en resistencia, que alcanzaron gran apoyo entre obreros y artesanos de Santiago, Valparaíso, Talca y Concepción.” Memoria chilena. El anarquismo en Chile (1890-1953) El texto menciona la influencia del anarquismo en Chile a finales del siglo XIX. En base a lo expuesto en el párrafo, ¿qué impacto tuvo esta ideología en la política nacional?", "answers": [{"letter": "A", "text": "Generó cambios sociales al negociar con el gobierno mejoras laborales."}, {"letter": "B", "text": "Apoyó en la organización obrera para alcanzar el poder del Estado chileno."}, {"letter": "C", "text": "Fomentó el desarrollo de agrupaciones obreras para su organización y lucha."}, {"letter": "D", "text": "Intervino en las industrias nacionales para aumentar la producción artesanal."}], "correctAnswer": null}, {"number": 41, "axis": "Historia: Mundo, América y Chile", "text": "A partir del año 1929, se desencadenó una gran crisis económica a nivel global, tras el colapso de la bolsa de valores de Nueva York. En América Latina, donde la economía dependía de sus exportaciones, se vivieron los efectos más intensos de la Gran Depresión. Considerando lo anterior ¿Qué medidas tomaron los gobiernos latinoamericanos para enfrentar la crisis económica?", "answers": [{"letter": "A", "text": "El control estatal de las empresas de origen extranjero."}, {"letter": "B", "text": "La expropiación de las tierras agrícolas dentro del país."}, {"letter": "C", "text": "La estatización de los recursos productivos estratégicos"}, {"letter": "D", "text": "La aplicación de un modelo sustitutivo de importaciones."}], "correctAnswer": null}, {"number": 42, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “He logrado reprimir enérgicamente las actividades del comunismo y me propuse, a fin de poder gobernar, eliminar con mano firme a los que se habían trazado como único objeto de su acción pública impedirlo con todos los medios a su alcance. Esas medidas (destierros y otras) son ineludibles. Se ha hablado de los políticos profesionales. Poseen el arte de la oposición. Tienen una habilidad increíble para enredar las cosas, para propalar rumores inquietantes, para tergiversar lo más sencillo, no se puede confiar en su colaboración (…) A su vez los conservadores no han aprendido todavía de que la organización moderna de la sociedad no puede sustraerse a la idea de justicia social y conciliar los intereses opuestos con un concepto equitativo que es al fin y al cabo lo que 15 dicta la razón y lo que aconseja la prudencia”. Carlos Ibáñez del Campo (1929) Entrevista a Diario la Nación de Buenos Aires. El fragmento corresponde a parte de la entrevista realizada por el Diario La Nación al presidente chileno Carlos Ibáñez del Campo, considerado uno de los representantes del populismo. A partir de la entrevista, ¿cuál de las siguientes opciones representa una de las características del populismo en Latinoamérica?", "answers": [{"letter": "A", "text": "El liderazgo de políticos de izquierda."}, {"letter": "B", "text": "La fuerte influencia de líderes militares."}, {"letter": "C", "text": "La mirada crítica hacia los partidos políticos."}, {"letter": "D", "text": "El intento por apartar a los sectores populares."}], "correctAnswer": null}, {"number": 43, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “El Partido Nacional Fascista es una milicia civil al servicio del Estado. Su objetivo es hacer realidad la grandeza del pueblo italiano. Desde sus propios orígenes, con el renacimiento de la conducta italiana y la voluntad de alcanzar la victoria, el partido se ha considerado siempre en estado de guerra; al principio, para derrotar a aquellos que deshonraban el espíritu de la nación; en la actualidad y siempre, para defender y acrecentar el poder del pueblo italiano. El fascismo no es tan solo la unión de italianos en torno a determinado programa (...) sino sobre todo una fe que ha dado a sus miembros y en cuyas filas actúan los nuevos italianos como soldados”. Estatutos del Partido Nacional Fascista, 1921 A partir de la lectura de la fuente adjunta, ¿qué rasgo compartido por los totalitarismos europeos del período de entreguerras es correcto identificar?", "answers": [{"letter": "A", "text": "La defensa de la idea de superioridad racial."}, {"letter": "B", "text": "La planificación de la economía por el Estado."}, {"letter": "C", "text": "La promoción del pacifismo entre los habitantes."}, {"letter": "D", "text": "La exacerbación del nacionalismo en la población."}], "correctAnswer": null}, {"number": 44, "axis": "Historia: Mundo, América y Chile", "text": "Dado que los sistemas totalitarios tenían características específicas y provocaron grandes conflictos bélicos en todo el mundo, ¿cuál de las siguientes opciones se plantea 16 como un desafío para los países democráticos?", "answers": [{"letter": "A", "text": "Instaurar una organización internacional que promoviera la democracia."}, {"letter": "B", "text": "Auspiciar un programa de estudios nucleares para frenar el comunismo."}, {"letter": "C", "text": "Promover una institución europea para proteger a las colonias asiáticas."}, {"letter": "D", "text": "Fortalecer a la Sociedad de las Naciones para frenar el totalitarismo nazi."}], "correctAnswer": null}, {"number": 45, "axis": "Historia: Mundo, América y Chile", "text": "En respuesta a las diversas crisis mundiales surgidas a principios del siglo XX, muchos estados occidentales adoptaron un modelo basado en el Estado de bienestar. Desde una perspectiva económica, ¿qué característica es típica de este tipo de sistema?", "answers": [{"letter": "A", "text": "Privatización de empresas estatales."}, {"letter": "B", "text": "Eliminación de las regulaciones laborales."}, {"letter": "C", "text": "Reducción de los impuestos sobre la renta para los ricos."}, {"letter": "D", "text": "Expansión de servicios sociales financiados por el Estado."}], "correctAnswer": null}, {"number": 46, "axis": "Historia: Mundo, América y Chile", "text": "En 1960, la Asamblea General de las Naciones Unidas hizo un llamado a la finalización inmediata del colonialismo en todas sus formas, declarando que todos los pueblos tienen el derecho a la libre determinación. Como resultado de esta declaración, ¿cuál de los siguientes eventos es una consecuencia?", "answers": [{"letter": "A", "text": "La descolonización de numerosos territorios bajo dominio europeo."}, {"letter": "B", "text": "La división de países europeos, como Alemania, en varios territorios."}, {"letter": "C", "text": "La expansión colonial de potencias europeas en Asia y América Latina."}, {"letter": "D", "text": "La mayor cooperación entre las potencias y colonias recién emancipadas."}], "correctAnswer": null}, {"number": 47, "axis": "Historia: Mundo, América y Chile", "text": "Entre principios del siglo XX y 1960, la sociedad chilena experimentó una importante transformación demográfica. En este sentido, ¿cuál fue un cambio que se puede identificar?", "answers": [{"letter": "A", "text": "La concentración de población en zonas extremas del país."}, {"letter": "B", "text": "El aumento de población producto de la protección estatal."}, {"letter": "C", "text": "El auge de la actividad salitrera hacia mediados del siglo XX."}, {"letter": "D", "text": "La mayor migración desde las zonas urbanas hacia los campos."}], "correctAnswer": null}, {"number": 48, "axis": "Historia: Mundo, América y Chile", "text": "En Chile, hacia la década de 1950, se observaban los primeros signos de agotamiento del modelo industrializador, lo que fue acompañado de una alta inflación. En paralelo, la población aumentaba considerablemente y el ritmo de la migración desde el campo a las 17 ciudades se mantenía. ¿Cuál fue una consecuencia del panorama descrito en la década siguiente?", "answers": [{"letter": "A", "text": "La sustitución del modelo de desarrollo."}, {"letter": "B", "text": "El incremento de la marginalidad urbana."}, {"letter": "C", "text": "La caída en el precio de los bienes básicos."}, {"letter": "D", "text": "El despoblamiento de los grandes latifundios."}], "correctAnswer": null}, {"number": 49, "axis": "Historia: Mundo, América y Chile", "text": "Durante la mitad del siglo XX, uno de los sucesos más significativos en Chile fue la aparición de varios grupos sociales, en la esfera pública, exigiendo diversas demandas. En relación a lo anterior, ¿cuál de los siguientes es un grupo representativo de la primera mitad del siglo XX?", "answers": [{"letter": "A", "text": "Las mujeres que exigían diversos derechos políticos en el país."}, {"letter": "B", "text": "Los ecologistas que criticaba el impacto del modelo sustitutivo."}, {"letter": "C", "text": "La burguesía que comenzaba a irrumpir en actividades mineras."}, {"letter": "D", "text": "La clase aristocrática que exigía mayor participación económica."}], "correctAnswer": null}, {"number": 50, "axis": "Historia: Mundo, América y Chile", "text": "En la década de 1970, en Latinoamérica surgieron dictaduras militares con el propósito de frenar el avance del marxismo en la región. Una de las estrategias empleadas para alcanzar esta meta fue la implementación del Plan Cóndor. En este sentido, ¿cuál fue la principal consecuencia de este plan?", "answers": [{"letter": "A", "text": "La consolidación de los gobiernos democráticos en la región, que lograron mantenerse estables durante varias décadas."}, {"letter": "B", "text": "La creación de un clima de terror y represión, que llevó a la persecución, tortura y desaparición de miles de personas en Latinoamérica."}, {"letter": "C", "text": "El fomento de una economía centralizada en los países que formaron parte de esta Operación permitiendo la reducción de la pobreza."}, {"letter": "D", "text": "La promoción de la libertad de expresión y de los derechos humanos, como parte de las medidas implementadas para combatir el comunismo."}], "correctAnswer": null}, {"number": 51, "axis": "Historia: Mundo, América y Chile", "text": "En septiembre de 1973, un Golpe de Estado militar, liderado por el general Augusto Pinochet, derrocó al gobierno democrático de Salvador Allende en Chile. Considerando lo anterior, ¿Cuál fue la excusa planteada por los militares para realizar el Golpe de Estado?", "answers": [{"letter": "A", "text": "El interés de Allende de instaurar un gobierno totalitario en Chile."}, {"letter": "B", "text": "La intervención de la Unión Soviética en apoyo al golpe de estado."}, {"letter": "C", "text": "El deseo de Pinochet de establecer un gobierno más democrático. 18"}, {"letter": "D", "text": "La amenaza de que se estableciera un régimen comunista en Chile."}], "correctAnswer": null}, {"number": 52, "axis": "Historia: Mundo, América y Chile", "text": "Después del golpe de estado en Chile en 1973, la Junta Militar liderada por Pinochet implementó una serie de políticas represivas y autoritarias. ¿Qué consecuencia social tuvo el golpe de estado en Chile en 1973?", "answers": [{"letter": "A", "text": "La disminución en la criminalidad y la violencia en las calles."}, {"letter": "B", "text": "El aumento de la inversión extranjera en la economía chilena."}, {"letter": "C", "text": "El desarrollo de un sistema educativo de alta calidad en Chile."}, {"letter": "D", "text": "La violación a los derechos humanos en la población opositora."}], "correctAnswer": null}, {"number": 53, "axis": "Historia: Mundo, América y Chile", "text": "Durante la dictadura militar en Chile, se implementó una nueva constitución en el año 1980. Esta tuvo un impacto significativo en la vida democrática chilena. ¿Cuál fue el principal efecto de la constitución de 1980 en el sistema político chileno?", "answers": [{"letter": "A", "text": "Debilitó el rol del Estado en la protección ciudadana."}, {"letter": "B", "text": "Limitó la capacidad del ejecutivo para gobernar el país."}, {"letter": "C", "text": "Estableció una mayor independencia del poder judicial."}, {"letter": "D", "text": "Reforzó el poder del Congreso Nacional asumir el poder."}], "correctAnswer": null}, {"number": 54, "axis": "Historia: Mundo, América y Chile", "text": "Durante el periodo de dictadura se implementaron diversas políticas para mantener el control y el poder del país, por medio de organismos estatales y otros autónomos que dependían específicamente de Augusto Pinochet. Este es el caso de la Dirección de Inteligencia Nacional (DINA). Considerando lo anterior, ¿cuál fue la principal función de la DINA durante este período?", "answers": [{"letter": "A", "text": "Fomentar el desarrollo económico y neoliberal del país."}, {"letter": "B", "text": "Promover la educación y la cultura en la sociedad chilena."}, {"letter": "C", "text": "Ejecutar la represión y persecución de opositores políticos."}, {"letter": "D", "text": "Asegurar un sistema de justicia para los detenidos políticos."}], "correctAnswer": null}, {"number": 55, "axis": "Historia: Mundo, América y Chile", "text": "En la década de 1970, Chile implementó políticas económicas neoliberales bajo el régimen de Augusto Pinochet, convirtiéndose en uno de los primeros países en instalar este sistema económico. ¿Cuál de las siguientes políticas es ejemplo del neoliberalismo?", "answers": [{"letter": "A", "text": "La aplicación de altos aranceles a las importaciones."}, {"letter": "B", "text": "La privatización de la mayoría de las empresas estatales."}, {"letter": "C", "text": "La estatización de los mercados de productos y servicios."}, {"letter": "D", "text": "La planificación centralizada y aumento del gasto público."}], "correctAnswer": null}, {"number": 56, "axis": "Historia: Mundo, América y Chile", "text": "Durante la crisis económica de 1982, el gobierno chileno enfrentó la devaluación de su 19 moneda lo que generó graves consecuencias económicas y sociales. Considerando la crisis referida, ¿cuál fue la estrategia económica adoptada para estabilizar la economía?", "answers": [{"letter": "A", "text": "Nacionalizar la banca extranjera."}, {"letter": "B", "text": "Disminuir el gasto público nacional."}, {"letter": "C", "text": "Desincentivar la inversión extranjera."}, {"letter": "D", "text": "Acelerar la estatización de las empresas."}], "correctAnswer": null}, {"number": 57, "axis": "Historia: Mundo, América y Chile", "text": "Entre las décadas de 1960 y 1970, países sudamericanos como Brasil, Argentina y Uruguay fueron gobernados por dictaduras militares que tuvieron distinta extensión temporal. Sin embargo, existieron importantes transformaciones en el aspecto político a fines de la década de 1980. ¿Cuál de las siguientes afirmaciones da cuenta de estos cambios?", "answers": [{"letter": "A", "text": "La exclusión de los partidos de izquierda en la política."}, {"letter": "B", "text": "El fin de procesos judiciales sobre derechos humanos."}, {"letter": "C", "text": "La transferencia del poder político a los sectores civiles."}, {"letter": "D", "text": "El surgimiento de movimientos nacionalistas totalitarios."}], "correctAnswer": null}, {"number": 58, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “El alma de Chile, íntimamente ligada a la fe cristiana, muestra desde su mismo nacimiento un sagrado respeto por la dignidad del hombre, cualquiera sea su raza y condición; y un extraordinario aprecio por su libertad, huella imborrable de su semejanza divina. Nosotros no hemos hecho otra cosa que procurar ser fieles a esta tradición, entendiéndola como un legado […]”. Silva, R. (1978). Respeto a los derechos humanos. El texto corresponde a un discurso del cardenal Raúl Silva Henríquez, quien participó en la creación del Comité Pro Paz y la Vicaría de la Solidaridad. A partir de la lectura, ¿cuál fue el principal objetivo de estas instituciones?", "answers": [{"letter": "A", "text": "Promover la lucha armada contra la dictadura."}, {"letter": "B", "text": "Apoyar las medidas represivas del gobierno militar."}, {"letter": "C", "text": "Proteger a la sociedad a partir de los valores cristianos."}, {"letter": "D", "text": "Fomentar la lectura de las escrituras para alcanzar la paz."}], "correctAnswer": null}, {"number": 59, "axis": "Historia: Mundo, América y Chile", "text": "De acuerdo con lo estipulado por la normativa constitucional, en 1988 debía celebrarse un plebiscito que definiría la continuidad del régimen militar. En relación con este acontecimiento, ¿qué consecuencia tuvo el triunfo de la opción “No”?", "answers": [{"letter": "A", "text": "La entrega del Gobierno a un conglomerado de centroderecha."}, {"letter": "B", "text": "La elección por el Congreso de un nuevo presidente de la República."}, {"letter": "C", "text": "La transmisión del poder desde la Junta Militar hacia la Corte Suprema."}, {"letter": "D", "text": "La realización de elecciones legislativas y presidenciales dentro de un año."}], "correctAnswer": null}, {"number": 60, "axis": "Sistema Económico", "text": "En un mercado de frutas y verduras, se produce un aumento en la demanda de manzanas. Este aumento en la demanda se generó gracias a una mayor publicidad y la creciente popularidad de las manzanas como alimento saludable. ¿cómo afecta al mercado el mayor consumo de esta fruta?", "answers": [{"letter": "A", "text": "Aumento en el precio y en la cantidad ofrecida."}, {"letter": "B", "text": "Aumento en el precio y disminución en la oferta."}, {"letter": "C", "text": "Disminución en el precio y aumento en la oferta."}, {"letter": "D", "text": "Disminución en el precio y en la cantidad ofrecida."}], "correctAnswer": null}, {"number": 61, "axis": "Sistema Económico", "text": "La inflación es un fenómeno económico que afecta a todas las sociedades y que puede tener graves consecuencias en la economía de un país. Los gobiernos y los bancos centrales implementan diversas medidas para controlar la inflación y mantenerla en niveles estables. En relación con lo anterior, ¿qué factor puede generar inflación en un país?", "answers": [{"letter": "A", "text": "Un incremento en la productividad laboral."}, {"letter": "B", "text": "Un aumento en la oferta de bienes y servicios."}, {"letter": "C", "text": "Una disminución en la demanda de bienes y servicios."}, {"letter": "D", "text": "Un alza generalizada en los precios de bienes y servicios. 21"}], "correctAnswer": null}, {"number": 62, "axis": "Sistema Económico", "text": "En un mercado altamente contaminante, una empresa ha sido acusada de generar una gran cantidad de emisiones de gases de efecto invernadero que contribuyen al cambio climático. Sin embargo, la empresa afirma que estas emisiones son necesarias para la producción de bienes y servicios que benefician a la sociedad en general. La discusión se centra en si las emisiones son una externalidad negativa del mercado o un costo necesario para el bienestar social. ¿Cuál de las siguientes afirmaciones proporciona el mejor argumento para la postura de que las emisiones de la empresa son una externalidad negativa del mercado?", "answers": [{"letter": "A", "text": "Las emisiones son necesarias para mantener el empleo en la empresa y en la industria en general."}, {"letter": "B", "text": "Las emisiones no afectan directamente la salud humana, por lo que no son una externalidad negativa."}, {"letter": "C", "text": "La empresa ha tomado medidas para reducir sus emisiones, pero estas siguen siendo demasiado altas."}, {"letter": "D", "text": "La emisión de gases afecta en el cambio climático, lo que causa daños económicos y sociales a largo plazo."}], "correctAnswer": null}, {"number": 63, "axis": "Sistema Económico", "text": "La existencia de monopolios puede generar un impacto significativo en una economía. Un monopolio se define como una situación en la que una sola empresa controla todo el mercado y no tiene competidores. En este contexto, ¿cuál es una de sus principales características?", "answers": [{"letter": "A", "text": "Impiden la entrada de nuevos competidores en el mercado."}, {"letter": "B", "text": "Generan la distribución equitativa de la riqueza en la sociedad."}, {"letter": "C", "text": "Promueven la innovación en la industria al dinamizar el mercado."}, {"letter": "D", "text": "Benefician a los consumidores porque permiten precios más bajos."}], "correctAnswer": null}, {"number": 64, "axis": "Sistema Económico", "text": "La evasión es un tema importante en la economía y tiene implicaciones significativas en los sistemas fiscales y políticos. En este contexto, ¿cuál de las siguientes afirmaciones responde a una de sus características?", "answers": [{"letter": "A", "text": "Es un problema ético que reduce la confianza en las empresas."}, {"letter": "B", "text": "Es un delito penado por ley pues afecta a los ingresos del Estado."}, {"letter": "C", "text": "Es un delito que involucra a las personas más que a las empresas."}, {"letter": "D", "text": "Es un problema común de los países desarrollados industrializados."}], "correctAnswer": null}, {"number": 65, "axis": "Sistema Económico", "text": "En el mercado de la telefonía móvil, dos empresas líderes en el mercado han sido acusadas de colusión por fijar precios altos, limitado la oferta para maximizar sus ganancias. 22 ¿Qué estrategia podrían utilizar los consumidores afectados por la colusión de las empresas de telefonía móvil para proteger sus intereses?", "answers": [{"letter": "A", "text": "Cambiar a una empresa de telefonía móvil extranjera que no esté involucrada en la colusión."}, {"letter": "B", "text": "Aceptar los precios y planes ofrecidos por las empresas coludidas, ya que es la única opción disponible."}, {"letter": "C", "text": "Reportar la colusión a las autoridades competentes para que impongan multas y sanciones a las empresas."}, {"letter": "D", "text": "Negociar directamente con las empresas coludidas para obtener precios más bajos en los planes de datos móviles."}], "correctAnswer": null}], "2": [{"number": 1, "axis": "Formación Ciudadana", "text": "Lea el siguiente texto: “En cuanto a los valores esenciales de la democracia, encontramos el reconocer la dignidad de la persona humana. Entendiendo a la persona como un ser racional, ya que puede pensar; que tiene voluntad, dado que puede dirigir su conducta; que tiene afectividad, dado que puede sentir y generar adhesión a personas, cosas y valores; que es consciente de sí misma, por tanto, puede relacionarse con otros; que es capaz de aprender, pudiendo perfeccionarse; y, finalmente, que es libre y puede elegir entre opciones diversas y proponer nuevas alternativas”. López K.(2016), La democracia de hoy. El texto describe el valor de la dignidad humana y su aporte a la democracia. Considerando lo propuesto en el párrafo, ¿cuál de las siguientes afirmaciones describe una característica de las personas en el contexto democrático?", "answers": [{"letter": "A", "text": "Ser individualista pues defiende sus propios intereses."}, {"letter": "B", "text": "Ser sociable pues se relaciona y empatiza con sus pares."}, {"letter": "C", "text": "Ser egoísta pues evita compartir sus recursos y conocimientos."}, {"letter": "D", "text": "Ser inocente pues es controlado por sus representantes políticos."}], "correctAnswer": null}, {"number": 2, "axis": "Formación Ciudadana", "text": "Uno de los fundamentos de la democracia es la soberanía popular, que obedece a la idea de que el Estado debe estar legitimado por las personas que componen la nación. Alcanzar la democracia ha representado un largo camino para muchas de las repúblicas occidentales. Considerando el contexto descrito, ¿cuál de las siguientes alternativas explica el retraso para conseguir el sufragio universal en los países?", "answers": [{"letter": "A", "text": "La negativa en conceder el voto femenino, pues durante buena parte del siglo XX se le consideraba inferior al hombre."}, {"letter": "B", "text": "El interés del mundo laico por aumentar la participación de la iglesia católica en las elecciones políticas para evitar su influencia."}, {"letter": "C", "text": "El temor de las clases proletarias por entregar el derecho a sufragio de sus jefes, quienes intentarían reducir los derechos sociales."}, {"letter": "D", "text": "La instalación de sistemas federales, en la mayoría de los países del mundo, limitó la participación ciudadana a reducidas oportunidades."}], "correctAnswer": null}, {"number": 3, "axis": "Formación Ciudadana", "text": "Una de las dimensiones de la democracia es la representatividad, asociada a los votos obtenidos en las elecciones y a los índices de representatividad que alcanzan las autoridades durante su gobierno. En los últimos años la representatividad ha ido disminuyendo. Considerando el contexto planteado, ¿cuál es uno de los desafíos para alcanzar mayores grados de representatividad?", "answers": [{"letter": "A", "text": "Aumentar los impuestos de la clase media."}, {"letter": "B", "text": "Repartir dinero entre los ciudadanos del país."}, {"letter": "C", "text": "Disminuir los índices de corrupción en política."}, {"letter": "D", "text": "Cerrar los medios de prensa críticos al gobierno."}], "correctAnswer": null}, {"number": 4, "axis": "Formación Ciudadana", "text": "Lea el siguiente texto: “En América Latina, la situación no ha sido demasiado diferente. Experiencias como la de Nicolás Maduro en Venezuela o Daniel Ortega en Nicaragua indican un debilitamiento en varios aspectos de la democracia, donde la relación hacia la oposición ha alcanzado dimensiones preocupantes. En Brasil, el gobierno del ex-capitán Jair Bolsonaro siguió una senda similar. Además de dejar librada a su suerte la vida de miles de personas en medio de la pandemia, Bolsonaro ha instado en diversas oportunidades a la sociedad civil a armarse frente al «comunismo», utilizando un lenguaje violento y conspirativo Freibrun, N.(2022). El malestar en la democracia. El párrafo corresponde a un extracto de la columna de opinión de Nicolás Freibrun denominada “El Malestar de la democracia”. En el texto se expone la situación política de América Latina. Considerando lo expresado en el párrafo, ¿cuál de las siguientes alternativas expresa un peligro para la democracia latinoamericana?", "answers": [{"letter": "A", "text": "La cantidad de dictaduras de izquierda que amenazan a las inversiones."}, {"letter": "B", "text": "El alza de delitos económicos que generan incertidumbre en la población."}, {"letter": "C", "text": "La participación de los militares en las decisiones políticas del continente."}, {"letter": "D", "text": "El aumento en los discursos y acciones en contra de los enemigos políticos."}], "correctAnswer": null}, {"number": 5, "axis": "Formación Ciudadana", "text": "En Chile, la mala influencia de los empresarios en la política ha mermado la confianza que la ciudadanía tiene en sus representantes. Los casos Corpesca, Penta y Soquimich son sólo algunos ejemplos en la política. En este escenario, ¿cuál de las siguientes alternativas representa una solución para enfrentar el cohecho?", "answers": [{"letter": "A", "text": "Reducir las facultades del Ministerio Público."}, {"letter": "B", "text": "Redactar una ley de transparencia y probidad."}, {"letter": "C", "text": "Establecer leyes más drásticas para el cohecho."}, {"letter": "D", "text": "Ampliar el rol de la Fiscalía Nacional Económica."}], "correctAnswer": null}, {"number": 6, "axis": "Formación Ciudadana", "text": "En los últimos años en Chile se ha cuestionado la accesibilidad a los centros de votación. Considerado las características geográficas del país, ¿cuál de las siguientes alternativas puede facilitar, aún más, el acceso a los actos electorales?", "answers": [{"letter": "A", "text": "Obligar a los jóvenes a votar."}, {"letter": "B", "text": "Incorporar el voto telemático."}, {"letter": "C", "text": "Aplicar gratuidad en la locomoción."}, {"letter": "D", "text": "Considerar la voluntariedad del voto."}], "correctAnswer": null}, {"number": 7, "axis": "Formación Ciudadana", "text": "En una sociedad, como la chilena, donde se busca fortalecer la democracia y promover el bienestar general, es fundamental identificar cuáles son las acciones que impulsan el bien común. Considerando este objetivo, ¿cuál de las siguientes acciones contribuye al bien común?", "answers": [{"letter": "A", "text": "Establecer restricciones a la libre expresión para evitar polarización."}, {"letter": "B", "text": "Promover la participación ciudadana en la toma de decisiones políticas."}, {"letter": "C", "text": "Conceder privilegios a grupos minoritarios para fomentar su integración."}, {"letter": "D", "text": "Otorgar amplios poderes al Estado sin una rendición de cuentas efectiva."}], "correctAnswer": null}, {"number": 8, "axis": "Formación Ciudadana", "text": "Lea el siguiente texto: “El sondeo también consultó respecto a cuál valor la gente le daba más importancia en 4 una democracia: si a que haya libertades públicas y privadas o a que haya orden público y seguridad ciudadana. En ese sentido un 10% de los entrevistados se mostró más cercano a la primera opción y un 68% a la segunda alternativa, siendo esta última cifra la más alta desde noviembre-diciembre de 2008” Reyes C., Encuesta CEP revela deterioro en la percepción ciudadana de la democracia en Chile. La Tercera. 04 de enero de 2023 El texto muestra parte de los resultados de la última encuesta del Centro de Estudios Públicos. Considerando lo expresado en el sondeo, ¿cuál es una conclusión válida que se puede obtener de los resultados de la encuesta?", "answers": [{"letter": "A", "text": "Se observa un aumento en el valor de la democracia y las libertades."}, {"letter": "B", "text": "Se explicita una disminución en la importancia dada al orden público."}, {"letter": "C", "text": "Se manifiesta un aumento en la valoración de la seguridad ciudadana."}, {"letter": "D", "text": "Se expresa un retroceso en la valoración a los regímenes dictatoriales."}], "correctAnswer": null}, {"number": 9, "axis": "Formación Ciudadana", "text": "En los últimos años, en Chile se ha denunciado una gran cantidad de eventos que afectan a las empresas privadas: fraudes, colusión, elusión de impuestos y evasión tributaria, que desprestigian al mundo empresarial. Sin embargo, las cifras de evasión tributaria también se vinculan con acciones de los ciudadanos comunes y corrientes. Considerando el contexto presentado, ¿en cuál de las siguientes situaciones una familia daña al fisco?", "answers": [{"letter": "A", "text": "Al no exigir boleta de compra - venta en los negocios de su barrio."}, {"letter": "B", "text": "Al costear vacaciones en un hotel caribeño de República Dominicana."}, {"letter": "C", "text": "Al sumar, entre sus integrantes, un ingreso superior a dos sueldos mínimos."}, {"letter": "D", "text": "Al financiar la educación de sus hijos en colegios particulares pagados del país."}], "correctAnswer": null}, {"number": 10, "axis": "Formación Ciudadana", "text": "Lea el siguiente texto: “El principal mecanismo de rendición de cuentas (accountability) democrático son las elecciones. El control político que ejerce el ciudadano a través del voto es la esencia de la democracia. Sin embargo, el control político que pueden ejercer los ciudadanos es limitado, tanto porque las elecciones tienen intervalos de tiempo relativamente largos como porque la disponibilidad de información al momento de ejercer el voto es limitada. De esta forma, la existencia de un accountability horizontal (…) se basa en la necesidad de un sistema de pesos y contrapesos en el Estado que permita un control complementario al ejercido por los ciudadanos a través del voto”. 5 Galli F., El rol de la Contraloría en el Estado chileno actual: ¿debería actuar la Cámara de Diputados como su mandante en el ejercicio de la función fiscalizadora? El párrafo adjunto refiere a la necesidad de controlar las acciones de las autoridades. A partir de lo señalado en el texto, ¿cuál de las siguientes medidas puede aplicarse para fortalecer la democracia?", "answers": [{"letter": "A", "text": "Restringir el acceso a la información electoral."}, {"letter": "B", "text": "Aumentar la duración del mandato presidencial."}, {"letter": "C", "text": "Ofrecer mayores atribuciones a las autoridades."}, {"letter": "D", "text": "Establecer un sistema de consultas ciudadanas."}], "correctAnswer": null}, {"number": 11, "axis": "Formación Ciudadana", "text": "En los Estados democráticos, la actividad política se focaliza en la generación de acuerdos entre una diversidad de actores sociales y políticos. En este sentido, ¿qué rol ejercen las organizaciones ciudadanas en Chile?", "answers": [{"letter": "A", "text": "Difunden las políticas sociales desarrolladas por el Gobierno."}, {"letter": "B", "text": "Aplican normas jurídicas sobre diversas materias a nivel local."}, {"letter": "C", "text": "Fomentan la inscripción de la ciudadanía en los partidos políticos."}, {"letter": "D", "text": "Representan los intereses de la comunidad ante instancias formales."}], "correctAnswer": null}, {"number": 12, "axis": "Formación Ciudadana", "text": "En un sistema democrático, el Estado se organiza en tres poderes fundamentales: el poder ejecutivo, el legislativo y el judicial. En este sentido, ¿cuál es la importancia de mantener la división de los poderes del Estado?", "answers": [{"letter": "A", "text": "Evitar la centralización del poder en una sola entidad."}, {"letter": "B", "text": "Fomentar la supremacía de un poder sobre los demás."}, {"letter": "C", "text": "Mantener el traspaso del poder entre las entidades públicas."}, {"letter": "D", "text": "Eliminar prácticas corruptas dentro de las instituciones estatales."}], "correctAnswer": null}, {"number": 13, "axis": "Formación Ciudadana", "text": "La probidad se refiere a la honestidad, integridad y transparencia en la actuación de los funcionarios públicos. En Chile, la probidad es un principio fundamental en la administración del Estado y en el ejercicio de cargos públicos. ¿Cuál de las siguientes acciones promueve la probidad en el ámbito público en Chile?", "answers": [{"letter": "A", "text": "La aceptación de obsequios por parte de funcionarios públicos."}, {"letter": "B", "text": "La identificación y manejo temprano de los conflictos de interés."}, {"letter": "C", "text": "La utilización de recursos públicos para beneficio personal o familiar."}, {"letter": "D", "text": "La participación en política mientras se desempeña en un cargo público."}], "correctAnswer": null}, {"number": 14, "axis": "Formación Ciudadana", "text": "El Estado de Derecho es un principio fundamental en una sociedad democrática en la que el poder se encuentra limitado y su ejercicio se rige por normas jurídicas que garantizan 6 los derechos individuales y colectivos. Con relación a lo anterior, ¿en cuál de las siguientes circunstancias se cumple el Estado de derecho?", "answers": [{"letter": "A", "text": "Cuando las normas jurídicas son aplicadas de manera selectiva."}, {"letter": "B", "text": "Cuando las leyes son establecidas de manera arbitraria por un líder."}, {"letter": "C", "text": "Cuando los derechos individuales son ignorados por las autoridades."}, {"letter": "D", "text": "Cuando existen mecanismos de control entre los poderes del Estado."}], "correctAnswer": null}, {"number": 15, "axis": "Formación Ciudadana", "text": "Los Derechos Humanos son un tema relevante en la sociedad actual. Los avances y desafíos en la protección de los derechos fundamentales han generado discusiones sobre diversas problemáticas que afectan a las personas en la actualidad. ¿Cuál de las siguientes situaciones representa un desafío actual en la protección de los DDHH?", "answers": [{"letter": "A", "text": "Persistir en la discriminación basada en la orientación sexual."}, {"letter": "B", "text": "Crear leyes para promover la inclusión y la igualdad de género."}, {"letter": "C", "text": "Garantizar el acceso segregado a la educación para las personas."}, {"letter": "D", "text": "Fortalecer los mecanismos de rendición de cuentas de autoridades."}], "correctAnswer": null}, {"number": 16, "axis": "Formación Ciudadana", "text": "Internet se ha expandido con mucha velocidad en Chile durante las últimas décadas, siendo parte indispensable de los hogares como también de los diferentes rubros productivos; sin embargo, por diferentes razones, no ha podido alcanzar una cobertura en todo el país, lo que se transforma en un gran desafío para las autoridades del Estado. En este sentido, ¿cuál de las siguientes afirmaciones representa un obstáculo geográfico que impide la expansión de Internet?", "answers": [{"letter": "A", "text": "La presencia de un territorio altamente montañoso."}, {"letter": "B", "text": "El desarrollo de una diversidad de zonas climáticas."}, {"letter": "C", "text": "La gran distancia entre ciudades del territorio nacional."}, {"letter": "D", "text": "El incremento de las zonas rurales en diferentes regiones."}], "correctAnswer": null}, {"number": 17, "axis": "Historia: Mundo, América y Chile", "text": "El liberalismo fue un movimiento político, social y económico que defendió la libertad en todo ámbito de la vida, para lo cual, se debía limitar el poder del Estado sobre todo en el aspecto económico. Considerando lo anterior, ¿qué elemento propio del liberalismo económico del siglo XIX se puede apreciar en la actualidad?", "answers": [{"letter": "A", "text": "La aplicación de políticas que aumenten el control estatal frente a inversionistas privados."}, {"letter": "B", "text": "La restricción al capital de los privados, causando que la relación entre las clases sociales mejore."}, {"letter": "C", "text": "La defensa de la propiedad comunitaria que busca proteger los bienes de consumo que poseen todas las personas."}, {"letter": "D", "text": "La existencia de un libre mercado que permite a consumidores y vendedores determinar la manera en que se relacionan."}], "correctAnswer": null}, {"number": 18, "axis": "Historia: Mundo, América y Chile", "text": "Al caer el Imperio Napoleónico en Europa, las monarquías absolutas intentaron recuperar el terreno perdido, y volver al régimen anterior a 1789, etapa que se denominó la Restauración. En este sentido, ¿cuál de las siguientes alternativas es una consecuencia del intento por recuperar las monarquías absolutas?", "answers": [{"letter": "A", "text": "El desarrollo de nuevos movimientos revolucionarios."}, {"letter": "B", "text": "El nacimiento de corrientes filosóficas anti sistémicas."}, {"letter": "C", "text": "La expansión de las operaciones colonialistas en África."}, {"letter": "D", "text": "La supresión de las ideas aportadas por los revolucionarios."}], "correctAnswer": null}, {"number": 19, "axis": "Historia: Mundo, América y Chile", "text": "El liberalismo fue una importante corriente filosófica, política y económica que tuvo gran influencia en la Europa del siglo XIX pero que también marcó las decisiones de los nacientes Estados americanos. En este sentido, y desde la perspectiva económica, ¿en cuál de los siguientes aspectos se aprecia la influencia liberal en los Estados americanos?", "answers": [{"letter": "A", "text": "La creación de altos impuestos a la riqueza."}, {"letter": "B", "text": "El fomento a la creación de industrias privadas."}, {"letter": "C", "text": "El desarrollo de la industrialización desde el Estado."}, {"letter": "D", "text": "La nacionalización de las principales materias primas."}], "correctAnswer": null}, {"number": 20, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente párrafo: \"Consideramos como verdades evidentes en sí mismas que todos los hombres son creados iguales; que son dotados por su Creador de ciertos derechos inalienables; que entre estos están la vida, la libertad y la búsqueda de la felicidad; que para garantizar estos derechos se instituyen entre los hombres los gobiernos, que derivan sus poderes legítimos del consentimiento de los gobernados; que cuando quiera que una forma de gobierno se haga destructora de estos principios, el pueblo tiene el derecho a reformarla o abolirla e instituir un nuevo gobierno que se funde en dichos principios, y a organizar sus poderes en la forma que a su juicio ofrecerá las mayores probabilidades de alcanzar su seguridad y felicidad [...].” Declaración de Independencia de Estados Unidos (1776). El fragmento corresponde a un extracto de la Declaración de Independencia de los Estados Unidos de 1776. Considerando lo expresado en el párrafo, ¿cuál de las siguientes afirmaciones corresponde a ideas de ilustración?", "answers": [{"letter": "A", "text": "La noción de progreso indefinido."}, {"letter": "B", "text": "La división de poderes del Estado."}, {"letter": "C", "text": "La creencia en una religión universal."}, {"letter": "D", "text": "La promoción de la soberanía popular."}], "correctAnswer": null}, {"number": 21, "axis": "Historia: Mundo, América y Chile", "text": "En el siglo XVIII surge el movimiento Ilustrado cuyas ideas repercutieron, incluso, hasta en el siglo XIX en Europa. En este sentido, ¿cuál de las siguientes afirmaciones corresponden a ideas ilustradas presentes en el siglo XIX?", "answers": [{"letter": "A", "text": "La reducción de regímenes con tendencias totalitarias."}, {"letter": "B", "text": "La implementación de la división de poderes del Estado."}, {"letter": "C", "text": "La llegada de las mujeres a las instituciones de gobierno."}, {"letter": "D", "text": "La expansión de los denominados Estados confesionales."}], "correctAnswer": null}, {"number": 22, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “Algunos movimientos nacionalistas tuvieron carácter integrador. Los dos casos más destacados de la segunda mitad del siglo XIX fueron las unificaciones de Italia y de Alemania. Entre ambos hay muchas semejanzas, como la difusión de las ideas de igualdad, libertad y soberanía nacional, y el despertar de un sentimiento de nación y de odio a los monarcas “extranjeros”; la expansión económica y la unión comercial se convirtieron en el preludio de la unificación política; fue importante la formación de movimientos de jóvenes patriotas románticos; las dirigieron los reyes con el apoyo de la burguesía, del Ejército y de sus jefes de gobierno”. Rosales, K. et al. Libro Historia, geografía y ciencias sociales. I medio. El fragmento da cuenta de algunas características presentes en los movimientos de unificación de Alemania e Italia durante el siglo XIX. En relación con lo anterior, ¿cuál de las siguientes afirmaciones expresa elementos comunes en estas unificaciones?", "answers": [{"letter": "A", "text": "El liderazgo ejercido por la burguesía."}, {"letter": "B", "text": "La formación de una autarquía comercial."}, {"letter": "C", "text": "El desarrollo de una profunda reforma religiosa."}, {"letter": "D", "text": "La adopción de sistemas políticos monárquicos."}], "correctAnswer": null}, {"number": 23, "axis": "Historia: Mundo, América y Chile", "text": "Entre 1810 y 1823, Chile desarrolló un proceso emancipador de la monarquía española. 10 Si bien existieron aspectos que cambiaron profundamente con el surgimiento de la república chilena, existieron otros que se mantuvieron por largo tiempo. En este sentido, ¿cuál de las siguientes alternativas da cuenta de elementos que se mantuvieron con el surgimiento de la república independiente chilena?", "answers": [{"letter": "A", "text": "La aplicación de un monopolio comercial."}, {"letter": "B", "text": "La elección abierta de autoridades políticas."}, {"letter": "C", "text": "La influencia del culto católico en la sociedad."}, {"letter": "D", "text": "La formación de una monarquía parlamentaria."}], "correctAnswer": null}, {"number": 24, "axis": "Historia: Mundo, América y Chile", "text": "Durante las primeras décadas del siglo XIX, América experimentó un profundo proceso de emancipación que permitió el surgimiento de nuevas repúblicas. Estas repúblicas, con diferentes matices, tuvieron aspectos positivos, así como también dificultades. En este sentido, ¿cuál de las siguientes alternativas da cuenta de los problemas en común experimentados por las nuevas repúblicas americanas?", "answers": [{"letter": "A", "text": "La creación de estructuras imperiales."}, {"letter": "B", "text": "Las rivalidades entre la nobleza y los obreros."}, {"letter": "C", "text": "La inexperiencia política de los diferentes gobiernos."}, {"letter": "D", "text": "La oposición de los sectores eclesiásticos a las reformas."}], "correctAnswer": null}, {"number": 25, "axis": "Historia: Mundo, América y Chile", "text": "Analice la siguiente caricatura: Doctrina Monroe. En diciembre de 1823 el Presidente de EEUU., James Monroe, compartió, en el Congreso 11 norteamericano, un conjunto de ideas en torno a la política que su país debía aplicar sobre el continente americano. Considerando la caricatura, ¿cuál de las siguientes alternativas representa el objetivo del presidente Monroe en Sudamérica?", "answers": [{"letter": "A", "text": "Imponer su cultura sobre las naciones latinoamericanas."}, {"letter": "B", "text": "Devolver a españoles y portugueses las colonias perdidas."}, {"letter": "C", "text": "Negociar con los europeos el dominio sobre América latina."}, {"letter": "D", "text": "Resguardar a los países latinoamericanos del dominio europeo."}], "correctAnswer": null}, {"number": 26, "axis": "Historia: Mundo, América y Chile", "text": "Tras la abdicación de O`Higgins en 1823, se inició la organización del Estado. En esta breve etapa, se aplicaron tres modelos políticos que fracasaron por las disputas de poder al interior de la elite nacional, dividida en conservadores y liberales. Uno de los modelos que intentó aplicarse fue el sistema federal. ¿Cuál fue la importancia de este proyecto para el país?", "answers": [{"letter": "A", "text": "Pretendía promover una descentralización político-administrativa."}, {"letter": "B", "text": "Buscaba fortalecer el control de la elite nacional sobre las provincias."}, {"letter": "C", "text": "Deseaba concentrar el poder en manos de una elite política reducida."}, {"letter": "D", "text": "Intentaba promover la igualdad económica entre las distintas provincias."}], "correctAnswer": null}, {"number": 27, "axis": "Historia: Mundo, América y Chile", "text": "Durante el siglo XIX, Chile atravesó un periodo de importantes transformaciones políticas y constitucionales. En esta época, se llevaron a cabo diversos ensayos que reflejaron las aspiraciones y tensiones de la sociedad chilena en su búsqueda por establecer un orden político y social. ¿Cuál fue una consecuencia de este proceso?", "answers": [{"letter": "A", "text": "La adopción del parlamentarismo."}, {"letter": "B", "text": "El fortalecimiento del poder ejecutivo."}, {"letter": "C", "text": "El surgimiento de movimientos separatistas."}, {"letter": "D", "text": "La polarización entre conservadores y liberales."}], "correctAnswer": null}, {"number": 28, "axis": "Historia: Mundo, América y Chile", "text": "La Constitución de 1833 fue una de las más influyentes en la historia política de Chile. Esta carta magna estableció un sistema político y social que perduró durante gran parte del siglo XIX, definiendo las bases del orden institucional y la organización del Estado chileno. ¿Cuál de las siguientes afirmaciones describe una característica de la Constitución de 1833?", "answers": [{"letter": "A", "text": "Reconoció el sufragio universal y garantizó la participación política de todos los ciudadanos, sin restricciones."}, {"letter": "B", "text": "Promovió la igualdad de género, otorgando derechos a las mujeres en los ámbitos de la vida política y social."}, {"letter": "C", "text": "Estableció un sistema presidencialista, donde el poder ejecutivo tenía amplias facultades y atribuciones políticas. 12"}, {"letter": "D", "text": "Instituyó un sistema de gobierno parlamentario, donde el poder ejecutivo era ejercido por un primer ministro elegido por el Congreso."}], "correctAnswer": null}, {"number": 29, "axis": "Historia: Mundo, América y Chile", "text": "Durante el siglo XIX, el sistema electoral chileno estuvo marcado por el voto censitario. Esta forma de votación generó debates entre distintos sectores de la sociedad. Considerando lo anterior, ¿cuál fue una dificultad asociada a este sistema?", "answers": [{"letter": "A", "text": "La baja participación ciudadana en las elecciones debido a la falta de interés político."}, {"letter": "B", "text": "La manipulación de los resultados electorales por parte de la élite política dominante."}, {"letter": "C", "text": "La limitación de la libertad de expresión y asociación política durante las campañas electorales."}, {"letter": "D", "text": "La falta de representatividad en las decisiones políticas al excluir a la mayoría de la población del derecho al voto."}], "correctAnswer": null}, {"number": 30, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “Apreciado amigo: La posición de Chile frente a la confederación Perú-boliviana es insostenible. No puede ser tolerada ni por el pueblo ni por el Gobierno, porque equivaldría a su suicidio. No podemos mirar sin inquietud y la mayor alarma la existencia de dos pueblos confederados, y que, a la larga, por la comunidad de origen, lengua, hábitos, religión, ideas, costumbres, formarán, como es natural, un solo núcleo”. Epistolario de don Diego Portales: 1821 – 1837. Ministerio de Justicia. El texto adjunto hace referencia al pensamiento de Portales en cuanto a la guerra de la Confederación Perú-Boliviana. Este refleja la idea de amenaza que representaría este suceso para Chile. A partir de su análisis, ¿por qué se justifica que Chile participe de una guerra contra la confederación?", "answers": [{"letter": "A", "text": "Amenazaba la integridad territorial de Chile al establecer la unión de las dos naciones."}, {"letter": "B", "text": "Buscaba imponer un sistema político y social compatible con los valores y principios de Chile."}, {"letter": "C", "text": "Permitiría a Chile anexar los territorios de Tarapacá y Antofagasta y explotar sus recursos."}, {"letter": "D", "text": "Representaba una alianza directa para luchar contra Argentina y recuperar la 13 Patagonia chilena."}], "correctAnswer": null}, {"number": 31, "axis": "Historia: Mundo, América y Chile", "text": "A mediados del siglo XIX, en Chile, se creó la Sociedad de la Igualdad, agrupación que reunió a intelectuales y representantes de sectores laborales como artesanos y sastres. Esta organización generó diversos debates y movimientos sociales de la época. Considerando la base social recién identificada, ¿cuál fue uno de los propósitos que tuvo la creación de esta institución?", "answers": [{"letter": "A", "text": "La defensa de los intereses de la aristocracia."}, {"letter": "B", "text": "La búsqueda de derechos para afrodescendientes."}, {"letter": "C", "text": "La demanda por la igualdad de derechos entre las personas."}, {"letter": "D", "text": "La difusión de ideas conservadoras vinculadas al catolicismo."}], "correctAnswer": null}, {"number": 32, "axis": "Historia: Mundo, América y Chile", "text": "Durante el siglo XIX, el cultivo y venta de trigo experimentó un notable crecimiento en Chile, impactando significativamente en la economía del país, ¿Cuál fue un impacto del auge de la agricultura en este período?", "answers": [{"letter": "A", "text": "Produjo el inicio de la migración rural-urbana."}, {"letter": "B", "text": "Provocó el abandono de las actividades primarias."}, {"letter": "C", "text": "Generó una gran dependencia económica en el país."}, {"letter": "D", "text": "Ocasionó una disminución de la diversidad económica."}], "correctAnswer": null}, {"number": 33, "axis": "Historia: Mundo, América y Chile", "text": "Analice las siguientes estrofas: “Cantemos la gloria del triunfo marcial que el pueblo chileno obtuvo en Yungay. ¡Oh, patria querida, que vidas tan caras, ahora en tus aras se van a inmolar! Su sangre vertida te da la victoria; su sangre, a tu gloria da un brillo inmortal. Con ella se vea ceñida la frente del héroe valiente del héroe sin par”. Zapiola, J., Himno a la Victoria de Yungay, 1839. El texto corresponde a un fragmento del Himno de la Victoria de Yungay. Este triunfo dio 14 término a la guerra contra la Confederación Perú-Boliviana. Considerando la fuente, ¿cuál es la importancia de esta victoria para el pueblo chileno?", "answers": [{"letter": "A", "text": "Estableció una oportunidad para expandir el territorio chileno y aumentar su influencia política en Sudamérica."}, {"letter": "B", "text": "Impactó negativamente en la economía chilena debido a los altos costos de la guerra y la destrucción de infraestructuras."}, {"letter": "C", "text": "Desencadenó una serie de conflictos internos en Chile debido a las disputas por el reconocimiento y recompensas entre los líderes militares."}, {"letter": "D", "text": "Generó la unidad y cohesión del pueblo chileno, reforzando el sentido de identidad nacional y la confianza en sus capacidades militares."}], "correctAnswer": null}, {"number": 34, "axis": "Historia: Mundo, América y Chile", "text": "A fines del siglo XIX Chile contaba con amplias reservas de salitre. Este nitrato, que era un fertilizante natural, también servía en la elaboración de pólvora, generó múltiples ingresos para la economía nacional. Considerando lo anterior, ¿cuál fue el desafío de los gobiernos chilenos que administraron los recursos salitreros?", "answers": [{"letter": "A", "text": "Ampliar los beneficios estatales en salud."}, {"letter": "B", "text": "Eliminar impuestos para fortalecer la industria."}, {"letter": "C", "text": "Aumentar la cobertura educacional universitaria."}, {"letter": "D", "text": "Construir obras públicas para mejorar el transporte."}], "correctAnswer": null}, {"number": 35, "axis": "Historia: Mundo, América y Chile", "text": "Observe la siguiente imagen: Locomotora Copiapó. Memoria chilena. La imagen corresponde a la primera locomotora que unió la ciudad de Copiapó con el puerto de Caldera. Tras la observación de la fotografía, ¿cuál es una inferencia válida?", "answers": [{"letter": "A", "text": "El ferrocarril favoreció el turismo en el país. 15"}, {"letter": "B", "text": "La llegada de locomotora fue un hito tecnológico."}, {"letter": "C", "text": "El transporte ferroviario restringió el trabajo humano."}, {"letter": "D", "text": "La línea férrea fue construida por obreros extranjeros."}], "correctAnswer": null}, {"number": 36, "axis": "Historia: Mundo, América y Chile", "text": "Al comparar la economía del periodo de la organización de la República (1823-1830) con la estructura económica del Chile finisecular, se pueden identificar elementos de continuidad y cambio. Con respecto a lo anterior, ¿qué elemento de continuidad en el ámbito económico se aprecia en ambos periodos?", "answers": [{"letter": "A", "text": "El intervencionismo por parte del Estado en el sistema financiero chileno."}, {"letter": "B", "text": "El desarrollo de una explosiva agroindustria en la zona centro-sur del país."}, {"letter": "C", "text": "La exportación de materias primas provenientes de la agricultura y minería."}, {"letter": "D", "text": "La diversificación de la mano de obra de los sectores populares de la época."}], "correctAnswer": null}, {"number": 37, "axis": "Historia: Mundo, América y Chile", "text": "Durante la segunda mitad del siglo XIX, Chile experimentó un auge minero que tuvo un impacto significativo en su economía. La explotación de recursos minerales como el salitre, impulsó el desarrollo del país y atrajo inversiones extranjeras. Considerando lo anterior, ¿Cuál fue un fenómeno derivado de este proceso?", "answers": [{"letter": "A", "text": "El debilitamiento del sector financiero y bancario."}, {"letter": "B", "text": "El fortalecimiento de la industria textil y manufacturera."}, {"letter": "C", "text": "La disminución de la migración hacia la zona Norte de Chile."}, {"letter": "D", "text": "El aumento de la inversión en la infraestructura de transporte."}], "correctAnswer": null}, {"number": 38, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “Aunque hay discrepancias sobre su recepción en Chile, lo cual se explica también por los sucesos de la Guerra Civil del 91 que acaparó la atención nacional, no hay duda que los sectores eclesiásticos y quienes lideraban intelectualmente el Partido Conservador combinaron la influencia del documento pontificio con el temor al descontento social y a la irreligiosidad del socialismo, para tomar conciencia que la cuestión social ponía seriamente en jaque su hegemonía social y política”. Stuven, A.(2008), El primer catolicismo social ante la cuestión social: un momento en el proceso de consolidación nacional. En la reseña anterior la autora se refiere a la acogida de la encíclica papal Rerum Novarum (1891) por una parte de la elite chilena a fines del siglo XIX. A partir de su análisis, ¿qué posición asumieron los conservadores ante la problemática social?", "answers": [{"letter": "A", "text": "Incentivaron la participación de las altas autoridades de la Iglesia Católica en la política activa."}, {"letter": "B", "text": "Desestimaron la aplicación de la Doctrina Social de la Iglesia, por el impacto de la Guerra Civil de 1891."}, {"letter": "C", "text": "Rechazaron la adopción de los planteamientos papales frente al avance del socialismo y el ateísmo."}, {"letter": "D", "text": "Incorporaron la nueva doctrina de la Iglesia como estrategia para enfrentar un contexto sociopolítico adverso."}], "correctAnswer": null}, {"number": 39, "axis": "Historia: Mundo, América y Chile", "text": "Analice el siguiente texto: “Tal vez en ningún pueblo moderno hay entre las clases opulentas y las menesterosas una distancia tan grande como en Chile; y lo más grave es que esa distancia va aumentando día por día. La situación originada por la guerra del 79, cuyo influjo hasta ahora estamos recibiendo, ha hecho cuadriplicarse la riqueza de las unas a expensas de las otras; y aunque nos salte a los ojos la miseria de los proletarios, no queremos verla, y si la vemos nos lavamos las manos diciendo – ellos tienen la culpa, porque son flojos, borrachos, mentirosos y ladrones – […] Dr. Julio Valdés Cange, Cartas al Excelentísimo Señor Don Pedro Montt, 1909 El texto anterior hace referencia a la Cuestión Social en Chile. Considerando la descripción del autor, ¿Qué se puede inferir sobre este fenómeno en el país?", "answers": [{"letter": "A", "text": "Nace a partir del crecimiento socioeconómico de la población."}, {"letter": "B", "text": "Existe dada la estabilidad económica en Chile durante el siglo XX."}, {"letter": "C", "text": "Refleja la desigualdad social y económica entre los grupos sociales."}, {"letter": "D", "text": "Ocurre por los vicios que afectan a las clases marginales de la sociedad."}], "correctAnswer": null}, {"number": 40, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “Aquella mañana se produjo una desaforada e inexplicable carrera por vender. El alud cayó sobre la Bolsa con fuerza torrencial. El mecanismo no podía adaptarse al pánico (…). En todo el país la gente no sabía lo que pasaba, solo que estaba arruinada o pronto lo estaría. La bancarrota dio al traste con la capacidad adquisitiva de los consumidores, con las inversiones en los negocios y con la solvencia de los bancos y las empresas. Después de la gran bancarrota, vino la Gran Depresión; primero, la eutanasia de los ricos, y después de los pobres. En 1933, casi la cuarta parte de todos los trabajadores norteamericanos estaban sin empleo…Tal vez se derrumbaba el capitalismo, y sería interesante verlo”. Galbraith, J. (1977), La era de la incertidumbre. La interpretación adjunta, describe algunas repercusiones del llamado “Jueves Negro” de octubre de 1929 en Estados Unidos. De acuerdo con el fragmento, ¿qué consecuencia tuvo dicho evento económico?", "answers": [{"letter": "A", "text": "El surgimiento de modelos económicos con protagonismo estatal."}, {"letter": "B", "text": "El abandono del capitalismo por parte de las economías mundiales."}, {"letter": "C", "text": "El desarrollo de un sentimiento de incertidumbre entre la población."}, {"letter": "D", "text": "El origen del Plan Marshall para el rescate de las economías europeas."}], "correctAnswer": null}, {"number": 41, "axis": "Historia: Mundo, América y Chile", "text": "La crisis económica de 1929 tuvo un impacto significativo en todo el mundo, incluyendo 17 los países de América Latina, que adoptaron medidas para hacer frente a la crisis y mitigar los efectos económicos y sociales. ¿Cuál de las siguientes opciones fue una medida adoptada por los países Latinoamericanos ante la crisis?", "answers": [{"letter": "A", "text": "Establecer alianzas militares para protegerse de posibles conflictos."}, {"letter": "B", "text": "Fomentar la industrialización sustitutiva y la diversificación económica."}, {"letter": "C", "text": "Implementar políticas de libre mercado reduciendo la intervención estatal."}, {"letter": "D", "text": "Ampliar las exportaciones de materias primas como base de sus economías."}], "correctAnswer": null}, {"number": 42, "axis": "Historia: Mundo, América y Chile", "text": "Durante el siglo XX, Europa fue testigo del surgimiento de varios regímenes totalitarios que impactaron en la sociedad. Ejemplos destacados de estos totalitarismos incluyen el nazismo en Alemania, el fascismo en Italia y el estalinismo en la Unión Soviética. ¿Cuál de las siguientes características fue común entre estos regímenes en el período de Entreguerras?", "answers": [{"letter": "A", "text": "El fomento de la pluralidad política y la participación ciudadana."}, {"letter": "B", "text": "La adopción de políticas económicas basadas en la propiedad privada."}, {"letter": "C", "text": "La promoción de la diversidad cultural y la tolerancia hacia minorías étnicas."}, {"letter": "D", "text": "El control estatal de los medios de comunicación para manipular información."}], "correctAnswer": null}, {"number": 43, "axis": "Historia: Mundo, América y Chile", "text": "Observe la siguiente propaganda: Arena, L., Alelí, (1953) Libros peronistas. Durante el siglo XX, varios países de América Latina experimentaron gobiernos populistas. Estos regímenes tuvieron un impacto significativo en la historia política y social en sus países. Considerando la imagen anterior, ¿qué característica del populismo se puede observar?", "answers": [{"letter": "A", "text": "La generación de un sentimiento nacionalista."}, {"letter": "B", "text": "La promoción de un liderazgo entre la población."}, {"letter": "C", "text": "La apertura económica hacia mercados externos."}, {"letter": "D", "text": "La redistribución de la riqueza entre los habitantes."}], "correctAnswer": null}, {"number": 44, "axis": "Historia: Mundo, América y Chile", "text": "En 1945, se creó la Organización de las Naciones Unidas (ONU), la cual amplió y profundizó la labor emprendida por su precursora, la Sociedad de las Naciones (1919). En este contexto, ¿qué objetivo perseguía consolidar esta organización?", "answers": [{"letter": "A", "text": "Preservar el patrimonio cultural y arqueológico de todos los países miembros."}, {"letter": "B", "text": "Establecer políticas migratorias globales para regular los flujos de migrantes entre los países."}, {"letter": "C", "text": "Promover la paz y la seguridad mundial fomentando la cooperación entre los países miembros."}, {"letter": "D", "text": "Fomentar el comercio internacional y promover la cooperación económica entre los países miembros."}], "correctAnswer": null}, {"number": 45, "axis": "Historia: Mundo, América y Chile", "text": "En 1948, la Asamblea General de las Naciones Unidas adoptó la Declaración Universal de los Derechos Humanos, un hito que ha influido en la legislación y las políticas en todo el mundo. ¿Cuál es una de las características del contexto geopolítico mundial en el que se creó esta declaración?", "answers": [{"letter": "A", "text": "La confrontación entre Estados Unidos y la Unión Soviética, que buscaban ganar influencia en el escenario internacional."}, {"letter": "B", "text": "El surgimiento de movimientos de liberación nacional en diversas regiones, que buscaban independencia y autonomía frente al colonialismo y la opresión."}, {"letter": "C", "text": "La consolidación de bloques regionales, que buscaban la integración económica y la cooperación política entre países vecinos."}, {"letter": "D", "text": "La crueldad cometida durante la Segunda Guerra Mundial, que generaron una amplia conciencia sobre la importancia de prevenir futuros abusos."}], "correctAnswer": null}, {"number": 46, "axis": "Historia: Mundo, América y Chile", "text": "Después de la Segunda Guerra Mundial, Asia y África comenzaron a luchar por su independencia y buscaron poner fin al dominio colonial de las potencias europeas. Este proceso de descolonización transformó el mapa político del mundo y tuvo un impacto duradero en las relaciones internacionales. En relación con el contexto, ¿cuál de las siguientes alternativas describe una consecuencia de la descolonización de Asia y África?", "answers": [{"letter": "A", "text": "Repercutió en una dependencia económica continua de los antiguos países 19 colonizadores."}, {"letter": "B", "text": "Llevó a la total eliminación de las influencias culturales y lingüísticas europeas en Asia y África."}, {"letter": "C", "text": "Resultó en la creación de sociedades completamente homogéneas y sin conflictos étnicos."}, {"letter": "D", "text": "Permitió a los países recién independizados establecer sus propias políticas y modelos de desarrollo."}], "correctAnswer": null}, {"number": 47, "axis": "Historia: Mundo, América y Chile", "text": "A mitad del siglo XX en Chile, se experimenta un incremento en la población debido al rápido proceso de urbanización y redistribución territorial, lo cual genera una nueva dinámica social. Al respecto, ¿cuál es el principal factor que influye en el aumento de la población?", "answers": [{"letter": "A", "text": "El aumento de la tasa de natalidad debido a mejoras en la atención médica y acceso a servicios de salud"}, {"letter": "B", "text": "La migración interna de las zonas rurales a las áreas urbanas en busca de mejores oportunidades económicas y de empleo."}, {"letter": "C", "text": "El impacto de la migración internacional hacia Chile, con personas provenientes de otros países buscando nuevas oportunidades."}, {"letter": "D", "text": "La implementación de políticas de planificación familiar que fomentaron el control de la natalidad y la disminución de la población infantil."}], "correctAnswer": null}, {"number": 48, "axis": "Historia: Mundo, América y Chile", "text": "Las poblaciones informales, conocidas como poblaciones callampas, fueron asentamientos populares que surgieron en Santiago durante el siglo XX debido al intenso flujo migratorio. Con relación a esto, ¿cuáles eran las características distintivas de este tipo de viviendas?", "answers": [{"letter": "A", "text": "Eran asentamientos planificados por grandes empresas con viviendas de calidad."}, {"letter": "B", "text": "Eran viviendas precarias, construidas con materiales improvisados como cartón, latas y madera."}, {"letter": "C", "text": "Eran espacios de viviendas sociales construidas por el gobierno, ofreciendo servicios básicos a precios asequibles."}, {"letter": "D", "text": "Eran barriadas usadas por migrantes extranjeros, con viviendas construidas siguiendo los estilos de sus países de origen."}], "correctAnswer": null}, {"number": 49, "axis": "Historia: Mundo, América y Chile", "text": "Durante 1975, las dictaduras militares de Sudamérica implementaron un plan de coordinación y apoyo mutuo conocido como el Plan Cóndor. Este plan clandestino buscaba perseguir y eliminar a opositores políticos en toda la región, llevando a cabo operaciones de inteligencia y represión transnacionales bajo la lógica de la Guerra Fría. Considerando lo anterior, ¿cuál de las siguientes alternativas muestra la implicancia de Estados Unidos en el Plan Cóndor?", "answers": [{"letter": "A", "text": "Brindó apoyo logístico y financiero a las dictaduras. 20"}, {"letter": "B", "text": "Condenó públicamente el accionar de las dictaduras."}, {"letter": "C", "text": "Ofreció asistencia a los opositores políticos perseguidos."}, {"letter": "D", "text": "Desconoció la existencia del plan ignorando sus acciones."}], "correctAnswer": null}, {"number": 50, "axis": "Historia: Mundo, América y Chile", "text": "A mediados del siglo XX, la sociedad chilena había experimentado cambios significativos que mostraban una realidad diferente a la de las primeras décadas de este siglo. En este contexto, ¿cuál fue una de las características que tuvo esta nueva realidad?", "answers": [{"letter": "A", "text": "Experimentó una mayor equidad económica y social en comparación con las primeras décadas del siglo."}, {"letter": "B", "text": "Mostró una mayor diversidad cultural y étnica en comparación con las primeras décadas del siglo."}, {"letter": "C", "text": "Significó un retroceso en los derechos y libertades individuales en comparación con las primeras décadas del siglo."}, {"letter": "D", "text": "Promovió una mayor participación política de la mujer y conciencia ciudadana en comparación con las primeras décadas del siglo."}], "correctAnswer": null}, {"number": 51, "axis": "Historia: Mundo, América y Chile", "text": "En la década de 1960, Chile experimentó un periodo de intensa polarización política y social. Durante este tiempo, surgieron diferentes corrientes ideológicas y movimientos sociales que reflejaban las tensiones y divisiones en la sociedad chilena. ¿Cuál de los siguientes factores contribuyó a la polarización en Chile en este período?", "answers": [{"letter": "A", "text": "La ausencia de acuerdos entre las principales fuerzas políticas del país."}, {"letter": "B", "text": "La adopción de una economía de libre mercado que generó desigualdades."}, {"letter": "C", "text": "El fortalecimiento de un sistema político autoritario que restringió derechos."}, {"letter": "D", "text": "La participación de los obreros quienes frenaban el accionar de los gobiernos."}], "correctAnswer": null}, {"number": 52, "axis": "Historia: Mundo, América y Chile", "text": "Analice el siguiente texto: “Desde un comienzo, desde el día mismo del 11 de septiembre, el derrocamiento del gobierno de Allende y de la Unidad Popular aspiraba a ser algo más que un golpe de Estado […] Desde un inicio, por ende, saltan a la vista los dos aspectos cruciales que definen el régimen militar: su carácter en extremo represivo y anulador del disenso social y, por otra parte, la intención refundacional que lo anima a perpetuarse desde aquel día, pasando por tantos otros llegando a la actualidad, gracias a diversos reacomodos exitosos.” Correa, Sofía y otros, (2009) Historia del siglo XX chileno. El texto refiere a las intenciones detrás del Golpe de Estado de 1973. Tras el análisis de la 21 cita, ¿cuál fue uno de los objetivos de la Junta Militar al asumir el poder?", "answers": [{"letter": "A", "text": "Consolidar el poder a través de reformas económicas."}, {"letter": "B", "text": "Establecer un gobierno de transición hasta lograr el orden."}, {"letter": "C", "text": "Impulsar reformas sociales para mejorar la calidad de vida."}, {"letter": "D", "text": "Anular cualquier forma de oposición al régimen establecido."}], "correctAnswer": null}, {"number": 53, "axis": "Historia: Mundo, América y Chile", "text": "Durante la dictadura militar en Chile (1973-1990), se produjo una supresión del Estado de derecho. En este contexto, ¿cuál fue una de las principales consecuencias de la supresión del estado de derecho durante la dictadura militar en Chile?", "answers": [{"letter": "A", "text": "La aplicación de medidas de inclusión social con el objetivo de disminuir la brecha de desigualdad."}, {"letter": "B", "text": "El debilitamiento de las organizaciones sociales y sindicales limitando la participación ciudadana."}, {"letter": "C", "text": "La adopción de una Constitución actualizada con la participación de la ciudadanía en su elaboración."}, {"letter": "D", "text": "La implementación de la Ley de Amnistía que protegía a los funcionarios militares acusados de violaciones a los derechos humanos."}], "correctAnswer": null}, {"number": 54, "axis": "Historia: Mundo, América y Chile", "text": "Después del golpe militar de 1973 en Chile, liderado por Augusto Pinochet, se implementaron políticas económicas basadas en el neoliberalismo, inspiradas en la Escuela de Economía de Chicago y el pensamiento de Milton Friedman. Estas políticas tuvieron un profundo impacto en la economía y la sociedad chilena, transformando la forma en que se organizaban y operaban los sectores público y privado. Al respecto, ¿cuál de las siguientes opciones corresponde a una de las características que tuvo este sistema?", "answers": [{"letter": "A", "text": "La implementación de altos impuestos a las grandes fortunas y empresas para redistribuir la riqueza de manera equitativa."}, {"letter": "B", "text": "La regulación gubernamental estricta de los mercados y los precios para evitar la concentración de poder económico."}, {"letter": "C", "text": "La apertura económica a través de la liberalización del comercio y la eliminación de barreras arancelarias para fomentar la integración económica."}, {"letter": "D", "text": "La promoción de un fuerte Estado de Bienestar con programas sociales para garantizar la igualdad de oportunidades para todos los ciudadanos."}], "correctAnswer": null}, {"number": 55, "axis": "Historia: Mundo, América y Chile", "text": "En el período de la dictadura militar en Chile, la Vicaría de la Solidaridad llevó a cabo diversas acciones que tuvieron impacto en el desarrollo político y social del país. Considerando el contexto de la época, ¿cuál fue uno de los objetivos que perseguía esta organización?", "answers": [{"letter": "A", "text": "Justificar las decisiones de la dictadura militar en la nación."}, {"letter": "B", "text": "Promover la limitación y el control de la libertad de expresión."}, {"letter": "C", "text": "Proporcionar apoyo psicológico y jurídico a las víctimas de represión."}, {"letter": "D", "text": "Aplicar medidas económicas que promovieran la estabilidad del Estado."}], "correctAnswer": null}, {"number": 56, "axis": "Historia: Mundo, América y Chile", "text": "Durante el régimen dictatorial en Chile (1973-1990), ocurrieron múltiples violaciones a los derechos humanos. En este contexto, ¿de qué forma se sostuvo el carácter sistemático de vulneración de estos derechos?", "answers": [{"letter": "A", "text": "Al reconocer los crímenes de lesa humanidad cometidos y procesar a los responsables."}, {"letter": "B", "text": "Al generar un clima de miedo y silenciamiento de la oposición creando organismos de represión."}, {"letter": "C", "text": "Al consolidar un sistema de justicia independiente y transparente para denunciar los vejámenes."}, {"letter": "D", "text": "Al implementar políticas de reparación y compensación para las víctimas de violaciones de derechos humanos."}], "correctAnswer": null}, {"number": 57, "axis": "Historia: Mundo, América y Chile", "text": "En Chile, los partidos políticos fueron restablecidos en 1987, mediante una ley orgánica constitucional que establecía, a nivel general, que estas agrupaciones servían para encauzar la opinión pública y participar del ordenamiento político. En 1988, los partidos políticos se agruparon en torno a dos grandes coaliciones que se enfrentaron en el plebiscito del mismo año. Considerando los antecedentes expuestos, ¿cuál de las siguientes opciones explica la incapacidad de los partidos para funcionar previo a 1987?", "answers": [{"letter": "A", "text": "La desorganización de los dirigentes que sobrevivieron al golpe."}, {"letter": "B", "text": "La prohibición que impidió su funcionamiento después del golpe."}, {"letter": "C", "text": "El decreto firmado por Allende que ilegalizó a los partidos de derecha."}, {"letter": "D", "text": "El exilio de ciudadanos que formaban parte de los partidos tras el golpe."}], "correctAnswer": null}, {"number": 58, "axis": "Historia: Mundo, América y Chile", "text": "En 1988, Chile vivió un momento crucial en su historia con el plebiscito que determinó la continuidad de Augusto Pinochet en el poder. Este evento marcó un hito en la transición política del país. ¿Cuál es una característica de este proceso?", "answers": [{"letter": "A", "text": "Se organizó desde el exterior por un organismo internacional, asegurando un proceso electoral justo y transparente."}, {"letter": "B", "text": "Se impulsaron cambios estructurales significativos en la economía chilena para impulsar el desarrollo y el bienestar social."}, {"letter": "C", "text": "Se permitió la participación de partidos políticos y organizaciones sociales en la 23 campaña, lo que garantizó un proceso democrático y justo."}, {"letter": "D", "text": "Se realizó tras un proceso de justicia que castigo a los responsables de violaciones a los derechos humanos."}], "correctAnswer": null}, {"number": 59, "axis": "Sistema Económico", "text": "En las últimas décadas, la evasión tributaria ha sido un tema relevante en Chile, generando debates sobre su impacto en la economía del país y la distribución de recursos. ¿Cuál de las siguientes afirmaciones describe mejor la relación entre la evasión tributaria y la sociedad chilena?", "answers": [{"letter": "A", "text": "Es una práctica común y aceptada culturalmente en Chile, lo que ha llevado a un deterioro en la calidad de los servicios públicos."}, {"letter": "B", "text": "Es un fenómeno minoritario en Chile y no afecta de manera relevante la economía del país ni la distribución de recursos."}, {"letter": "C", "text": "Es un tema insignificante en el contexto chileno, ya que el Estado tiene otras fuentes de financiamiento para los servicios públicos."}, {"letter": "D", "text": "Es un problema estructural en Chile que contribuye a la desigualdad y limita la capacidad del Estado para financiar políticas sociales."}], "correctAnswer": null}, {"number": 60, "axis": "Sistema Económico", "text": "Lea la siguiente noticia sobre el alza de precios en Argentina: “El alza de precios golpea a los sectores de bajos recursos y empuja la línea de la pobreza. En el país de los alimentos, comer cuesta cada vez más. Tres consultoras privadas argentinas, a falta de números oficiales, calcularon desde enero alzas de entre 12 y 13 puntos en la canasta básica de alimentos, una construcción estadística que sirve para 24 medir la pobreza y la indigencia. (…) El escenario no podría ser peor para las aspiraciones del gobierno de Mauricio Macri de cerrar el año con una inflación no mayor al 25 %. Sobre todo, por la presión extra que ejercerá, junto con los alimentos, el aumento en hasta 300 % de servicios públicos como electricidad, agua, gas y transporte.” Diario El País, 7 de abril de 2016. La canasta básica de alimentos en Argentina sube 13%. Considerando lo informado en la noticia ¿Qué fenómeno económico se asocia a la descripción presentada?", "answers": [{"letter": "A", "text": "La devaluación de la moneda argentina que provoca pérdidas para el país."}, {"letter": "B", "text": "Un proceso inflacionario que disminuye el poder adquisitivo de la población."}, {"letter": "C", "text": "Un cambio en los gustos de la población que preferirá la producción exterior."}, {"letter": "D", "text": "El aumento de los costos de producción que genera desempleo a nivel global."}], "correctAnswer": null}, {"number": 61, "axis": "Sistema Económico", "text": "La inflación es un fenómeno económico que se caracteriza por el aumento generalizado y sostenido de los precios de bienes y servicios en un país. En el caso de Chile, la inflación ha sido un tema relevante en diferentes momentos de su historia económica, con implicaciones en el poder adquisitivo de la población y la estabilidad macroeconómica. Considerando lo anterior, ¿cuál de las siguientes medidas es considerada una estrategia comúnmente utilizada para controlar la inflación?", "answers": [{"letter": "A", "text": "Aumentar el sueldo base de la población a nivel general."}, {"letter": "B", "text": "Establecer políticas de subsidios directos hacia la población."}, {"letter": "C", "text": "Fomentar la inversión extranjera y el libre comercio internacional."}, {"letter": "D", "text": "Incrementar las tasas de interés para disminuir el dinero circulante."}], "correctAnswer": null}, {"number": 62, "axis": "Sistema Económico", "text": "En un mercado, actúan factores de diversa índole que influyen en la oferta y demanda, afectando el precio de los bienes y servicios. Considerando lo anterior, ¿Cuál de los siguientes factores disminuye la demanda de un producto?", "answers": [{"letter": "A", "text": "Un incremento en el stock disponible."}, {"letter": "B", "text": "Un alza significativa en el precio de venta."}, {"letter": "C", "text": "Un aumento en la población consumidora."}, {"letter": "D", "text": "Una disminución en los costos de producción."}], "correctAnswer": null}, {"number": 63, "axis": "Sistema Económico", "text": "En el contexto económico, las externalidades son efectos positivos o negativos que una actividad económica genera en terceros y que no están reflejados en los precios de mercado. Estas externalidades pueden tener impactos sociales, ambientales o económicos, y pueden generar situaciones de beneficio o perjuicio para la sociedad en su conjunto. Al respecto, ¿cuál de las siguientes afirmaciones ejemplifica una externalidad negativa en el mercado económico?", "answers": [{"letter": "A", "text": "La inversión en tecnologías limpias para reducir la contaminación ambiental de una ciudad."}, {"letter": "B", "text": "La emisión de gases tóxicos por parte de una fábrica que afecta la salud de los residentes cercanos."}, {"letter": "C", "text": "El desarrollo de programas de responsabilidad social empresarial en beneficio de comunidades locales."}, {"letter": "D", "text": "La construcción de parques y áreas verdes en una ciudad para el disfrute de la comunidad por parte de una industria forestal."}], "correctAnswer": null}, {"number": 64, "axis": "Sistema Económico", "text": "Los bienes son aquellos objetos tangibles que se disponen para el consumo de la población. Sobre la base de lo anterior ¿Cuál de las siguientes situaciones ejemplifica la oferta de bienes en un mercado?", "answers": [{"letter": "A", "text": "Un abogado ofrece servicios legales a sus clientes."}, {"letter": "B", "text": "Un profesor imparte clases de matemáticas a sus alumnos."}, {"letter": "C", "text": "Un agricultor entrega su cosecha de tomates a un supermercado local."}, {"letter": "D", "text": "Un músico compone una canción y la sube a una plataforma de streaming."}], "correctAnswer": null}, {"number": 65, "axis": "Sistema Económico", "text": "Chile hoy cuenta con un sistema de protección laboral que es resultado de un largo proceso en el que la ciudadanía y la clase política, han sido actores fundamentales. Sobre la base de lo anterior, ¿cuál de los siguientes constituye un antecedente de los derechos laborales que existen en el país?", "answers": [{"letter": "A", "text": "El accionar de los gremios empresariales."}, {"letter": "B", "text": "El incremento de los beneficios salariales."}, {"letter": "C", "text": "Las propuestas de la Sociedad de fomento."}, {"letter": "D", "text": "Las demandas surgidas desde los sindicatos."}], "correctAnswer": null}], "3": [{"number": 1, "axis": "Formación Ciudadana", "text": "Lea el siguiente texto: “Ambos procesos –el de negación de la identidad y existencia de los pueblos indígenas a favor de la formación de una identidad nacional única, y el de apropiación de su territorio a favor de la consolidación del territorio nacional– si bien fueron exitosos en su objetivo de servir a la formación del Estado-nación chileno, tuvieron consecuencias que se arrastran hasta el presente”. Informe Comisión Verdad y Nuevo Trato con los pueblos indígenas. El texto expresa características del proceso de incorporación de las etnias indígenas en la formación del Estado-Nación. En relación con ello ¿cuál de las siguientes resume el vínculo de las comunidades indígenas con el Estado chileno?", "answers": [{"letter": "A", "text": "La participación de los pueblos originarios dentro del Estado."}, {"letter": "B", "text": "La conservación de sus territorios ancestrales dentro del Estado."}, {"letter": "C", "text": "La valoración del aporte cultural indígena en la formación del Estado."}, {"letter": "D", "text": "La desvalorización de la raíz indígena en beneficio de la unidad estatal."}], "correctAnswer": null}, {"number": 2, "axis": "Formación Ciudadana", "text": "Chile se reconoce como un país democrático, donde la participación de la sociedad es fundamental para elegir a sus representantes. En este contexto, cada cuatro años se realizan 2 elecciones presidenciales. ¿Cuál de los siguientes elementos corresponde a una facultad de la ciudadanía en dicho proceso electoral?", "answers": [{"letter": "A", "text": "Proponer candidatos que representara cada sector político."}, {"letter": "B", "text": "Elegir de manera libre a un representante mediante el sufragio."}, {"letter": "C", "text": "Organizar las mesas de votación del sistema electoral del país."}, {"letter": "D", "text": "Elaborar informes sobre los recursos utilizado en las campañas."}], "correctAnswer": null}, {"number": 3, "axis": "Formación Ciudadana", "text": "Los tratados internacionales son considerados uno de los mecanismos más importantes en el resguardo de los derechos esenciales de los individuos. ¿Qué implica el hecho de que Chile ratifique dichos tratados?", "answers": [{"letter": "A", "text": "Que disminuyen las diferencias programáticas entre los partidos políticos."}, {"letter": "B", "text": "Que consolidan el progreso económico de los sectores vulnerables del país."}, {"letter": "C", "text": "Que se integran al sistema jurídico del país alcanzando rango constitucional."}, {"letter": "D", "text": "Que son válidos en la medida que aborden simplemente derechos esenciales."}], "correctAnswer": null}, {"number": 4, "axis": "Formación Ciudadana", "text": "La República de Chile ha desarrollado una serie de modificaciones desde su formación, como república independiente, hasta el día de hoy, manteniendo como principio fundamental la democracia. En base a lo anterior, ¿cuál de las siguientes afirmaciones es un principio de la democracia chilena?", "answers": [{"letter": "A", "text": "La existencia de un congreso unicameral."}, {"letter": "B", "text": "La constitución de un Estado confesional."}, {"letter": "C", "text": "El reconocimiento de derechos y libertades."}, {"letter": "D", "text": "El predominio femenino en política nacional."}], "correctAnswer": null}, {"number": 5, "axis": "Formación Ciudadana", "text": "En el Chile contemporáneo persisten varios pueblos indígenas a pesar de que, durante la historia nacional, se les impuso una lengua y religión, se erradicaron sus prácticas de subsistencia y expropiaron sus tierras. Considerando los antecedentes expuestos y los tratados internacionales suscritos por el país en materia de derechos indígenas, ¿cuál de las siguientes constituye un desafío para el Estado de Chile en relación con sus pueblos indígenas?", "answers": [{"letter": "A", "text": "Designar a autoridades indígenas como ministros de Estado."}, {"letter": "B", "text": "Entregar tierras a familias indígenas que vistan trajes típicos."}, {"letter": "C", "text": "Imponer, en la Araucanía, el mapudungun como lengua oficial."}, {"letter": "D", "text": "Aumentar la representación indígena en las decisiones políticas. 3"}], "correctAnswer": null}, {"number": 6, "axis": "Formación Ciudadana", "text": "En la mayoría de las naciones occidentales, como Chile, los regímenes políticos democráticos son los predominantes, aunque con particularidades de acuerdo con las leyes fundamentales de cada Estado. Sin embargo, ¿qué principio básico es compartido por todos esos regímenes?", "answers": [{"letter": "A", "text": "La existencia de dos partidos políticos."}, {"letter": "B", "text": "La elección periódica de representantes."}, {"letter": "C", "text": "La subordinación del individuo al Estado."}, {"letter": "D", "text": "La incorporación de la oposición al Gobierno."}], "correctAnswer": null}, {"number": 7, "axis": "Formación Ciudadana", "text": "Lea el siguiente texto: “Prácticamente todas las actividades socioeconómicas están vinculadas al clima. Algunas de ellas, como la agricultura o el sector forestal, presentan una dependencia directa, ya que el clima determina la existencia de recursos energéticos y físicos primarios. En otros casos, los recursos hídricos juegan un papel de gran relevancia, de tal forma que los impactos que el cambio climático tenga sobre la oferta hidrológica dan lugar a consecuencias en cascada que repercuten finalmente en las actividades económicas que se benefician de ellos”. CEPAL (2009). Economía del cambio climático en Chile. A partir del análisis del fragmento adjunto, ¿cómo repercutiría el cambio climático en las actividades productivas del país?", "answers": [{"letter": "A", "text": "Afectaría la producción minera del Norte Grande."}, {"letter": "B", "text": "Aumentaría la importancia productiva de las regiones."}, {"letter": "C", "text": "Reduciría los costos de la producción agrícola en los valles."}, {"letter": "D", "text": "Aseguraría la actividad silvícola del secano en la zona central"}], "correctAnswer": null}, {"number": 8, "axis": "Formación Ciudadana", "text": "Lea el siguiente texto: “En este sentido, un desafío del nuevo Instituto, que es también un desafío de las políticas de derechos humanos en los países del Cono Sur, consiste en articular la agenda de 4 derechos humanos relacionada con el legado del pasado autoritario, con una agenda más amplia, que dé cuenta de las nuevas demandas de derechos en los Estados democráticos”. INDH (2010) Discurso del primer informe anual del Instituto de Derechos Humanos de Chile. El Instituto Nacional de Derechos Humanos nació en 2009. Considerando el discurso, presentado, ¿cuál es uno de los objetivos de esta institución?", "answers": [{"letter": "A", "text": "Ampliar el aporte de los DDHH considerando nuevas demandas sociales."}, {"letter": "B", "text": "Reasignar la agenda actual de DDHH por sobre las demandas pendientes."}, {"letter": "C", "text": "Aplicar gradualidad a la implementación de libertades públicas y privadas."}, {"letter": "D", "text": "Restringir en una institución la protección de los derechos fundamentales."}], "correctAnswer": null}, {"number": 9, "axis": "Formación Ciudadana", "text": "El régimen democrático chileno se caracteriza por realizar elecciones periódicas, aceptar el pluripartidismo y respetar el Estado de Derecho. De acuerdo con lo anterior, ¿qué significa respetar el Estado de Derecho?", "answers": [{"letter": "A", "text": "Fomentar las tradiciones y costumbres del país."}, {"letter": "B", "text": "Contar con FFAA garantes de la institucionalidad."}, {"letter": "C", "text": "Valorar las políticas aplicadas por el gobierno de turno."}, {"letter": "D", "text": "Aplicar las leyes vigentes en el marco legal de la nación."}], "correctAnswer": null}, {"number": 10, "axis": "Formación Ciudadana", "text": "Se entiende por sistema electoral, al conjunto de normas que define la forma en que los ciudadanos eligen a las autoridades que los representarán en el Poder Ejecutivo y en el Legislativo. En este contexto, una de las principales críticas que se hizo al antiguo sistema binominal chileno radica en que", "answers": [{"letter": "A", "text": "generaba estabilidad política y gobernanza, pero requería de una nueva regulación."}, {"letter": "B", "text": "aseguraba la representación parlamentaria equitativa, pero necesitaba mejoras y modernizaciones."}, {"letter": "C", "text": "debían ampliarse los cupos para los candidatos que iban por coalición política y disminuirse los de candidatos independientes."}, {"letter": "D", "text": "impedía una correcta representación de las fuerzas políticas del país, proporcional a los votos que obtenían en los comicios."}], "correctAnswer": null}, {"number": 11, "axis": "Formación Ciudadana", "text": "La participación ciudadana es uno de los pilares fundamentales del sistema democrático en Chile que promueve la intervención de organizaciones sociales en el diseño de políticas públicas nacionales o locales como también la libre opinión sobre asuntos políticos, sin embargo, cuenta con restricciones entre las que destaca", "answers": [{"letter": "A", "text": "ser menor de edad."}, {"letter": "B", "text": "pertenecer a las FFAA."}, {"letter": "C", "text": "administrar una empresa. 5"}, {"letter": "D", "text": "militar en un partido político."}], "correctAnswer": null}, {"number": 12, "axis": "Formación Ciudadana", "text": "Las cifras de participación electoral, en la última década, se han ido debilitando. Si a principios de los años noventa votaba el 90% del padrón electoral, hacia fines del 2017 votó solo el 50% de los ciudadanos con derecho a voto. En este contexto de alta abstención electoral, los partidos políticos tienen el gran desafío de", "answers": [{"letter": "A", "text": "generar programas que incorporen las necesidades ciudadanas."}, {"letter": "B", "text": "aumentar el número de adherentes para mantenerse en el sistema."}, {"letter": "C", "text": "ofrecer servicios sociales gratuitos para incorporar a los desposeídos."}, {"letter": "D", "text": "representar a un grupo seleccionado de personas con la misma ideología."}], "correctAnswer": null}, {"number": 13, "axis": "Formación Ciudadana", "text": "La participación ciudadana se expresa de diferentes formas en la vida democrática, entre las que destaca la movilización popular, donde cientos de personas salen a las calles a exponer sus demandas. Considerando los eventos de los últimos años ¿cuál es el desafío de la institucionalidad democrática chilena?", "answers": [{"letter": "A", "text": "Lograr la equidad económica en todos los grupos sociales del país."}, {"letter": "B", "text": "Permitir el control estatal en aspectos privados de la sociedad chilena."}, {"letter": "C", "text": "Reducir los cargos de elección popular en los distintos poderes del Estado."}, {"letter": "D", "text": "Fortalecer los derechos de las personas que habitan en el territorio nacional."}], "correctAnswer": null}, {"number": 14, "axis": "Formación Ciudadana", "text": "Para que la democracia en Chile sea efectiva requiere que los ciudadanos adquieran compromisos y responsabilidades. En este aspecto, ¿cuál es un ejemplo de compromiso ciudadano?", "answers": [{"letter": "A", "text": "Rechazar las posturas políticas contrarias."}, {"letter": "B", "text": "Excluir a quienes no tienen derecho a voto."}, {"letter": "C", "text": "Generar espacios de diálogo en sus barrios."}, {"letter": "D", "text": "Integrar alguna rama de las Fuerzas Armadas."}], "correctAnswer": null}, {"number": 15, "axis": "Formación Ciudadana", "text": "El Estado es la unidad política representante de la nación cuyo objetivo es alcanzar el bien común. Considerando la finalidad del Estado, ¿Qué acción debe propiciar esta entidad?", "answers": [{"letter": "A", "text": "Fomentar el uso de la fuerza a nivel internacional."}, {"letter": "B", "text": "Establecer valores morales para la vida en sociedad."}, {"letter": "C", "text": "Intervenir en asuntos civiles de la población nacional."}, {"letter": "D", "text": "Aplicar políticas que mejoren la vida de los ciudadanos."}], "correctAnswer": null}, {"number": 16, "axis": "Formación Ciudadana", "text": "Actualmente en Chile, los distintos establecimientos educativos generan instancias de participación ciudadana, por ejemplo, mediante la construcción de centro de estudiantes, elecciones de directivo de curso, elecciones de centro de padres. Entre los aspectos positivos de estas prácticas para la formación ciudadana podemos señalar que 6", "answers": [{"letter": "A", "text": "desarrolla formas de organización para la vida en sociedad."}, {"letter": "B", "text": "incrementa las desigualdades sociales entre los estudiantes."}, {"letter": "C", "text": "genera un mayor reconocimiento económico para las escuelas."}, {"letter": "D", "text": "permite mejores resultados de evaluación para los estudiantes."}], "correctAnswer": null}, {"number": 17, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “La metrópoli abandona los pueblos de América a la más espantosa ignorancia, ni cuida de su ilustración, ni de los establecimientos útiles para su prosperidad: cuida también, de destruirlos cuando puede; y cuando tienen agotadas y destruidas las provincias con los impuestos y contribuciones exorbitantes, y con el comercio de monopolio, quiere que hasta los institutos de caridad, y todo cuanto se haga, sea a costa de los miserables pueblos, porque los tesoros que se arrancan de nosotros por medio de las exacciones fiscales solo deben servir para dotar magníficamente empleados europeos, para pagar soldados que nos opriman, y para enriquecer la Metrópoli y los favoritos”. José Amor de la Patria (1810) Catecismo Político Cristiano. El “Catecismo Político Cristiano” fue un manuscrito que circuló meses antes de la convocatoria al Cabildo Abierto de 1810. De acuerdo con su análisis, ¿qué refleja el texto adjunto?", "answers": [{"letter": "A", "text": "El deseo independentista de la mayoría de la elite criolla."}, {"letter": "B", "text": "La posición colonialista para todos los pueblos americanos."}, {"letter": "C", "text": "El descontento de una parte de la sociedad con el sistema colonial."}, {"letter": "D", "text": "Los beneficios que se obtendrían con una monarquía constitucional. 7"}], "correctAnswer": null}, {"number": 18, "axis": "Historia: Mundo, América y Chile", "text": "Adam Smith, a fines del siglo XVIII, redactó “La Riqueza de las Naciones”, que contiene los principios económicos que permitieron a la burguesía europea del siglo XIX aumentar y consolidar sus riquezas. Considerado la propuesta de Smith, ¿cuál de las siguientes corresponde a una idea económica?", "answers": [{"letter": "A", "text": "La libre empresa es fundamental para el crecimiento económico."}, {"letter": "B", "text": "La propiedad privada es un obstáculo para el desarrollo económico."}, {"letter": "C", "text": "El Estado debe intervenir en la economía para asegurar la justicia social."}, {"letter": "D", "text": "La planificación centralizada es la mejor manera de aumentar la riqueza."}], "correctAnswer": null}, {"number": 19, "axis": "Historia: Mundo, América y Chile", "text": "La “Paz Armada” (1870-1914) fue una época caracterizada por el incremento del gasto público en armamentos, adoptado por las principales potencias imperialistas. En este sentido, ¿qué otra característica tuvo dicho período?", "answers": [{"letter": "A", "text": "La disminución de las tensiones políticas en los Balcanes."}, {"letter": "B", "text": "El aumento de la influencia rusa en las colonias británicas."}, {"letter": "C", "text": "La formación de bloques militares en el continente europeo."}, {"letter": "D", "text": "El debilitamiento de la industrialización en Francia y Reino Unido."}], "correctAnswer": null}, {"number": 20, "axis": "Historia: Mundo, América y Chile", "text": "Analice la siguiente caricatura: Le Petit Journal (1885) China, pastel de reyes y emperadores. La caricatura, publicada en una revista francesa en 1885, hace referencia al imperialismo que se gestó en la segunda mitad del siglo XIX a nivel mundial. Considerando la escena, ¿cuál es una de las características del imperialismo?", "answers": [{"letter": "A", "text": "Es un fenómeno que contribuye al progreso."}, {"letter": "B", "text": "En una etapa que promueve progreso económico."}, {"letter": "C", "text": "Es un proceso que genera conflictos entre los países."}, {"letter": "D", "text": "Es un sistema que amplía el comercio entre las naciones."}], "correctAnswer": null}, {"number": 21, "axis": "Historia: Mundo, América y Chile", "text": "Durante los siglos XIX y XX, algunas naciones europeas desarrollaron un proceso de expansión territorial conocido como imperialismo. Con relación a este proceso histórico, ¿cuál fue una de sus características?", "answers": [{"letter": "A", "text": "El liderazgo político económico de Estados Unidos en el mundo."}, {"letter": "B", "text": "El uso de medios de transportes que permitieron la conexión global."}, {"letter": "C", "text": "El deseo europeo de mejorar la vida de los habitantes de las colonias."}, {"letter": "D", "text": "El respeto demostrado por lo europeos hacia las culturas colonizadas."}], "correctAnswer": null}, {"number": 22, "axis": "Historia: Mundo, América y Chile", "text": "La independencia de Hispanoamérica, ocurrida en las primeras décadas del siglo XIX, tiene sus orígenes en un conjunto de factores de distinta naturaleza. En relación con ello, ¿cuál de las siguientes opciones alude a una causa estructural interna de dicho proceso?", "answers": [{"letter": "A", "text": "El malestar de los criollos con la administración colonial."}, {"letter": "B", "text": "La ausencia de autoridad legítima en la Corona española."}, {"letter": "C", "text": "La respuesta política en España a la invasión napoleónica."}, {"letter": "D", "text": "La emancipación de las colonias inglesas en Norteamérica."}], "correctAnswer": null}, {"number": 23, "axis": "Historia: Mundo, América y Chile", "text": "Posterior al proceso de independencia, varios sectores políticos manifestaron sus planteamientos en torno a la organización de la república en Chile, uno de estos grupos fueron los “federalistas”, ¿cuál es una de las propuestas de este sector político?", "answers": [{"letter": "A", "text": "La conformación de un gobierno impersonal."}, {"letter": "B", "text": "La influencia de la Iglesia católica en política."}, {"letter": "C", "text": "El establecimiento de un gobierno autoritario."}, {"letter": "D", "text": "La instalación de un gobierno descentralizado."}], "correctAnswer": null}, {"number": 24, "axis": "Historia: Mundo, América y Chile", "text": "En el período de la organización republicana en Chile, entre 1823 y 1830, se elaboraron constituciones de corta vigencia. De las siguientes alternativas, ¿cuál fue el principal objetivo con la promulgación de estas normativas? 9", "answers": [{"letter": "A", "text": "Organizar y desarrollar la economía nacional."}, {"letter": "B", "text": "Reconocer al catolicismo como religión oficial."}, {"letter": "C", "text": "Instaurar una democracia social y participativa."}, {"letter": "D", "text": "Asegurar la soberanía nacional sobre el territorio."}], "correctAnswer": null}, {"number": 25, "axis": "Historia: Mundo, América y Chile", "text": "En los primeros años de vida independiente, los dos grupos más importantes de la elite nacional, liberales y conservadores se enfrentaron para diseñar la estructura política del país. En 1829 los conservadores lograron imponerse a los liberales tras una guerra civil, lo que les permitió redactar una constitución que representó sus ideales políticos. ¿Cuál de las siguientes alternativas representa una característica de la constitución de 1833?", "answers": [{"letter": "A", "text": "Propone una democracia directa."}, {"letter": "B", "text": "Fortalece el rol del congreso nacional."}, {"letter": "C", "text": "Instala un sistema político participativo."}, {"letter": "D", "text": "Establece un régimen presidencial autoritario."}], "correctAnswer": null}, {"number": 26, "axis": "Historia: Mundo, América y Chile", "text": "Al comparar el período colonial en Chile con la instalación de un modelo republicano, se observan elementos de continuidad, pero también de cambio. Según lo anterior, ¿qué elemento de cambio histórico se aprecia entre ambas etapas?", "answers": [{"letter": "A", "text": "La hegemonía del pensamiento católico."}, {"letter": "B", "text": "La separación de los poderes del Estado."}, {"letter": "C", "text": "El establecimiento de un sistema autoritario."}, {"letter": "D", "text": "El predominio de la aristocracia en la sociedad."}], "correctAnswer": null}, {"number": 27, "axis": "Historia: Mundo, América y Chile", "text": "La agricultura fue fundamental en el proceso de inserción de la economía chilena al capitalismo, producido hacia mediados del siglo XIX. En relación con ello, ¿cuál de las siguientes situaciones contribuyó al auge de esa actividad económica?", "answers": [{"letter": "A", "text": "La presencia de medios de transporte tradicionales."}, {"letter": "B", "text": "La apertura de mercados consumidores de cereales."}, {"letter": "C", "text": "La transformación en torno a la propiedad del campo."}, {"letter": "D", "text": "La mecanización de la siembra y la cosecha de frutas."}], "correctAnswer": null}, {"number": 28, "axis": "Historia: Mundo, América y Chile", "text": "La expansión del liberalismo en Europa se sintió también en América y en Chile. En este sentido, en la segunda mitad del siglo XIX, en el país se vivieron una serie de conflictos de carácter político-religioso, en los cuales se enfrentaron los liberales y los conservadores. 10 Entre las situaciones que contribuyeron al conflicto entre ambos grupos destaca", "answers": [{"letter": "A", "text": "la negativa de los sectores católicos a aceptar la libertad de culto."}, {"letter": "B", "text": "la promoción de la libertad de enseñanza por parte de los liberales."}, {"letter": "C", "text": "la aceptación generalizada de la Iglesia con respecto al matrimonio civil."}, {"letter": "D", "text": "el impulso al Estado laico planteado por los intelectuales conservadores."}], "correctAnswer": null}, {"number": 29, "axis": "Historia: Mundo, América y Chile", "text": "Durante el gobierno de Federico Errázuriz Zañartu (1871-1876) se produjo el quiebre de la Fusión Liberal-Conservadora, originado por las diferencias ideológicas entre los grupos que integraban esa coalición. Estas tensiones se relacionaron con las llamadas “cuestiones doctrinarias”, que incluían el debate en torno a la educación. ¿Cuál era el planteamiento de los conservadores con respecto a esa discusión?", "answers": [{"letter": "A", "text": "La defensa del principio de libertad de enseñanza."}, {"letter": "B", "text": "El respaldo a la laicización de la educación primaria."}, {"letter": "C", "text": "El rechazo a la incorporación de mujeres en la docencia."}, {"letter": "D", "text": "El fortalecimiento del rol del Estado en materia educacional."}], "correctAnswer": null}, {"number": 30, "axis": "Historia: Mundo, América y Chile", "text": "¿Cuál de las siguientes opciones resume la principal transformación política llevada a cabo por los Gobiernos liberales de la segunda mitad del siglo XIX en Chile?", "answers": [{"letter": "A", "text": "La consolidación del sufragio censitario."}, {"letter": "B", "text": "La participación del Estado en la economía."}, {"letter": "C", "text": "El incremento de las facultades del Poder Legislativo."}, {"letter": "D", "text": "El bloqueo a la participación de las clases populares."}], "correctAnswer": null}, {"number": 31, "axis": "Historia: Mundo, América y Chile", "text": "En Chile, durante la segunda mitad del siglo XIX, la problemática política entre el Estado y la Iglesia giraba en torno a las llamadas “cuestiones doctrinarias”. Esta discusión llevó al gobierno de Domingo Santa María a promulgar las llamadas Leyes Laicas, que provocaron", "answers": [{"letter": "A", "text": "el avance de la secularización de las instituciones."}, {"letter": "B", "text": "la reducción de las atribuciones del Estado hacia la Iglesia."}, {"letter": "C", "text": "la masificación de las ideas de los sectores conservadores."}, {"letter": "D", "text": "el fin del conflicto entre autoridades eclesiásticas y estatales."}], "correctAnswer": null}, {"number": 32, "axis": "Historia: Mundo, América y Chile", "text": "Desde mediados del siglo XIX, Chile comenzó un proceso de inserción en la economía global, utilizando un modelo primario exportador. De acuerdo con lo anterior, ¿cuál de las siguientes afirmaciones explica la inserción temprana del país en la economía mundial?", "answers": [{"letter": "A", "text": "La dotación de recursos naturales de alta importancia."}, {"letter": "B", "text": "La fuerte inversión del Estado en el sistema productivo."}, {"letter": "C", "text": "Las estrictas regulaciones existentes en materia laboral."}, {"letter": "D", "text": "El importante contingente tecnológico presente en Chile."}], "correctAnswer": null}, {"number": 33, "axis": "Historia: Mundo, América y Chile", "text": "La primera mitad del siglo XIX, en Chile, se caracterizó por la llegada de comerciantes extranjeros, el auge de la minería argentífera en el Norte Chico, el nacimiento de la Sociedad Nacional de Agricultura y las exportaciones de trigo hacia Australia y California. Al respecto, el proceso que posibilitó dichos sucesos fue la", "answers": [{"letter": "A", "text": "modernización del sector agropecuario en el país."}, {"letter": "B", "text": "exportación de materias primas chilenas al exterior."}, {"letter": "C", "text": "formación de una infraestructura económica avanzada."}, {"letter": "D", "text": "aplicación de técnicas industriales en el sector agrícola."}], "correctAnswer": null}, {"number": 34, "axis": "Historia: Mundo, América y Chile", "text": "Durante la primera mitad del siglo XIX, se generó en Chile un profundo proceso de crecimiento económico, que se vio complementado, entre otras cosas, por la implementación de nuevos sistemas de transporte. En relación con lo anterior, los adelantos en materia de transporte aceleraron el crecimiento económico del país porque", "answers": [{"letter": "A", "text": "aseguraron la mayor intervención del Estado en la economía."}, {"letter": "B", "text": "promovieron la movilidad de los campesinos hacia las ciudades."}, {"letter": "C", "text": "permitieron la circulación de bienes y servicios dentro del territorio."}, {"letter": "D", "text": "incidieron en la disminución del rol de la burguesía en la economía."}], "correctAnswer": null}, {"number": 35, "axis": "Historia: Mundo, América y Chile", "text": "Analice el siguiente esquema: Zona patagónica Zona norte Zona sur Zona insular Ocupación del Guerra del Pacificación de la Incorporación Estrecho. Pacífico. Araucanía. Isla de Pascua. (1843) (1879 -1883) (1883) (1888) El esquema refiere a sucesos ocurridos a lo largo del siglo XIX en Chile. A partir de su observación, ¿qué expresión sintetiza correctamente los hechos representados?", "answers": [{"letter": "A", "text": "Conformación del territorio nacional durante el siglo XIX. 12"}, {"letter": "B", "text": "Conflictos entre Chile y sus países vecinos en el siglo XIX."}, {"letter": "C", "text": "Incorporación de territorios mineros a la soberanía nacional."}, {"letter": "D", "text": "Ocupación de zonas estratégicas mediante prácticas bélicas."}], "correctAnswer": null}, {"number": 36, "axis": "Historia: Mundo, América y Chile", "text": "Entre las décadas de 1860 y 1880, el Estado de Chile implementó un plan para la ocupación definitiva de los territorios de la Araucanía. Entre otros aspectos, ¿qué consecuencia tuvo dicho proceso para la economía nacional?", "answers": [{"letter": "A", "text": "Disminuyó la cantidad de industrias al sur de esa zona."}, {"letter": "B", "text": "Favoreció el desarrollo de la agricultura triguera en la región."}, {"letter": "C", "text": "Significó el ingreso de capital proveniente de la industria salitrera."}, {"letter": "D", "text": "Posibilitó la apertura de yacimientos mineros en tierras indígenas."}], "correctAnswer": null}, {"number": 37, "axis": "Historia: Mundo, América y Chile", "text": "La Guerra del Pacífico (1879-1883) fue el más importante conflicto que ha tenido Chile durante la historia de sus relaciones con los países vecinos. Como parte de las consecuencias de aquel conflicto, es posible mencionar", "answers": [{"letter": "A", "text": "la disminución de la inversión extranjera en el país."}, {"letter": "B", "text": "la incorporación del cobre a la economía nacional."}, {"letter": "C", "text": "el incremento de los ingresos económicos fiscales."}, {"letter": "D", "text": "la ampliación del territorio nacional hacia la zona sur."}], "correctAnswer": null}, {"number": 38, "axis": "Historia: Mundo, América y Chile", "text": "La fundación del Fuerte Bulnes (1843) y la promulgación de la Ley de Colonización (1845) son ejemplos de una política de Estado que se concretó a lo largo del siglo XIX. Al respecto, ¿cuál fue uno de los objetivos perseguidos por el Estado con estos proyectos?", "answers": [{"letter": "A", "text": "Conseguir la descentralización política del territorio."}, {"letter": "B", "text": "Establecer soberanía efectiva sobre el territorio nacional."}, {"letter": "C", "text": "Promover las migraciones internas hacia el Norte Grande."}, {"letter": "D", "text": "Integrar a las comunidades indígenas al desarrollo del país."}], "correctAnswer": null}, {"number": 39, "axis": "Historia: Mundo, América y Chile", "text": "Aunque la explotación de los yacimientos salitreros de Tarapacá y Antofagasta estaba en manos de capitales privados, el Estado de Chile tuvo un rol importante en la distribución de la riqueza generada por esa actividad económica. ¿Cuál de las siguientes opciones contiene un ejemplo de esa acción estatal?", "answers": [{"letter": "A", "text": "La entrega de subsidios obreros."}, {"letter": "B", "text": "La tecnificación de la agricultura."}, {"letter": "C", "text": "La construcción de obras públicas."}, {"letter": "D", "text": "La reducción de aranceles aduaneros."}], "correctAnswer": null}, {"number": 40, "axis": "Historia: Mundo, América y Chile", "text": "Tras la Guerra del Pacífico, muchas personas migraron hacia el norte para trabajar en las oficinas salitreras, sin embargo, el sistema salarial y las condiciones laborales en las que 13 se desarrolló la extracción del nitrato no cumplieron con las expectativas de los nuevos mineros y sus familias, situación que los motivó a", "answers": [{"letter": "A", "text": "organizarse para exigir mejoras laborales."}, {"letter": "B", "text": "regresar a las haciendas del valle central."}, {"letter": "C", "text": "exigir al Estado la construcción de escuelas."}, {"letter": "D", "text": "proponer la construcción de hospitales públicos."}], "correctAnswer": null}, {"number": 41, "axis": "Historia: Mundo, América y Chile", "text": "Para hacer frente a las precarias condiciones de vida, muchos obreros dieron vida a mutuales y cooperativas, organizaciones que buscaban ofrecer una ayuda económica a sus integrantes en períodos de cesantía, enfermedad e incluso la muerte. Por otra parte, las mancomunales y sociedades de resistencia fueron organizaciones eminentemente políticas. Uno de los desafíos políticos de las organizaciones obreras de principios del siglo XX es", "answers": [{"letter": "A", "text": "representar en el Congreso al campesinado chileno."}, {"letter": "B", "text": "promover leyes que defiendan al proletariado urbano."}, {"letter": "C", "text": "fomentar la participación política de las mujeres obreras."}, {"letter": "D", "text": "incrementar la participación de los radicales en el Gobierno."}], "correctAnswer": null}, {"number": 42, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “En Santiago, en la fecha del centenario, se contabilizaban más de 1.600 conventillos y las enfermedades infecciosas (tuberculosis, viruela, tifus, etc.) eran pan de todos los días. La mortalidad infantil alcanzaba el 30% y el analfabetismo casi llegaba al 50%. Aquellos que migraban al norte no tenían mejores expectativas de futuro. Las condiciones laborales eran tremendamente duras y hasta 1907, en que se legisló sobre la materia, se trabajaba entre 12 y 14 horas diarias, sin descanso dominical del domingo”. Góngora, A. (2000). Chile (1541- 2000) una interpretación de su historia política. El texto adjunto retrata los principales problemas que, a finales del siglo XIX y principios del siglo XX, afectaba a los sectores más pobres de Chile. Entre las características de este período, es correcto señalar", "answers": [{"letter": "A", "text": "la eficiente legislación laboral que protegía a los trabajadores."}, {"letter": "B", "text": "la alta calidad de vida, experimentado por los sectores obreros."}, {"letter": "C", "text": "la baja esperanza de vida que alcanzaban las clases trabajadoras."}, {"letter": "D", "text": "la intensión de las autoridades por ofrecer servicios a la población."}], "correctAnswer": null}, {"number": 43, "axis": "Historia: Mundo, América y Chile", "text": "Una de las grandes transformaciones sociales de inicios del siglo XX fue la incorporación de los sectores medios a la política, los que se diferenciaron del proletariado en sus formas de expresión. En este sentido, ¿cuál fue la vía de participación más significativa para la clase 14 media?", "answers": [{"letter": "A", "text": "La convocatoria a huelgas."}, {"letter": "B", "text": "La militancia en partidos políticos."}, {"letter": "C", "text": "La defensa de la revolución de los obreros."}, {"letter": "D", "text": "La generación de acuerdos con la oligarquía."}], "correctAnswer": null}, {"number": 44, "axis": "Historia: Mundo, América y Chile", "text": "La gran crisis económica, iniciada en 1929, golpeó de forma gravitante a casi todas las economías del mundo. Al interior de los países, los efectos fueron dramáticas. ¿Cuál de los siguientes es un efecto sobre la población?", "answers": [{"letter": "A", "text": "El desempleo de millones de trabajadores."}, {"letter": "B", "text": "Los esfuerzos por crear pequeñas industrias."}, {"letter": "C", "text": "El encarecimiento de servicios de salud privados."}, {"letter": "D", "text": "La caída en la compra de bienes para la recreación."}], "correctAnswer": null}, {"number": 45, "axis": "Historia: Mundo, América y Chile", "text": "A partir de 1929, con el problema que sufrió la bolsa de valores de Nueva York, se desató una gran crisis económica conocida como la Gran Depresión, que generó graves perjuicios económicos y sociales a nivel mundial. En América Latina se sintieron sus efectos con mayor intensidad desde 1931. Considerando lo anterior, ¿cuál de las siguientes alternativas fue una solución adoptada por los gobiernos latinoamericanos frente a esta crisis?", "answers": [{"letter": "A", "text": "El control estatal de las acciones e industrias bajo propiedad extranjera."}, {"letter": "B", "text": "La expropiación de la mayor parte de las tierras productivas a nivel nacional."}, {"letter": "C", "text": "La estatización de los recursos productivos estratégicos del territorio chileno."}, {"letter": "D", "text": "La aplicación de un modelo de industrialización sustitutiva de importaciones."}], "correctAnswer": null}, {"number": 46, "axis": "Historia: Mundo, América y Chile", "text": "Durante la Primera Guerra Mundial, cientos de mujeres comenzaron a trabajar en las industrias de los países beligerantes. Considerando el contexto, ¿cuál de las siguientes situaciones es un efecto de la participación femenina en el mundo laboral?", "answers": [{"letter": "A", "text": "El desarrollo de nuevos cargos de gobierno asumidos por mujeres."}, {"letter": "B", "text": "El interés por erradicar el analfabetismo entre los sectores vulnerables."}, {"letter": "C", "text": "La saturación de los puestos de trabajo en las zonas industriales europeas."}, {"letter": "D", "text": "La demanda por otorgar mayores grados de igualdad jurídica a las mujeres."}], "correctAnswer": null}, {"number": 47, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: 15 “Entonces, en 1929 los acontecimientos se empezaron a mover en la dirección de Hitler. Ese año dio inicio la crisis financiera mundial que provocó la caída del último gobierno realmente parlamentario de Alemania. Los alemanes acusaban a los extranjeros de sus problemas y a los judíos por evadir capitales. El marco sufrió grandes presiones y dejó de ser convertible. (…) El comercio cayó en dos terceras partes y como Alemania dependía de las exportaciones, muy pronto ocho millones de alemanes se quedaron sin empleo. En las elecciones federales de 1932, el treinta por ciento de los alemanes votaron por los nazis, el veintidós por ciento votaron por los socialdemócratas y el catorce por ciento optaron por los comunistas”. Stone, N. (2013) Breve historia de la Segunda Guerra Mundial. Los hechos descritos en el párrafo precedente se enmarcan en el período de entreguerras en Europa, que abarca desde el fin de la Gran Guerra hasta los inicios de la Segunda Guerra Mundial. De acuerdo con el párrafo, ¿qué permitió el complejo panorama económico de la década de 1930?", "answers": [{"letter": "A", "text": "La adopción de un modelo de desarrollo primario exportador."}, {"letter": "B", "text": "La consolidación de las ideas totalitarias en lo político-electoral."}, {"letter": "C", "text": "La profundización de la democracia en los países de Europa Central."}, {"letter": "D", "text": "El desprestigio de los partidos políticos como forma de representación."}], "correctAnswer": null}, {"number": 48, "axis": "Historia: Mundo, América y Chile", "text": "Posterior a la Segunda Guerra Mundial, diversos Estados occidentales optaron por seguir un modelo basado en el Estado de bienestar, como una respuesta de las diversas crisis que se evidenciaron desde inicios del siglo XX. A partir de un ámbito económico, ¿cuál es una característica de este tipo de sistema?", "answers": [{"letter": "A", "text": "La expansión del gasto fiscal."}, {"letter": "B", "text": "La privatización de la educación."}, {"letter": "C", "text": "La liberalización del comercio exterior."}, {"letter": "D", "text": "La eliminación de derechos sindicales."}], "correctAnswer": null}, {"number": 49, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “Por medio de la Declaración Universal de los Derechos Humanos, la comunidad internacional se comprometió a evitar la repetición de atrocidades como las sucedidas durante la Segunda Guerra Mundial, gracias a lo cual, “los Derechos Humanos representan [...] el consenso más grande jamás conseguido en la historia de la humanidad sobre valores, derechos y deberes para vivir en comunidad”. Rodríguez, X. (2006). Pedagogía de la convivencia. Entre las consecuencias de la Segunda Guerra Mundial, se establecen diversos acuerdos de paz y seguridad entre países. Considerando la fuente anterior, ¿cuál fue el impacto de la Declaración Universal de los Derechos Humanos? 16", "answers": [{"letter": "A", "text": "Generar un consenso internacional que resguardara la paz."}, {"letter": "B", "text": "Establecer los deberes políticos de la ciudadanía al vivir en sociedad."}, {"letter": "C", "text": "Formular acciones por parte del Estado para evitar conflictos armados."}, {"letter": "D", "text": "Evitar la participación de otros países en problemáticas de orden nacional."}], "correctAnswer": null}, {"number": 50, "axis": "Historia: Mundo, América y Chile", "text": "La sociedad chilena experimentó, hacia mediados del siglo XX una transformación demográfica de gran importancia. En este sentido, dentro de los factores que explican estos cambios, es posible encontrar", "answers": [{"letter": "A", "text": "el cierre definitivo de las poblaciones callampas."}, {"letter": "B", "text": "la aplicación de políticas económicas neoliberales."}, {"letter": "C", "text": "la promoción de políticas públicas de protección social."}, {"letter": "D", "text": "el incremento de la actividad industrial vinculada al salitre."}], "correctAnswer": null}, {"number": 51, "axis": "Historia: Mundo, América y Chile", "text": "Hacia mediados del siglo XX Chile experimentó una serie de transformaciones sociales y políticas. En este sentido, ¿cuál de las siguientes alternativas representa un cambio ocurrido en el período?", "answers": [{"letter": "A", "text": "La disminución del rol del Estado."}, {"letter": "B", "text": "La participación política de la mujer"}, {"letter": "C", "text": "El menor interés de la elite en política."}, {"letter": "D", "text": "El bajo protagonismo de la clase media."}], "correctAnswer": null}, {"number": 52, "axis": "Historia: Mundo, América y Chile", "text": "En la segunda mitad del siglo XX en Chile, gran parte de la población infantil enfrentaba condiciones de insalubridad y desnutrición, a pesar de que la tasa de mortalidad había disminuido. Considerando este contexto, ¿qué factor contribuyó a la permanencia de esta problemática?", "answers": [{"letter": "A", "text": "La falta de recursos por parte del Estado para la distribución de bienes."}, {"letter": "B", "text": "La escasez de profesionales universitarios en la clase baja de la sociedad."}, {"letter": "C", "text": "El incremento de la inflación a propósito del mayor gasto fiscal en bienestar."}, {"letter": "D", "text": "El desinterés de los sectores políticos para crear leyes sobre seguridad social."}], "correctAnswer": null}, {"number": 53, "axis": "Historia: Mundo, América y Chile", "text": "En 1973 se produjo un Golpe de Estado que inició una dictadura cívico-militar que de diecisiete años. Considerando el contexto expuesto, ¿cuál fue una característica de este régimen?", "answers": [{"letter": "A", "text": "El respeto de la Constitución Política de 1925."}, {"letter": "B", "text": "La implementación de un Estado de bienestar en Chile."}, {"letter": "C", "text": "La persecución de intelectuales y políticos de izquierda."}, {"letter": "D", "text": "El triunfo de guerrillas que buscaban acabar con la dictadura."}], "correctAnswer": null}, {"number": 54, "axis": "Historia: Mundo, América y Chile", "text": "Durante la dictadura cívico-militar chilena hubo modificaciones estructurales en aspectos políticos, sociales y económicos. En relación con este último ámbito, ¿cuál es una 17 característica de este sistema?", "answers": [{"letter": "A", "text": "La privatización de empresas estatales."}, {"letter": "B", "text": "El cierre de fábricas y empresas privadas."}, {"letter": "C", "text": "La prohibición para la inversión extranjera."}, {"letter": "D", "text": "El aumento de inversión estatal en minería."}], "correctAnswer": null}, {"number": 55, "axis": "Historia: Mundo, América y Chile", "text": "Durante la dictadura militar se aprobó una nueva constitución política para el país. Considerando el contexto autoritario que impuso el régimen militar, ¿cuál fue uno de los objetivos perseguidos con la promulgación de una nueva Carta Magna?", "answers": [{"letter": "A", "text": "Legitimar un relato histórico afín a los intereses de los cuerpos militares."}, {"letter": "B", "text": "Incentivar el rechazo ciudadano hacia los partidos de orientación marxista."}, {"letter": "C", "text": "Fomentar la participación ciudadana para la recuperación de la democracia."}, {"letter": "D", "text": "Asegurar la permanencia de la nueva institucionalidad tras el fin del régimen."}], "correctAnswer": null}, {"number": 56, "axis": "Historia: Mundo, América y Chile", "text": "La Vicaría de la Solidaridad fue una institución ligada a la Iglesia Católica que se organizó durante la dictadura militar e integraba a personas de distintas disciplinas. Considerando sus propósitos, ¿cuál fue el rol de esta institución durante el régimen militar?", "answers": [{"letter": "A", "text": "Apoyar las decisiones políticas aplicadas por el régimen militar."}, {"letter": "B", "text": "Encubrir las acciones de las autoridades de la dictadura militar."}, {"letter": "C", "text": "Mantener un rol secundario en el desarrollo de manifestaciones."}, {"letter": "D", "text": "Evidenciar las violaciones a los derechos humanos en la dictadura."}], "correctAnswer": null}, {"number": 57, "axis": "Historia: Mundo, América y Chile", "text": "Analice la siguiente propaganda: “LA MALA MEMORIA DE JULIA PUEDE HACERLA PASAR HAMBRE” 1973: DESABASTECIMIENTO Y COLAS/ 1988: PLENA OFERTA Y COMODIDAD La mala memoria puede hacer que muchas mujeres chilenas vuelvan a pasar penurias, escasez e incomodidades. Porque hace quince años las colas eran interminables. Para el pan. Para la leche. Para el azúcar (…). En el próximo plebiscito es posible que usted tenga que volver hacer cola para votar. Cuando esté en la fila piense y acuérdese”. Campaña por el SI (1988) Texto de un afiche promocional de la opción “Sí”. La cita corresponde a una propaganda electoral elaborada por las autoridades del régimen militar de Chile, previo al plebiscito de 1988. A partir del análisis del documento y considerando el contexto histórico, es correcto deducir que 18", "answers": [{"letter": "A", "text": "la campaña del \"Sí\" se desarrolló a través de afiches, volantes y panfletos, pues no contaba con un espacio formal en televisión."}, {"letter": "B", "text": "la consulta ciudadana formó parte del proceso de retorno a la democracia, liderado por los partidos de derecha y la Iglesia católica."}, {"letter": "C", "text": "el modelo económico vigente en el país, al momento del plebiscito, era el de industrialización por sustitución de importaciones."}, {"letter": "D", "text": "el \"Sí\" apelaba al momento de prosperidad económica en 1988, en comparación con los problemas de escasez bajo la Unidad Popular."}], "correctAnswer": null}, {"number": 58, "axis": "Sistema Económico", "text": "El sistema económico chileno se reconoce como una economía social de mercado. En relación con lo anterior, ¿cuál de las siguientes alternativas representa una característica de este modelo económico?", "answers": [{"letter": "A", "text": "La libertad económica es una garantía constitucional."}, {"letter": "B", "text": "La generación de empleos es responsabilidad del Estado."}, {"letter": "C", "text": "El Estado controla la mayor parte del sistema económico."}, {"letter": "D", "text": "La autoridad fiscal fija los precios en el mercado financiero."}], "correctAnswer": null}, {"number": 59, "axis": "Sistema Económico", "text": "Independiente del modelo de desarrollo que tenga cada país, el Estado siempre ejerce algún papel en la economía. En el caso de Chile, ¿cuál es el papel que desempeña el Estado?", "answers": [{"letter": "A", "text": "Monopoliza los servicios educativos de la población."}, {"letter": "B", "text": "Propone la inversión de las clínicas privadas en salud."}, {"letter": "C", "text": "Determina la carga impositiva que se aplica a las empresas."}, {"letter": "D", "text": "Regula las estrategias de inversión de las empresas privadas."}], "correctAnswer": null}, {"number": 60, "axis": "Sistema Económico", "text": "La sociedad chilena hoy cuenta con mecanismos de protección laboral que son resultado de un largo proceso de luchas sociales y el aporte de distintos actores. En base a 19 lo recién expuesto, ¿cuál de las siguientes alternativas es un antecedente de la legislación laboral vigente?", "answers": [{"letter": "A", "text": "El movimiento obrero chileno."}, {"letter": "B", "text": "El respaldo de la iglesia católica."}, {"letter": "C", "text": "El aporte de los empresarios textiles."}, {"letter": "D", "text": "El accionar de los gremios industriales."}], "correctAnswer": null}, {"number": 61, "axis": "Sistema Económico", "text": "En los últimos años la automatización laboral ha provocado la reducción de empleos sobre todo en áreas del sector servicios, donde la mayoría de la población se desempeña. Considerando lo recién expuesto, ¿Cómo puede el Estado contribuir a la reinserción de los desempleados?", "answers": [{"letter": "A", "text": "Ampliando los bonos para los sectores vulnerables."}, {"letter": "B", "text": "Aumentando el empleo público en el sector terciario."}, {"letter": "C", "text": "Fomentando un nuevo retiro de fondos previsionales."}, {"letter": "D", "text": "Capacitando a las personas en empleos demandados."}], "correctAnswer": null}, {"number": 62, "axis": "Sistema Económico", "text": "Lea el siguientes párrafo: “El proyecto la Ley de 40 Horas fue originalmente presentado en 2017 por la entonces diputada y hoy ministra de la Secretaría General de Gobierno, Camila Vallejo, y la diputada Karol Cariola. En 2022 el gobierno del Presidente Gabriel Boric ingresó indicaciones a dicha propuesta, las que surgieron de un trabajo tripartito entre trabajadores, empleadores y Ejecutivo. El proyecto fue despachado a ley por el Congreso, con apoyo transversal, en abril del año pasado y promulgada el mismo mes.” Subsecretaria del Trabajo y previsión social. (2025) Ley de 40 Horas ya es una realidad. El párrafo explica el origen de la ley de 40 horas de trabajo aprobada durante el gobierno de Gabriel Boric. Considerando los antecedentes expuestos, ¿Qué se puede extraer del texto?", "answers": [{"letter": "A", "text": "La legislación fue ideada por el ejecutivo."}, {"letter": "B", "text": "La ley fue rechazada por los empresarios."}, {"letter": "C", "text": "La normativa se originó en la cámara baja."}, {"letter": "D", "text": "La reducción de horas se aplica desde 2022."}], "correctAnswer": null}, {"number": 63, "axis": "Sistema Económico", "text": "El Servicio Nacional del Consumidor (SERNAC) tiene como misión informar, educar y proteger a los consumidores de Chile. Por lo anterior, el SERNAC se encarga de elaborar guías e infografías para facilitar y promover el ejercicio cotidiano de los derechos por parte de los consumidores de todas las edades. A partir de lo anterior, ¿cuál de las siguientes 20 alternativas representa una vulneración a los derechos de los consumidores?", "answers": [{"letter": "A", "text": "La suspensión de un concierto ante una tormenta eléctrica."}, {"letter": "B", "text": "La devolución del dinero al consumidor por un producto defectuoso."}, {"letter": "C", "text": "El rechazo de una solicitud de crédito, por no cumplir con renta mínima."}, {"letter": "D", "text": "La negación a devolver valor de entrada ante cambio de fecha de concierto."}], "correctAnswer": null}, {"number": 64, "axis": "Sistema Económico", "text": "Lea el siguiente extracto de una noticia: El alza de precios golpea a los sectores de bajos recursos y empuja la línea de la pobreza. En el país de los alimentos, comer cuesta cada vez más. Tres consultoras privadas argentinas, a falta de números oficiales, calcularon desde enero alzas entre 12 y 13 puntos en la canasta básica de alimentos, una construcción estadística que sirve para medir la pobreza y la indigencia”. Diario El País, 7 de abril de 2016 ¿A qué fenómeno vinculado al funcionamiento del mercado se alude en el texto anterior?", "answers": [{"letter": "A", "text": "La pobreza."}, {"letter": "B", "text": "La inflación."}, {"letter": "C", "text": "La deflación."}, {"letter": "D", "text": "La desigualdad."}], "correctAnswer": null}, {"number": 65, "axis": "Sistema Económico", "text": "En las últimas décadas, en Chile, se han creado una serie de organismos como la Comisión para el Mercado Financiero (CMF) y el Servicio Nacional del Consumidor (SERNAC). Independientemente de su área de interés, estas instituciones tienen como principal propósito", "answers": [{"letter": "A", "text": "regular el mercado financiero dentro del territorio."}, {"letter": "B", "text": "fiscalizar el actuar de las empresas en el mercado."}, {"letter": "C", "text": "controlar el funcionamiento de la libre competencia."}, {"letter": "D", "text": "redactar la legislación que protege a los trabajadores."}], "correctAnswer": null}], "4": [{"number": 1, "axis": "Formación Ciudadana", "text": "La democracia se basa en el principio de soberanía popular que reconoce a los ciudadanos como protagonistas de su organización política, eligiendo libremente a sus representantes. Considerando lo anterior, ¿cuál es el principal problema que enfrenta hoy la democracia contemporánea?", "answers": [{"letter": "A", "text": "La escasa participación ciudadana en las elecciones."}, {"letter": "B", "text": "La imposibilidad de generar leyes para sus ciudadanos."}, {"letter": "C", "text": "La coerción que ejercen las policías en el uso de la fuerza."}, {"letter": "D", "text": "La restricción a la libertad de opinión ejercida por los estados."}], "correctAnswer": null}, {"number": 2, "axis": "Formación Ciudadana", "text": "Lea el siguiente texto: “El dato más relevante es el progresivo y constante incremento de la insatisfacción con la democracia desde mediados de la década de los 1990s y hasta la fecha. Hoy, en la mayoría de los países, cerca de un 60% de la ciudadanía se siente insatisfecha con su funcionamiento. Las regiones que han observado mayores incrementos en esta insatisfacción son América Latina, África y Europa” Fuentes, C.(2021) El descontento global con la democracia. El texto hace referencia a la mirada que tiene la ciudadanía con respecto a sus sistemas 2 democráticos, a nivel global. Considerando lo expuesto en el párrafo, ¿cuál de las siguientes opciones representa un problema para la democracia actual?", "answers": [{"letter": "A", "text": "La escasa valoración que existe en torno a la democracia en el mundo."}, {"letter": "B", "text": "La desconfianza que tiene la ciudadanía hacia sus sistemas democráticos."}, {"letter": "C", "text": "El incremento de las movilizaciones sociales que exigen un cambio político."}, {"letter": "D", "text": "El desapego que sienten los ciudadanos con políticos corruptos en sus países."}], "correctAnswer": null}, {"number": 3, "axis": "Formación Ciudadana", "text": "Los sondeos de opinión, en los últimos años, demuestran una evaluación negativa para la clase política nacional. Según una encuesta del Centro de Estudios Públicos, presentada en junio de 2022, los partidos políticos son los organismos que generan menor confianza entre la ciudadanía, seguidos por el Congreso Nacional. En este escenario ¿cuál de las siguientes alternativas representa un desafío para la clase política nacional?", "answers": [{"letter": "A", "text": "Mejorar las dietas de senadores y diputados."}, {"letter": "B", "text": "Proponer políticas que beneficien a la ciudadanía."}, {"letter": "C", "text": "Disminuir los sueldos de los funcionarios públicos."}, {"letter": "D", "text": "Fortalecer los beneficios tributarios de las empresas."}], "correctAnswer": null}, {"number": 4, "axis": "Formación Ciudadana", "text": "El pluralismo es uno de los atributos de la democracia chilena, lo que permite la existencia de una variada gama de partidos políticos que pueden tener representación parlamentaria. Considerando lo anterior, ¿cuál de las siguientes afirmaciones es resultado del pluralismo político?", "answers": [{"letter": "A", "text": "La posibilidad de discutir un proyecto de ley considerando diversas miradas."}, {"letter": "B", "text": "La amplia participación ciudadana en las elecciones dada la oferta partidista."}, {"letter": "C", "text": "La incapacidad del Congreso para redactar leyes que beneficien a la población."}, {"letter": "D", "text": "La escasa representatividad que alcanza el Congreso Nacional en las elecciones."}], "correctAnswer": null}, {"number": 5, "axis": "Formación Ciudadana", "text": "La democracia chilena se caracteriza por permitir la participación periódica de los ciudadanos en las elecciones de autoridades y representantes políticos como alcaldes, concejales, consejeros y gobernadores regionales, diputados, senadores y presidente de la República. Pese a esta amplia posibilidad de participación y posibilidades en las que se solicita la opinión de la ciudadanía, las últimas elecciones han demostrado un alza en la abstención electoral. Considerando lo recién expuesto, ¿cuál de las siguientes opciones es una de las causas que explican dicho fenómeno en la democracia chilena?", "answers": [{"letter": "A", "text": "La adopción de la inscripción automática y el voto voluntario en 2012."}, {"letter": "B", "text": "La imposibilidad de los trabajadores para acceder el día de las elecciones."}, {"letter": "C", "text": "El temor a que el voto individual sea manipulado por personeros de gobierno. 3"}, {"letter": "D", "text": "La escasa difusión sobre los candidatos y las propuestas que éstos presentan al país."}], "correctAnswer": null}, {"number": 6, "axis": "Formación Ciudadana", "text": "El Congreso Nacional chileno es una institución formada por dos cámaras y sus representantes son electos, íntegramente, por la ciudadanía en actos democráticos. Considerando la importancia que tiene este organismo en la elaboración y discusión de las leyes que rigen al país, ¿cuál es el principal desafío que tienen los ciudadanos chilenos en la elección de senadores y diputados?", "answers": [{"letter": "A", "text": "Difundir las propuestas políticas de los candidatos."}, {"letter": "B", "text": "Conocer las propuestas de los candidatos al Congreso."}, {"letter": "C", "text": "Proponer leyes que mejoren la vida de los trabajadores."}, {"letter": "D", "text": "Elegir a candidatos propuestos por el Gobierno de turno."}], "correctAnswer": null}, {"number": 7, "axis": "Formación Ciudadana", "text": "Lea el siguiente texto: “La democracia es una respuesta a la pregunta sobre quién debe ejercer el poder del Estado. A esta pregunta contesta la democracia, que el poder del Estado compete al pueblo. Ya desde la antigüedad se anota esta contestación: nos encontramos con los sofistas en donde existía ya la opinión de que la voluntad del pueblo es la fuente del poder político y se dibujaba la idea de un contrato social como fundamento de las leyes (...)” Ramírez, R. Los fundamentos de la democracia. En el texto se exponen los fundamentos de la democracia contemporánea aludiendo a sus orígenes. Considerando lo expresado en el párrafo, ¿cuál de las siguientes alternativas expone una idea central de la democracia?", "answers": [{"letter": "A", "text": "La fuente del poder político se concentra en las leyes."}, {"letter": "B", "text": "La voluntad ciudadana otorga el poder al sistema político."}, {"letter": "C", "text": "Los sofistas son los padres de los sistemas democráticos."}, {"letter": "D", "text": "La democracia se funda en los contratos entre las personas."}], "correctAnswer": null}, {"number": 8, "axis": "Formación Ciudadana", "text": "En un sistema democrático, el poder del Estado se divide en tres ramas principales: el poder ejecutivo, el poder legislativo y el poder judicial. Cada uno de estos poderes tiene un papel importante que desempeñar en el gobierno y en la sociedad en general. ¿Cuál es la función principal del poder legislativo en un sistema democrático? 4", "answers": [{"letter": "A", "text": "Ejecutar las políticas públicas del gobierno."}, {"letter": "B", "text": "Aprobar o rechazar nombramientos de jueces."}, {"letter": "C", "text": "Juzgar a los individuos por de violar las leyes del país."}, {"letter": "D", "text": "Representar los intereses ciudadanos a través de leyes."}], "correctAnswer": null}, {"number": 9, "axis": "Formación Ciudadana", "text": "El sufragio en Chile ha evolucionado a lo largo del tiempo, permitiendo el acceso al voto a diferentes sectores de la población. ¿Cuál fue una de las últimas reformas al sufragio en Chile?", "answers": [{"letter": "A", "text": "La aceptación del voto para mayores de 16 años."}, {"letter": "B", "text": "La voluntariedad del voto para mayores de 65 años."}, {"letter": "C", "text": "La incorporación de extranjeros residentes en el país."}, {"letter": "D", "text": "La implementación del voto de chilenos en el exterior."}], "correctAnswer": null}, {"number": 10, "axis": "Formación Ciudadana", "text": "En Chile, el sistema electoral utiliza el método D'Hondt para distribuir los escaños en las elecciones parlamentarias. Este método tiene ciertas características que afectan la representatividad del sistema y la distribución de poder en el Congreso. En este contexto, ¿cuál de las siguientes afirmaciones describe el método D'Hondt en Chile?", "answers": [{"letter": "A", "text": "Favorece a los partidos políticos que obtienen mayoría de votos en las elecciones, lo que les permite controlar el Congreso."}, {"letter": "B", "text": "Beneficia a los partidos políticos pequeños, ya que les permite obtener escaños con menos votos que los partidos más grandes."}, {"letter": "C", "text": "Otorga escaños de manera proporcional al número de votos obtenidos por cada lista, lo que asegura una representación equitativa en el Congreso."}, {"letter": "D", "text": "Otorga un número fijo de escaños a cada partido, independientemente del porcentaje de votos, lo que garantiza una representación justa en el Congreso."}], "correctAnswer": null}, {"number": 11, "axis": "Formación Ciudadana", "text": "El Tribunal Calificador de Elecciones (Tricel) es un organismo encargado de supervisar y fiscalizar el proceso electoral en Chile. Entre sus funciones se encuentra la resolución de controversias y la organización de las elecciones de los distintos organismos colegiados, como los consejos municipales, las juntas de vecinos, entre otros. En este contexto, ¿cuál es una característica de esta institución en Chile?", "answers": [{"letter": "A", "text": "Es un organismo que tiene como objetivo principal la elaboración de las leyes 5 electorales en Chile."}, {"letter": "B", "text": "Tiene como función principal la organización de las elecciones presidenciales y parlamentarias en Chile."}, {"letter": "C", "text": "Está compuesto por representantes de los distintos partidos políticos, quienes se encargan de supervisar y fiscalizar los procesos electorales en Chile."}, {"letter": "D", "text": "Es un organismo autónomo e independiente, cuyo objetivo es velar por el cumplimiento de la ley y la transparencia en los procesos electorales en Chile."}], "correctAnswer": null}, {"number": 12, "axis": "Formación Ciudadana", "text": "Las organizaciones no gubernamentales (ONG) han tenido un papel importante en la sociedad chilena, al abordar diferentes temas, desde los derechos humanos hasta la protección del medio ambiente. ¿Cuál de las siguientes afirmaciones describe mejor una característica común de las ONG en Chile?", "answers": [{"letter": "A", "text": "Tienen experiencia en cargos públicos para garantizar la eficiencia y efectividad de sus proyectos."}, {"letter": "B", "text": "Son apolíticas y no tienen una posición clara frente a los partidos políticos y los gobiernos de turno."}, {"letter": "C", "text": "Son financiadas principalmente por el Estado y reciben pocos fondos de donaciones privadas."}, {"letter": "D", "text": "Tienen una fuerte presencia en la sociedad civil y son reconocidas por su capacidad de movilización y presión en temas de interés público."}], "correctAnswer": null}, {"number": 13, "axis": "Formación Ciudadana", "text": "En Chile, la probidad es un tema de gran importancia en la gestión pública. La Ley N° 20.880 establece normas sobre probidad, transparencia y fortalecimiento de la ética pública. En este contexto, ¿cuál de las siguientes situaciones puede considerarse como una violación a la probidad?", "answers": [{"letter": "A", "text": "Un concejal se abstiene de votar en una sesión del concejo municipal debido a enemistades con el alcalde."}, {"letter": "B", "text": "Un alcalde utiliza fondos públicos para comprar materiales de construcción para reparar la casa de un amigo."}, {"letter": "C", "text": "Un diputado recibe una donación de una empresa para financiar su campaña electoral y lo declara entre sus gastos electorales."}, {"letter": "D", "text": "Un ministro de Estado nombra a un amigo para un cargo en su ministerio, aunque este no tenga las calificaciones necesarias para el puesto."}], "correctAnswer": null}, {"number": 14, "axis": "Formación Ciudadana", "text": "El Ministerio Público es el organismo encargado de investigar los actos delictivos que atentan contra la seguridad de los ciudadanos, pero, en el último tiempo, ante la existencia de nuevas bandas criminales y delitos, la capacidad de esta institución se ha visto mermada. Considerando el contexto descrito, ¿cómo puede fortalecerse esta institución del sistema judicial chileno?", "answers": [{"letter": "A", "text": "Difundiendo imágenes de miembros del crimen organizado. 6"}, {"letter": "B", "text": "Eliminando las exigencias de género para entrar a la institución."}, {"letter": "C", "text": "Otorgando recursos tecnológicos para perseguir la nueva criminalidad."}, {"letter": "D", "text": "Facultando a las policías a encarcelar inmediatamente a los delincuentes."}], "correctAnswer": null}, {"number": 15, "axis": "Formación Ciudadana", "text": "Lea el siguiente artículo: \"La facultad de conocer de las causas civiles y criminales, de resolverlas y de hacer ejecutar lo juzgado, pertenece exclusivamente a los tribunales establecidos por la ley. Ni el Presidente de la República ni el Congreso pueden, en caso alguno, ejercer funciones judiciales, avocarse causas pendientes, revisar los fundamentos o contenido de sus resoluciones o hacer revivir procesos fenecidos\" Poder Judicial. (2025) ¿Qué es el Poder Judicial? El texto corresponde al artículo 76 de la Constitución Política de Chile en lo que concierne a las atribuciones del Poder Judicial. Considerando lo expresado en el artículo, ¿cuál es una característica de este poder del Estado?", "answers": [{"letter": "A", "text": "Disponer de personal para la redacción de leyes."}, {"letter": "B", "text": "Contar con integrantes elegidos por la ciudadanía."}, {"letter": "C", "text": "Ser un ente autónomo frente a otros poderes estatales."}, {"letter": "D", "text": "Tener la facultad de indultar a reos ante una enfermedad."}], "correctAnswer": null}, {"number": 16, "axis": "Formación Ciudadana", "text": "Lea el siguiente texto: En el uso de las redes se pueden encontrar aspectos positivos, como el flujo de información que permite tomar decisiones más informadas, pero también aspectos negativos, como es la distorsión de realidades derivadas de ello. Se debe valorar la oportunidad que entregan las redes sociales de participar, pero entender que esto no reemplaza al mecanismo más tradicional en las democracias representativas que es el sufragio. Las redes pueden tener un tremendo éxito siempre y cuando generen la motivación de llevar a la urna. Si eso no se cumple, terminan siendo una falsa realidad”. Freire, N. (2019) ¿Las redes sociales son el escenario político de las nuevas generaciones? El autor del texto anterior expresa efectos positivos y negativos del uso de las redes sociales dentro del sistema democrático. En relación con lo anterior, ¿cuál de las siguientes afirmaciones da cuenta de un desafío de las redes sociales para cooperar con la democracia?", "answers": [{"letter": "A", "text": "La creación de realidades paralelas dentro de un mismo territorio."}, {"letter": "B", "text": "La difusión de noticias cuyas fuentes presentan orígenes difíciles de verificar."}, {"letter": "C", "text": "El reemplazo de los mecanismos tradicionales de participación de los ciudadanos."}, {"letter": "D", "text": "La motivación que permita a los ciudadanos participar de las votaciones y actos electorales."}], "correctAnswer": null}, {"number": 17, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “A través de numerosos catecismos políticos patriotas, republicanos y constitucionales, es posible identificar el significado de conceptos como patria, pueblo, soberanía y ciudadanía, los que constituyen la base de la definición de los estados republicanos y de los actores políticos que emergen con la independencia, los que, con las adaptaciones ocurridas a lo largo del tiempo y, sobre todo la inclusión de cada vez más personas en su significado, perduran hasta la actualidad.” Sagredo, R. Ciudadanía, ideal republicano, 1810-2020. El texto hace referencia a los conceptos que comenzaron a difundirse, entre la población durante los procesos de emancipación americana a principios del siglo XIX. Considerando lo expuesto en el párrafo, ¿cuál fue la estrategia utilizada para difundir el ideal republicano?", "answers": [{"letter": "A", "text": "En las iglesias mediante las prédicas."}, {"letter": "B", "text": "Educando a los niños en los colegios."}, {"letter": "C", "text": "Definiendo conceptos republicanos en libros."}, {"letter": "D", "text": "Eligiendo a representantes entre la ciudadanía."}], "correctAnswer": null}, {"number": 18, "axis": "Historia: Mundo, América y Chile", "text": "En los primeros años del siglo XIX las naciones americanas modificaron la estructura de 8 gobierno que las había regido desde la época colonial europea. Dicha modificación significó una serie de cambios en su estructura económica, política y social, sin embargo, hubo manifestaciones culturales que se mantuvieron en el tiempo. ¿Cuál de las siguientes alternativas constituye un elemento de continuidad cultural que se mantuvo tras los procesos de independencia americana?", "answers": [{"letter": "A", "text": "El protagonismo político de grupos amerindios."}, {"letter": "B", "text": "La influencia de la iglesia católica en asuntos políticos."}, {"letter": "C", "text": "El desinterés de los grupos criollos por intervenir en política."}, {"letter": "D", "text": "La permanente movilidad social de los estamentos sociales."}], "correctAnswer": null}, {"number": 19, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “Si la economía del mundo del siglo XIX se formó principalmente bajo la influencia de la revolución industrial inglesa, su política e ideología se formaron principalmente bajo la influencia de la Revolución francesa. Inglaterra proporcionó el modelo para sus ferrocarriles y fábricas y el explosivo económico que hizo estallar las tradicionales estructuras económicas y sociales del mundo no europeo, pero Francia hizo sus revoluciones y les dio sus ideas, hasta el punto de que cualquier cosa tricolor se convirtió en el emblema de todas las nacionalidades nacientes.” Hobsbawm, E.(2001) La era de la Revolución. El texto se refiere a los procesos económico-políticos que influyeron, en el siglo XIX, en el mundo occidental. Tras su lectura ¿cuál de las siguientes afirmaciones puede inferirse del párrafo?", "answers": [{"letter": "A", "text": "Las naciones americanas comerciaron con Inglaterra."}, {"letter": "B", "text": "Las industrias facilitaron la vida de los sectores proletarios."}, {"letter": "C", "text": "Las economías contemporáneas adoptaron el neoliberalismo."}, {"letter": "D", "text": "Las revoluciones del siglo XVIII influyeron en lo político y económico."}], "correctAnswer": null}, {"number": 20, "axis": "Historia: Mundo, América y Chile", "text": "A inicios del siglo XIX los países hispanoamericanos alcanzaron su libertad luego de violentos procesos de emancipación que dividieron a la sociedad y que dejaron una crisis económica de grandes proporciones. Considerando la situación político - económica recién expuesta ¿Cuál de las siguientes opciones fue un desafío para los primeros gobiernos 9 americanos?", "answers": [{"letter": "A", "text": "Ampliar la inversión estatal en la industria y el comercio."}, {"letter": "B", "text": "Recaudar recursos para mantener los nacientes estados."}, {"letter": "C", "text": "Impulsar proyectos de conectividad vial entre las ciudades."}, {"letter": "D", "text": "Construir hospitales públicos para recuperar a los soldados."}], "correctAnswer": null}, {"number": 21, "axis": "Historia: Mundo, América y Chile", "text": "Para lograr la independencia, los países de América Latina, debieron enfrentar cruentas guerras civiles entre quienes defendían a la monarquía española y los que deseaban la emancipación política. Tras alcanzar la emancipación la violencia no se detuvo pues durante los primeros años de vida independiente, los países americanos vivieron nuevos conflictos. ¿Cuál de las siguientes afirmaciones explica los conflictos descritos?", "answers": [{"letter": "A", "text": "La búsqueda de justicia social entre la clase dirigente."}, {"letter": "B", "text": "El interés de los proletarios por ser parte del gobierno."}, {"letter": "C", "text": "La escasa representación de la iglesia católica en el Estado."}, {"letter": "D", "text": "La diversidad de visiones entre la élite para organizar el Estado."}], "correctAnswer": null}, {"number": 22, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto; “El surgimiento del Estado moderno en América implicaba que no solamente se diera un desplazamiento de las viejas instituciones, sino su completa renovación, su predominio con las nuevas autoridades de la nación, creando un orden social nuevo (liberal, burgués y capitalista), al eliminarse las viejas formas estamentales de origen feudal del periodo colonial mediante un triple proceso revolucionario: revolución liberal, revolución burguesa y revolución industrial. Para las recién independizadas naciones, esto resultaría un proceso de largo plazo, con avances y retrocesos, que tomó aproximadamente todo el siglo XIX dada la complejidad en las estructuras políticas, económicas y sociales que existían en Latinoamérica” UNAM (2017) La conformación de los Estados latinoamericanos. El texto hace referencia a las políticas que debieron aplicar los nuevos estados americanos tras alcanzar la independencia en el siglo XIX. Según el texto, ¿cuál de las siguientes alternativas representa una política económica aplicada en el proceso de construcción del Estado - nación americano?", "answers": [{"letter": "A", "text": "Iniciar un proceso industrializador aplicando políticas capitalistas."}, {"letter": "B", "text": "Consolidar el sistema feudal que ofreció riqueza en la época colonial."}, {"letter": "C", "text": "Mantener el liderazgo de los terratenientes en la actividad productiva."}, {"letter": "D", "text": "Ampliar la participación de la ciudadanía en las decisiones económicas. 10"}], "correctAnswer": null}, {"number": 23, "axis": "Historia: Mundo, América y Chile", "text": "Durante el periodo de ensayos constitucionales en Chile (1823-1830), se discutió ampliamente sobre el modelo político que debía adoptar el país y los principios que debían regir en la redacción de la constitución. Uno de los debates más relevantes fue el que tuvo lugar en torno al concepto de soberanía popular y su relación con el poder ejecutivo y legislativo. ¿Qué implica el concepto de soberanía popular en el contexto del periodo de ensayos constitucionales en Chile?", "answers": [{"letter": "A", "text": "La eliminación del poder judicial."}, {"letter": "B", "text": "La posibilidad de elegir a los representantes."}, {"letter": "C", "text": "La creación de un poder ejecutivo unipersonal."}, {"letter": "D", "text": "La subordinación del poder legislativo al ejecutivo."}], "correctAnswer": null}, {"number": 24, "axis": "Historia: Mundo, América y Chile", "text": "La Guerra Civil de 1829 tuvo un impacto significativo en la historia de Chile y su proceso de consolidación como nación independiente. ¿Cuál fue la principal causa de este conflicto?", "answers": [{"letter": "A", "text": "La disputa por el poder entre conservadores y liberales."}, {"letter": "B", "text": "La influencia extranjera en los asuntos políticos de Chile."}, {"letter": "C", "text": "La rebelión de los mapuches en contra del gobierno chileno."}, {"letter": "D", "text": "El intento de Chile de anexarse territorios peruanos y bolivianos."}], "correctAnswer": null}, {"number": 25, "axis": "Historia: Mundo, América y Chile", "text": "Durante el siglo XIX, la promulgación de la Constitución de 1833 en Chile generó cambios significativos en la organización del Estado y la vida política del país. ¿Cuál de las siguientes opciones describe una consecuencia directa de esta Constitución?", "answers": [{"letter": "A", "text": "La instalación de un sistema de educación pública y laica."}, {"letter": "B", "text": "La instauración de un sistema federal estatal en el territorio chileno."}, {"letter": "C", "text": "La garantía de derechos civiles y políticos para todos los ciudadanos."}, {"letter": "D", "text": "La creación de un poder ejecutivo fuerte y centralizado en el presidente."}], "correctAnswer": null}, {"number": 26, "axis": "Historia: Mundo, América y Chile", "text": "Diego Portales fue un político y comerciante, que destacó por ser ministro del Interior, entre otros cargos públicos. Sus ideas y pensamiento sobre la política son conocidas como el ideal portaliano. Con respecto a esto, ¿qué impacto tuvo este ideal en la formación del Estado chileno en el siglo XIX?", "answers": [{"letter": "A", "text": "Promovió la participación ciudadana."}, {"letter": "B", "text": "Fomentó la descentralización política."}, {"letter": "C", "text": "Consolidó el autoritarismo presidencial."}, {"letter": "D", "text": "Generó un sistema igualitario en el país."}], "correctAnswer": null}, {"number": 27, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “Esta normativa, que se aplicó no sólo en Chile, sino que, en varios países del mundo, 11 establecía que el derecho al sufragio estaba garantizado para ciertos sectores de la población, los cuales estaban asociados a las clases más altas de la sociedad, puesto que los requisitos para poder votar consideraban, generalmente, el tener renta y/o capital. En el caso de Chile se exigía también ser un hombre libre, mayor de 25 años, en caso de ser soltero o de 21 si estaba casado, además de saber leer y escribir. Senado de Chile. La eliminación del voto censitario en el país. El voto censitario se instauró tanto en Chile, como en diversos países americanos. A partir de la lectura del texto, ¿cómo afectó el voto censitario a la construcción del sistema democrático chileno?", "answers": [{"letter": "A", "text": "Promovió el diálogo entre los diferentes actores políticos del país."}, {"letter": "B", "text": "Evitó el fraude electoral junto a los intentos por perpetuar el poder."}, {"letter": "C", "text": "Limitó la representatividad del sistema político y generó exclusión social."}, {"letter": "D", "text": "Contribuyó a la construcción de un Estado social y democrático de derecho."}], "correctAnswer": null}, {"number": 28, "axis": "Historia: Mundo, América y Chile", "text": "La Constitución política de 1833 ofreció amplias atribuciones al poder Ejecutivo, sin embargo, se entregaron al parlamento algunas prerrogativas entre las que destaca", "answers": [{"letter": "A", "text": "La garantía de manejar las elecciones nacionales."}, {"letter": "B", "text": "La posibilidad de destituir al presidente de la república."}, {"letter": "C", "text": "La capacidad de destituir a los comandantes en jefe de las FFAA"}, {"letter": "D", "text": "La aprobación de las leyes periódicas como el presupuesto nacional."}], "correctAnswer": null}, {"number": 29, "axis": "Historia: Mundo, América y Chile", "text": "En la primera mitad del siglo XIX, la Confederación Perú Boliviana fue un intento de unir a los países de Perú y Bolivia en una sola entidad política y económica. En este contexto, ¿cuál fue la principal razón por la que la Confederación Perú Boliviana fue vista como una amenaza para Chile?", "answers": [{"letter": "A", "text": "La preocupación de que la confederación influyera en la política chilena."}, {"letter": "B", "text": "El temor a que la confederación se convirtiera en una potencia económica."}, {"letter": "C", "text": "La posibilidad de que la confederación estableciera un gobierno autoritario."}, {"letter": "D", "text": "El riesgo de que esta unidad política controlara las vías terrestres de América."}], "correctAnswer": null}, {"number": 30, "axis": "Historia: Mundo, América y Chile", "text": "La Doctrina Monroe fue una política exterior estadounidense que establecía la primacía de Estados Unidos en el continente americano y su derecho a intervenir en los asuntos internos de otros países. ¿Cuál de las siguientes opciones describe mejor las críticas que se 12 han hecho a esta doctrina en América Latina?", "answers": [{"letter": "A", "text": "La defensa de la democracia en los países latinoamericanos."}, {"letter": "B", "text": "La promoción del comercio y la inversión extranjera en la región."}, {"letter": "C", "text": "La limitación de la autonomía y la soberanía de los países de la región."}, {"letter": "D", "text": "La promoción de la integración regional y la cooperación internacional."}], "correctAnswer": null}, {"number": 31, "axis": "Historia: Mundo, América y Chile", "text": "La Sociedad de la Igualdad en Chile de 1850 fue una de las primeras organizaciones sociales en buscar la igualdad social en el país. ¿Qué impacto tuvo esta organización en la lucha por la igualdad social en Chile?", "answers": [{"letter": "A", "text": "Logró la abolición de la esclavitud en el territorio chileno."}, {"letter": "B", "text": "Propició una mayor conciencia social y política en la sociedad chilena."}, {"letter": "C", "text": "Generó una polarización política que dificultó soluciones consensuadas."}, {"letter": "D", "text": "Fue el principal motor de la reforma agraria en las zonas rurales de Chile."}], "correctAnswer": null}, {"number": 32, "axis": "Historia: Mundo, América y Chile", "text": "La cultura y las letras experimentaron un crecimiento durante la administración de Manuel Bulnes (1841 – 1851). Dicha eclosión artística se concretó con la conformación del movimiento intelectual de 1842. Considerando lo anterior, ¿cuál fue una de las razones por las que se impulsó este movimiento?", "answers": [{"letter": "A", "text": "Buscaba fomentar la producción agrícola y la industria nacional."}, {"letter": "B", "text": "Quería promover la libertad de prensa y el derecho a la información."}, {"letter": "C", "text": "Quería fortalecer el poder político del gobierno eliminando la oposición."}, {"letter": "D", "text": "Buscaba promover la cultura y las artes para impulsar el desarrollo del país."}], "correctAnswer": null}, {"number": 33, "axis": "Historia: Mundo, América y Chile", "text": "A fines del siglo XIX y principios del siglo XX, Chile experimentó un importante proceso de modernización y desarrollo económico que tuvo un impacto significativo en la estructura social del país. ¿Cuál fue una de las principales consecuencias de este proceso durante la primera mitad del siglo XX?", "answers": [{"letter": "A", "text": "La eliminación de las barreras sociales y la creación de una sociedad igualitaria."}, {"letter": "B", "text": "El surgimiento de un movimiento obrero organizado y la lucha por los derechos laborales."}, {"letter": "C", "text": "La adopción de un modelo económico proteccionista que limitaba la influencia extranjera."}, {"letter": "D", "text": "La consolidación de una élite empresarial y política que controlaba el poder 13 económico."}], "correctAnswer": null}, {"number": 34, "axis": "Historia: Mundo, América y Chile", "text": "Durante el período conservador, se produjo una profunda transformación en la estructura social y económica de Chile. En este contexto, ¿cuál fue una de las principales consecuencias de la expansión del modelo exportador en el país?", "answers": [{"letter": "A", "text": "La diversificación productiva de la economía chilena."}, {"letter": "B", "text": "La creación de un sector industrial potente en el país."}, {"letter": "C", "text": "La dependencia económica a los mercados externos."}, {"letter": "D", "text": "La expansión del mercado interno de bienes y servicios."}], "correctAnswer": null}, {"number": 35, "axis": "Historia: Mundo, América y Chile", "text": "En Chile, a pesar de la notable expansión de la economía producida durante gran parte del siglo XIX, existieron algunas crisis que frenaron temporalmente los ciclos de crecimiento. En ese contexto, ¿cuál es una de las características que distinguió a dichas crisis económicas?", "answers": [{"letter": "A", "text": "Se relacionaron con el cierre de oficinas salitreras."}, {"letter": "B", "text": "Se vincularon a períodos recesivos del comercio exterior."}, {"letter": "C", "text": "Se originaron en el agotamiento del modelo industrializador."}, {"letter": "D", "text": "Se debilitaron por la fortaleza del sistema financiero del país."}], "correctAnswer": null}, {"number": 36, "axis": "Historia: Mundo, América y Chile", "text": "Analice el siguiente cuadro estadístico: Año Derechos pagados por salitre. Rentas ordinarias del Estado Porcentaje (millones de pesos oro) (millones de pesos oro) Aporte salitre 1880 2,3 48,8 4,7 1890 35,0 72,8 48,15 1900 50,1 102,5 48,90 1910 80,4 156,7 51,31 1920 105,6 212,7 40,97 Cariola y Sunkel (1982) Un siglo de historia económica de Chile. La tabla adjunta presenta los derechos pagados por las compañías salitreras al Estado chileno, el total de los ingresos fiscales entre 1880 y 1920, junto con el porcentaje de participación de la industria salitrera al erario nacional. A partir de su análisis, ¿qué es posible concluir?", "answers": [{"letter": "A", "text": "La gran participación de capitales ingleses en la industria del salitre y los derechos pagados al fisco."}, {"letter": "B", "text": "El aporte mayoritario de las exportaciones salitreras a las rentas del Estado en la primera década del siglo XX."}, {"letter": "C", "text": "La disminución de la demanda del nitrato evidenciada en el aumento de los derechos pagados por las compañías."}, {"letter": "D", "text": "El crecimiento de la participación del salitre fue inversamente proporcional a los ingresos percibidos por el fisco en el periodo considerado."}], "correctAnswer": null}, {"number": 37, "axis": "Historia: Mundo, América y Chile", "text": "El Estado de Chile contó, a fines del siglo XIX y comienzos del XX, con importantes recursos fiscales provenientes de la actividad salitrera. Dichos ingresos fueron utilizados en diversos ámbitos como la ampliación de la cobertura escolar de enseñanza básica, la modernización del Estado y el aumento de la burocracia administrativa. Considerando lo anterior, ¿en qué otro aspecto relevante influye el aumento del capital del Estado?", "answers": [{"letter": "A", "text": "En la atención sanitaria gratuita para los sectores populares."}, {"letter": "B", "text": "En programas de seguridad laboral y legales para grupos obreros."}, {"letter": "C", "text": "En la nacionalización de los yacimientos salitreros por parte del Estado."}, {"letter": "D", "text": "En la construcción del ferrocarril para mejorar la conectividad del territorio."}], "correctAnswer": null}, {"number": 38, "axis": "Historia: Mundo, América y Chile", "text": "En la segunda mitad del siglo XIX, se produjo un movimiento social de envergadura para la época que tuvo como consecuencia la aparición de las Sociedades de Socorros Mutuos. Estas organizaciones se caracterizaron por", "answers": [{"letter": "A", "text": "incorporar a las mujeres a los trabajos artesanales."}, {"letter": "B", "text": "regular el comercio extranjero en los puertos del país."}, {"letter": "C", "text": "brindar protección ante eventualidades a sus afiliados."}, {"letter": "D", "text": "fortalecer la organización política en los sectores rurales."}], "correctAnswer": null}, {"number": 39, "axis": "Historia: Mundo, América y Chile", "text": "A fines del siglo XIX, se produjeron diversas luchas y movilizaciones sociales en demanda de un sistema de sufragio más inclusivo y democrático. A partir de lo anterior ¿Cuál fue un argumento utilizado por los obreros en contra del voto censitario?", "answers": [{"letter": "A", "text": "La necesidad de establecer un sistema de voto obligatorio."}, {"letter": "B", "text": "La falta de representación política de los sectores populares."}, {"letter": "C", "text": "La importancia de preservar las tradiciones y valores de la nación."}, {"letter": "D", "text": "La importancia de mantener el poder político en manos de las élites."}], "correctAnswer": null}, {"number": 40, "axis": "Historia: Mundo, América y Chile", "text": "Analice la siguiente tabla: Conventillos en Santiago, 1907 Cantidad de conventillos 1.574 Población en conventillos 75.000 Población total en Santiago 430.775 Rodrigo Hidalgo (2000), La política de casas baratas a principios del siglo XX. El caso chileno. La tabla adjunta da cuenta de la situación habitacional en la ciudad de Santiago, a inicios del siglo XX. A partir de su interpretación, ¿qué aspecto de la cuestión social es correcto establecer?", "answers": [{"letter": "A", "text": "La política de construcción de viviendas para los obreros. 15"}, {"letter": "B", "text": "La situación de hacinamiento evidenciada en las habitaciones obreras."}, {"letter": "C", "text": "La proliferación de tomas de terrenos para la autoconstrucción de viviendas."}, {"letter": "D", "text": "La relocalización de población hacia los conventillos promovida por el Estado."}], "correctAnswer": null}, {"number": 41, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “Hay progresos evidentes en el siglo transcurrido, ello no puede negarse. Pero esos progresos corresponden a la acción de toda la colectividad y en mayor proporción, si se quiere, a la clase proletaria que es el único agente de producción, de creación, de ejecución de las ideas y de los pensamientos. Pero esos progresos ostensibles, son precisamente la causa de la miseria proletaria. El progreso está construido, pues, con cuotas de la miseria”. Recabarren, L. (1910) Ricos y pobres. A partir de lo planteado por el autor en el fragmento anterior, ¿cuál fue el rol de los sectores populares en el desarrollo económico de Chile hacia el Centenario?", "answers": [{"letter": "A", "text": "Participaron activamente en la toma de decisiones económicas."}, {"letter": "B", "text": "Rechazaron los avances derivados de la modernización capitalista."}, {"letter": "C", "text": "Tuvieron participación en los beneficios financieros del crecimiento."}, {"letter": "D", "text": "Constituyeron la base productiva que sustentó el progreso material."}], "correctAnswer": null}, {"number": 42, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “El 24 de octubre de 1929, la quiebra de la Bolsa de Valores de Nueva York desató una de las peores crisis en la historia del capitalismo mundial. Considerando el papel hegemónico que en dicho sistema había venido adquiriendo Estados Unidos desde la Primera Guerra Mundial, no fue extraño que la Gran Depresión se propagara con rapidez hacia las demás economías capitalistas (…). En el caso específico de Chile, los efectos de la Gran Depresión fueron, al menos en el corto plazo, devastadores (…). Un muy citado estudio de la Liga de las Naciones (…) determinó que nuestro país fue el más golpeado en el mundo por este fenómeno”. Salazar y Pinto, (1999) Historia contemporánea de Chile. En la reseña anterior los historiadores se refieren al impacto de la Gran Depresión sobre la economía chilena en la década de 1930. Considerando los antecedentes señalados, ¿qué consecuencia social tuvo el panorama descrito?", "answers": [{"letter": "A", "text": "La disminución de las exportaciones de salitre."}, {"letter": "B", "text": "El rápido incremento de la pobreza y la marginalidad urbana."}, {"letter": "C", "text": "El surgimiento de nuevas formas de sociabilidad en la oligarquía."}, {"letter": "D", "text": "La caída repentina de la tasa de natalidad en las grandes ciudades."}], "correctAnswer": null}, {"number": 43, "axis": "Historia: Mundo, América y Chile", "text": "Durante el siglo XX, varios países experimentaron regímenes totalitarios, caracterizados 16 por el control absoluto del Estado sobre la vida de los ciudadanos y la supresión de las libertades individuales. En este contexto, ¿Cuál fue uno de los principales factores que permitió la ascensión de los regímenes totalitarios?", "answers": [{"letter": "A", "text": "La influencia de las ideas socialistas en la política europea."}, {"letter": "B", "text": "La creciente importancia de las fuerzas armadas en política."}, {"letter": "C", "text": "La ineficiencia de las democracias ante las demandas sociales."}, {"letter": "D", "text": "La masificación de tecnología que permitió mayor control social."}], "correctAnswer": null}, {"number": 44, "axis": "Historia: Mundo, América y Chile", "text": "Analice la siguiente imagen: Discurso de Perón al pueblo argentino. En la imagen se retrata a Juan Domingo Perón, principal representante del populismo latinoamericano del siglo XX. Al observar la fotografía, ¿cuál es una característica de este movimiento político?", "answers": [{"letter": "A", "text": "La demostración de tolerancia política."}, {"letter": "B", "text": "El uso de una figura política carismática."}, {"letter": "C", "text": "El desarrollo de la participación ciudadana."}, {"letter": "D", "text": "La legitimación de la oposición en la sociedad."}], "correctAnswer": null}, {"number": 45, "axis": "Historia: Mundo, América y Chile", "text": "Entre 1938 y 1973, los gobiernos chilenos incrementaron la inversión en áreas como salud, educación, vivienda y previsión, creando una serie de instituciones encargadas del desarrollo de la población. Al respecto, ¿qué objetivo persiguieron en conjunto estas iniciativas?", "answers": [{"letter": "A", "text": "Incrementar los ingresos familiares para potenciar el consumo y favorecer la producción."}, {"letter": "B", "text": "Proveer servicios sociales que permitieran disminuir la inequidad existente en el país."}, {"letter": "C", "text": "Redefinir el rol del Estado mediante la intervención directa en la producción y la propiedad estatal."}, {"letter": "D", "text": "Otorgar subsidios a la población más vulnerable para facilitar su acceso a los servicios sociales mínimos."}], "correctAnswer": null}, {"number": 46, "axis": "Historia: Mundo, América y Chile", "text": "Durante los inicios del estado de bienestar en el siglo XX, se implementaron políticas de seguridad social que buscaban mejorar las condiciones de vida de la población. En este contexto, ¿cuál fue una de las principales críticas surgidas hacia estas políticas?", "answers": [{"letter": "A", "text": "La reducción de la participación ciudadana en la toma de decisiones."}, {"letter": "B", "text": "La disminución de la calidad de los servicios ofrecidos a la población."}, {"letter": "C", "text": "La dependencia de la población al Estado afectando la iniciativa privada."}, {"letter": "D", "text": "La aplicación de políticas para proveer de servicios sociales a la población."}], "correctAnswer": null}, {"number": 47, "axis": "Historia: Mundo, América y Chile", "text": "La descolonización de África y Asia fue un proceso largo y complejo que tuvo lugar en el siglo XX. Una de las principales causas de este proceso fue", "answers": [{"letter": "A", "text": "La presión de los grupos religiosos en las colonias."}, {"letter": "B", "text": "El aumento del poderío militar de las naciones colonizadas."}, {"letter": "C", "text": "La disminución del poder económico de las potencias coloniales."}, {"letter": "D", "text": "La llegada al poder de líderes políticos extremistas en las colonias."}], "correctAnswer": null}, {"number": 48, "axis": "Historia: Mundo, América y Chile", "text": "En 1945, se creó la Organización de las Naciones Unidas. La ONU se ha convertido en una organización clave en la política internacional y ha tenido un impacto significativo en el mundo. ¿Cuál fue el principal objetivo de esta organización?", "answers": [{"letter": "A", "text": "Controlar la propagación del comunismo en todo el mundo."}, {"letter": "B", "text": "Crear un sistema político global basado en la democracia liberal."}, {"letter": "C", "text": "Prevenir futuras guerras y promover la cooperación internacional."}, {"letter": "D", "text": "Garantizar la victoria de los Aliados en la Segunda Guerra Mundial."}], "correctAnswer": null}, {"number": 49, "axis": "Historia: Mundo, América y Chile", "text": "En el siglo XIX, América Latina y Chile estuvieron fuertemente marcados por la influencia inglesa. Durante el siglo XX esta situación cambió, ya que Estados Unidos se convirtió en la principal potencia del mundo. En términos políticos, ¿cómo se manifestó la influencia estadounidense en Chile y la región durante la segunda mitad del siglo XX?", "answers": [{"letter": "A", "text": "Fomentando el ascenso al poder de gobiernos marxistas."}, {"letter": "B", "text": "Aplicando la Doctrina de Seguridad Nacional en Latino América."}, {"letter": "C", "text": "Impulsando la creación de un mercado común en Latinoamérica."}, {"letter": "D", "text": "Promoviendo la instalación de armas nucleares en zonas costeras."}], "correctAnswer": null}, {"number": 50, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “Se ha dicho que la mujer no necesita una mediana instrucción. Y es que aún hay quienes ven en ella al ser capaz solo de gobernar el hogar. Instruir a la mujer es hacerla digna y levantarla. Abrirle un campo más vasto de porvenir, es arrancar a la degradación a muchas de sus víctimas. Instrúyase a la mujer. No hay nada en ella que le haga ser colocada en un lugar más bajo que el del hombre (…). Tendréis en el bello sexo instruido, menos miserables, menos fanáticas y menos mujeres nulas. Hágasele amar la ciencia más que las joyas y las sedas. Que consagre a ella los mejores años de su vida”. Zegers, P. (1994) Gabriela Mistral en El Coquimbo. El fragmento anterior, de la poeta Gabriela Mistral, evidencia el pensamiento de la autora con relación a los cambios que necesita la sociedad chilena a mediados del siglo XX. A partir del texto ¿cuál es la transformación es que exige la poetisa?", "answers": [{"letter": "A", "text": "La mantención del rol tradicional de las mujeres."}, {"letter": "B", "text": "La entrega de derechos cívicos a las mujeres del país."}, {"letter": "C", "text": "La educación de las mujeres para generar su desarrollo."}, {"letter": "D", "text": "La instalación de las mujeres en los estudios científicos."}], "correctAnswer": null}, {"number": 51, "axis": "Historia: Mundo, América y Chile", "text": "En la década de 1950, se produjo una migración masiva de la población rural a las ciudades en Chile. ¿Cuál fue una de las consecuencias más significativas de la migración 19 campo-ciudad en esta época?", "answers": [{"letter": "A", "text": "El crecimiento económico en las áreas urbanas."}, {"letter": "B", "text": "El alza de la producción agrícola en las ciudades."}, {"letter": "C", "text": "La disminución de la pobreza en las áreas rurales."}, {"letter": "D", "text": "La formación de barrios precarios en las ciudades."}], "correctAnswer": null}, {"number": 52, "axis": "Historia: Mundo, América y Chile", "text": "Durante la década de 1970 y 1980, los regímenes militares de América Latina ejecutaron la Operación Cóndor, plan que significó una acción militar conjunta. A partir de loa anterior, ¿Cómo afectó la Operación Cóndor a los habitantes de América Latina?", "answers": [{"letter": "A", "text": "Debilitó la influencia de Estados Unidos en la política latinoamericana."}, {"letter": "B", "text": "Reprimió a grupos de izquierda mediante la acción conjunta de militares."}, {"letter": "C", "text": "Fomentó la cooperación entre diferentes movimientos sociales en la región."}, {"letter": "D", "text": "Facilitó la creación de una oposición democrática a los gobiernos autoritarios."}], "correctAnswer": null}, {"number": 53, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “En la población de 6 años y más el país contaba en 1952 con 3.732.787 alfabetos, de los cuales 1.845.489 eran hombres y 1.887.298 correspondían a mujeres. En coeficientes, estas cifras absolutas indican que, de cada 1.000 alfabetos de la nación, 494 eran hombres y 506 mujeres (…). En el área urbana del país, de los 2.607 alfabetos, 1.223.906 eran hombres y 1.383.143 mujeres, lo que indica que, de cada 1.000 alfabetos del área urbana, 469 eran hombres y 531 mujeres. En el área rural los alfabetos del país fueron 1.125.738, de los cuales había 621.583 hombres y 504.155 mujeres. En otros términos, de 1.000 alfabetos del área rural, 552 eran hombres y 448 mujeres”. XII Censo General de Población y Vivienda 1952. Los datos de la cita refieren a una consecuencia de la Ley de Instrucción Primaria Obligatoria, dictada en 1920. De acuerdo con las cifras presentadas, ¿qué se puede inferir acerca de la sociedad chilena a mediados del siglo XX?", "answers": [{"letter": "A", "text": "Las mujeres recibían mejores ofertas laborales."}, {"letter": "B", "text": "La cobertura en educación secundaria aumentó."}, {"letter": "C", "text": "Los alfabetos se concentraban en las zonas rurales."}, {"letter": "D", "text": "La educación primaria benefició a hombres y mujeres."}], "correctAnswer": null}, {"number": 54, "axis": "Historia: Mundo, América y Chile", "text": "En 1973 tras un golpe de Estado se instaló una dictadura militar en Chile que suprimió 20 el Estado de Derecho inmediatamente. Considerando lo anterior, ¿Qué medida tomó la Junta Militar en el país?", "answers": [{"letter": "A", "text": "Clausuró el Congreso Nacional."}, {"letter": "B", "text": "Promulgó una nueva constitución."}, {"letter": "C", "text": "Implementó un estado de bienestar."}, {"letter": "D", "text": "Reconoció a un solo partido político."}], "correctAnswer": null}, {"number": 55, "axis": "Historia: Mundo, América y Chile", "text": "Durante la dictadura militar, encabezada por Augusto Pinochet, se implementó una nueva Constitución que estableció un nuevo marco legal para Chile, ¿Cuál es una característica de esta Constitución?", "answers": [{"letter": "A", "text": "Limitó las libertades civiles."}, {"letter": "B", "text": "Garantizó la igualdad de género."}, {"letter": "C", "text": "Reconoció la autonomía indígena."}, {"letter": "D", "text": "Estableció una supervisión militar."}], "correctAnswer": null}, {"number": 56, "axis": "Historia: Mundo, América y Chile", "text": "En 1974, se crea la Dirección de Inteligencia Nacional, que dependía directamente de la Junta de Gobierno. ¿Cuál fue la función de la DINA en Chile durante el régimen de Pinochet?", "answers": [{"letter": "A", "text": "Garantizó la democracia y los derechos humanos."}, {"letter": "B", "text": "Fomentó el desarrollo económico y social del país."}, {"letter": "C", "text": "Investigó a opositores políticos del régimen militar."}, {"letter": "D", "text": "Restringió el emprendimiento económico en el país."}], "correctAnswer": null}, {"number": 57, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “El cambio que intentamos explicar es de aquellos que vuelven el orden social desde uno sostenido por el ejercicio de la autoridad a otro de carácter más natural para las cosas y las personas (…). La sola presencia del Estado actuando más allá de un cierto límite (…) contradice el estado natural de las cosas. La facilidad para la construcción de un orden nuevo dependerá en gran medida de si él se acerca o aleja de aquel orden natural objetivo”. Barahona, P (1990). Chile en el último cuarto de siglo. El texto anterior expresa los principios que sustentaron las transformaciones implementadas en Chile durante la dictadura militar. A partir de su análisis, ¿qué consecuencia tuvieron estas ideas sobre la estructura económica del país?", "answers": [{"letter": "A", "text": "Disminuyeron la participación estatal en favor de la iniciativa privada."}, {"letter": "B", "text": "Significaron la implementación de reformas que ampliaron el rol del Estado."}, {"letter": "C", "text": "Provocaron la adopción de medidas proteccionistas para industrias mineras."}, {"letter": "D", "text": "Permitieron el desarrollo de proyectos público-privados en el sector primario."}], "correctAnswer": null}, {"number": 58, "axis": "Historia: Mundo, América y Chile", "text": "Durante la dictadura militar en Chile, la Vicaría de la Solidaridad realizó diversas acciones que influyeron en el devenir político y social de la época. Considerando lo anterior, ¿cuál fue su principal objetivo?", "answers": [{"letter": "A", "text": "Fomentar la censura hacia los opositores del gobierno militar."}, {"letter": "B", "text": "Defender las políticas aplicadas por el Régimen militar instalado."}, {"letter": "C", "text": "Implementar políticas económicas que favorecieran la economía."}, {"letter": "D", "text": "Brindar asesoría legal a las víctimas de la represión de la dictadura."}], "correctAnswer": null}, {"number": 59, "axis": "Historia: Mundo, América y Chile", "text": "La campaña electoral del plebiscito de 1988 tuvo gran impacto en la sociedad chilena. ¿Cuál de las siguientes opciones es un antecedente en la campaña del No?", "answers": [{"letter": "A", "text": "La creación de una coalición de partidos democráticos."}, {"letter": "B", "text": "La consolidación del régimen dictatorial iniciado en 1973."}, {"letter": "C", "text": "La eliminación de la oposición política al régimen dictatorial."}, {"letter": "D", "text": "El debilitamiento de las fuerzas políticas opositoras a la dictadura."}], "correctAnswer": null}, {"number": 60, "axis": "Sistema Económico", "text": "Los modelos económicos se han ido diferenciando en el tiempo por las características del mercado. Considerando el sistema económico aplicado en el país, ¿cuál de las siguientes alternativas es una característica del mercado chileno?", "answers": [{"letter": "A", "text": "Los bienes de primera necesidad son suministrados por el Estado."}, {"letter": "B", "text": "Los consumidores tienen restricciones para adquirir algunos productos."}, {"letter": "C", "text": "Las personas pagan elevados impuestos para aportar al patrimonio fiscal."}, {"letter": "D", "text": "Las empresas presentan amplias libertades para generar nuevas inversiones."}], "correctAnswer": null}, {"number": 61, "axis": "Sistema Económico", "text": "En un mercado de libre competencia, la oferta y la demanda interactúan considerando los mutuos intereses. Sobre la base de lo recién expuesto, ¿cuál de las siguientes situaciones puede aumentar la demanda sobre un producto?", "answers": [{"letter": "A", "text": "El aumento del valor de la carne."}, {"letter": "B", "text": "La popularidad de un smartphone."}, {"letter": "C", "text": "El alza en el precio de los chocolates."}, {"letter": "D", "text": "La pérdida de interés de la población."}], "correctAnswer": null}, {"number": 62, "axis": "Sistema Económico", "text": "El funcionamiento del sistema económico depende de los equilibrios de mercado, sin 22 embargo, hay situaciones que generan desequilibrios afectando a oferentes o demandantes. En este sentido, ¿en cuál de las siguientes situaciones ocurre un desequilibrio de mercado?", "answers": [{"letter": "A", "text": "En un almacén se presentan varios productos con precios similares."}, {"letter": "B", "text": "En un colegio existe un quiosco para atender a todos los estudiantes."}, {"letter": "C", "text": "En una feria existen puestos de frutas para atender a sus consumidores."}, {"letter": "D", "text": "En una ciudad existe una multiplicidad de tiendas para reparar celulares."}], "correctAnswer": null}, {"number": 63, "axis": "Sistema Económico", "text": "En los últimos años, la inflación ha sido un tema preocupante dados sus efectos en la economía. A partir de lo anterior, ¿Cuál de las siguientes opciones puede contribuir al aumento de la inflación en Chile?", "answers": [{"letter": "A", "text": "El deterioro del patrimonio estatal."}, {"letter": "B", "text": "La reducción de las tasas de interés."}, {"letter": "C", "text": "El aumento en la demanda de bienes."}, {"letter": "D", "text": "La disminución del dinero en circulación."}], "correctAnswer": null}, {"number": 64, "axis": "Sistema Económico", "text": "Actualmente, han surgido organizaciones de trabajadores informales, como los repartidores de aplicaciones digitales que exigen mejores condiciones laborales. Sobre la base de lo anterior, ¿Cuál de las siguientes es una demanda de estas organizaciones?", "answers": [{"letter": "A", "text": "Fijar de manera autónoma las tarifas de los productos."}, {"letter": "B", "text": "Obtener subsidios para invertir en nuevas tecnologías."}, {"letter": "C", "text": "Utilizar espacios públicos para promover sus servicios."}, {"letter": "D", "text": "Ingresar a la formalidad para acceder a seguridad social."}], "correctAnswer": null}, {"number": 65, "axis": "Sistema Económico", "text": "Lea el siguiente texto: “Garantizar el Trabajo Decente y condiciones laborales justas, mediante la fiscalización del cumplimiento de la legislación laboral, previsional y de seguridad y salud en el trabajo, gestionando la denuncia de forma oportuna, eficiente y eficaz mediante el uso de tecnologías de la información que permitan aplicar la inteligencia inspectiva, tanto para los procesos de fiscalización reactiva como para la fiscalización de oficio por programa, incorporando además la fiscalización electrónica como una herramienta de amplia cobertura.” Dirección del Trabajo (2025). Objetivos institucionales. El párrafo corresponde a uno de los objetivos estratégicos institucionales de la Dirección del Trabajo en Chile. Sobre la base de lo expuesto, ¿cuál es una meta de esta institución? 23", "answers": [{"letter": "A", "text": "Supervisar el pago de cotizaciones previsionales."}, {"letter": "B", "text": "Regular los incentivos económicos extraordinarios."}, {"letter": "C", "text": "Controlar los impuestos que tributan las empresas."}, {"letter": "D", "text": "Observar que las metas de producción se cumplan."}], "correctAnswer": null}], "5": [{"number": 1, "axis": "Formación Ciudadana", "text": "La relación entre el Estado y los pueblos originarios ha tenido diversas repercusiones por los distintos procesos históricos vividos en Chile. En relación con lo anterior, ¿qué consecuencias actuales reflejan esta relación?", "answers": [{"letter": "A", "text": "La participación real en la construcción del Estado nacional."}, {"letter": "B", "text": "La conservación de sus territorios ancestrales dentro del Estado."}, {"letter": "C", "text": "La desvalorización de su identidad cultural en el territorio nacional."}, {"letter": "D", "text": "La ausencia de demandas político - territoriales hacia las autoridades."}], "correctAnswer": null}, {"number": 2, "axis": "Formación Ciudadana", "text": "Lea el siguiente texto: “Estos hechos han sucedido en un clima de violencia y confrontación de las autoridades políticas chilenas, quienes no pueden eludir su responsabilidad debido a la incapacidad política para solucionar el conflicto que se vive en nuestro Wallmapu”. CIPER. (2013) Carta abierta de Juana Calfunao al presidente Sebastián Piñera. El fragmento adjunto muestra la demanda de una representante mapuche a Sebastián Piñera durante su primer mandato como presidente de la República. Considerando el contexto referido en la carta, ¿qué desafío sociopolítico tiene el Estado chileno?", "answers": [{"letter": "A", "text": "Resolver las diferencias entre las comunidades a través de la mediación."}, {"letter": "B", "text": "Generar políticas que acojan las demandas mapuches y permitan el diálogo."}, {"letter": "C", "text": "Fomentar la integración cultural indígena para reducir los hechos de violencia."}, {"letter": "D", "text": "Establecer parlamentos entre empresarios locales y comunidades mapuches."}], "correctAnswer": null}, {"number": 3, "axis": "Formación Ciudadana", "text": "Durante las últimas décadas, Chile ha experimentado un aumento significativo de inmigrantes lo que ha permitido enriquecer la diversidad cultural del país. Considerando lo anterior, ¿cuál de las siguientes opciones explica esta tendencia?", "answers": [{"letter": "A", "text": "La estabilidad política y económica de Chile ha incentivado la migración en busca de mejores condiciones de vida."}, {"letter": "B", "text": "El cambio climático ha obligado a las personas a abandonar sus hogares, lo que ha llevado a un aumento en la migración hacia Chile."}, {"letter": "C", "text": "La tasa de natalidad de la población chilena ha disminuido, lo que ha llevado a un aumento en la inmigración para mantener la fuerza laboral."}, {"letter": "D", "text": "La presencia de una gran cantidad de instituciones de educación superior en Chile ha atraído a estudiantes y profesionales de diversos países."}], "correctAnswer": null}, {"number": 4, "axis": "Formación Ciudadana", "text": "Para alcanzar un crecimiento económico equilibrado y responsable con el medioambiente, Chile ha asumido el desafío de lograr un desarrollo económico sostenible. En relación con lo anterior, ¿cuál de las siguientes alternativas ejemplifica un desarrollo económico sostenible?", "answers": [{"letter": "A", "text": "El aumento de producción de petróleo y gas natural en territorio chileno."}, {"letter": "B", "text": "La promoción de una agricultura orgánica junto con la protección de suelos."}, {"letter": "C", "text": "La construcción de una central hidroeléctrica que afecta el ecosistema local."}, {"letter": "D", "text": "La tala de bosques nativos para la expansión de la industria maderera y forestal."}], "correctAnswer": null}, {"number": 5, "axis": "Formación Ciudadana", "text": "La participación ciudadana es clave en los estados democráticos. Estos le otorgan a la población el derecho de escoger a sus representantes. En el contexto de las elecciones, ¿cuál de las siguientes corresponde a una facultad de la ciudadanía?", "answers": [{"letter": "A", "text": "La fiscalización del proceso electoral."}, {"letter": "B", "text": "La definición de las normas electorales."}, {"letter": "C", "text": "La determinación de las fechas electorales."}, {"letter": "D", "text": "La proposición del financiamiento de campañas."}], "correctAnswer": null}, {"number": 6, "axis": "Formación Ciudadana", "text": "Los Derechos Humanos son reconocidos en gran parte de los Estados democráticos, reflejando su importancia en el mundo actual. En este sentido, ¿cuál de las siguientes es una 3 acción vinculada a estos derechos?", "answers": [{"letter": "A", "text": "Se validan en instancias excepcionales donde existe peligro."}, {"letter": "B", "text": "Se designan en determinadas situaciones de vulnerabilidad."}, {"letter": "C", "text": "Se destinan a personas que pertenecen a minorías sociales."}, {"letter": "D", "text": "Se aplican a cada persona por ser inalienables e indivisibles."}], "correctAnswer": null}, {"number": 7, "axis": "Formación Ciudadana", "text": "En Chile, los partidos políticos se organizan a través de asociaciones voluntarias que cuentan con personalidad jurídica, están integrados por personas naturales, con la finalidad de conducir el Estado y las políticas públicas. Considerando lo anterior, ¿cuál de las siguientes actividades es un objetivo de los partidos políticos?", "answers": [{"letter": "A", "text": "Contribuir a la formación política de la ciudadanía y sus afiliados."}, {"letter": "B", "text": "Controlar las actas de escrutinios y suma de votos en elecciones."}, {"letter": "C", "text": "Difundir ideas fundamentales para mantener el control ideológico."}, {"letter": "D", "text": "Fiscalizar el actuar en sala de diputados y senadores del congreso."}], "correctAnswer": null}, {"number": 8, "axis": "Formación Ciudadana", "text": "Lea el siguiente texto: “El sector se propone que alumnos y alumnas desarrollen sentido cívico, conozcan y comprendan los derechos y deberes que implica la vida en democracia, incluyendo la participación responsable en las actividades comunitarias y ciudadanas, que reconozcan la legitimidad de distintos puntos de vista, los que reflejan la diversidad de visiones que conviven en el país, que actúen responsablemente consigo mismos, con su entorno y en la sociedad, y que valoren los principios fundamentales de libertad, igualdad, justicia, pluralismo, responsabilidad social y respeto a los derechos humanos”. Ministerio de Educación (2009) Currículo de Historia, Geografía y Ciencias Sociales. En la cita adjunta se plantean los objetivos propuestos por el Ministerio de Educación de Chile para la asignatura de Historia, Geografía y Ciencias Sociales con respecto a la formación ciudadana. Según lo expuesto, ¿qué lograrán los estudiantes a través de los contenidos de dicha área del conocimiento?", "answers": [{"letter": "A", "text": "Ejercer derechos y deberes ciudadanos desde una perspectiva participativa."}, {"letter": "B", "text": "Comprender la relevancia del derecho a sufragio censitario en la democracia."}, {"letter": "C", "text": "Valorar el rol de los partidos políticos por sobre otras formas de participación."}, {"letter": "D", "text": "Destacar la influencia del Estado en la formación de la ciudadanía y los DDHH."}], "correctAnswer": null}, {"number": 9, "axis": "Formación Ciudadana", "text": "Como parte de su ingreso al mundo globalizado, Chile ha debido compatibilizar la 4 necesidad de abastecimiento energético para la producción con el cuidado y protección del medioambiente. Considerando lo anterior, ¿cuál de las siguientes iniciativas ha buscado resolver dicho desafío?", "answers": [{"letter": "A", "text": "La aprobación de megaproyectos hidroeléctricos."}, {"letter": "B", "text": "La flexibilización de las normas medioambientales."}, {"letter": "C", "text": "El fomento gubernamental de energías renovables."}, {"letter": "D", "text": "El financiamiento de organismos no gubernamentales."}], "correctAnswer": null}, {"number": 10, "axis": "Formación Ciudadana", "text": "En Chile, la titularidad de la función política recae sobre el presidente de la república, a quien le corresponde dirigir, planificar y coordinar las políticas superiores del Estado. En relación con ello, ¿cuál de las siguientes opciones constituye un ejemplo de dicha atribución presidencial?", "answers": [{"letter": "A", "text": "La resolución de veredictos judiciales."}, {"letter": "B", "text": "La discusión de leyes constitucionales."}, {"letter": "C", "text": "El manejo de las relaciones internacionales."}, {"letter": "D", "text": "El control de las acusaciones constitucionales."}], "correctAnswer": null}, {"number": 11, "axis": "Formación Ciudadana", "text": "Entre las responsabilidades políticas que tienen los funcionarios de la administración del Estado, una de las más importantes es la probidad. Considerando lo anterior, ¿de qué manera contribuye la probidad al fortalecimiento de la democracia en Chile?", "answers": [{"letter": "A", "text": "Impide a los empleados públicos participar en una campaña política."}, {"letter": "B", "text": "Permite la defensa de los funcionarios ante la vulneración de sus derechos."}, {"letter": "C", "text": "Promueve la inocencia de los funcionarios públicos respecto a ciertos delitos."}, {"letter": "D", "text": "Fomenta la confianza de la ciudadanía en la labor de las instituciones estatales."}], "correctAnswer": null}, {"number": 12, "axis": "Formación Ciudadana", "text": "Analice el siguiente párrafo: “La Contraloría General de la República (CGR) es un órgano superior de fiscalización de la Administración del Estado, que está contemplado en la Constitución Política y es autónomo respecto del Poder Ejecutivo y de los demás órganos públicos. Controla la legalidad de los actos administrativos y resguarda el correcto uso de los fondos públicos”. Dictámenes Contraloría General de la República. El texto corresponde a la definición y objetivos de la Contraloría General de la República, uno de los cuatro órganos de control estatal establecidos en la Constitución Política de Chile. Considerando el texto adjunto, ¿cuál de las siguientes alternativas constituye un propósito de la Contraloría?", "answers": [{"letter": "A", "text": "Resguardar la privacidad de los actos estatales."}, {"letter": "B", "text": "Transparentar el accionar del Estado y sus gastos."}, {"letter": "C", "text": "Proteger al Gobierno frente a organismos externos."}, {"letter": "D", "text": "Ampliar las atribuciones de los funcionarios públicos."}], "correctAnswer": null}, {"number": 13, "axis": "Formación Ciudadana", "text": "Un municipio es una corporación autónoma, de derecho público, con personalidad jurídica y patrimonio propio, que administra una comuna y cuya finalidad es satisfacer las necesidades de la comunidad local, así como asegurar su participación. En base a lo anterior, ¿cuál de las siguientes opciones constituye un desafío para estas corporaciones?", "answers": [{"letter": "A", "text": "Fiscalizar las decisiones políticas a nivel nacional."}, {"letter": "B", "text": "Legislar considerando los requerimientos de la región."}, {"letter": "C", "text": "Resolver problemáticas de la población de su territorio."}, {"letter": "D", "text": "Aumentar el presupuesto regional para recibir recursos."}], "correctAnswer": null}, {"number": 14, "axis": "Formación Ciudadana", "text": "Los ciudadanos poseen derechos y deberes establecidos por la Constitución. Respecto a los deberes, ¿cuál de las siguientes opciones ejemplifica un deber ciudadano?", "answers": [{"letter": "A", "text": "Militar en un partido político."}, {"letter": "B", "text": "Elegir a los ministros del Estado."}, {"letter": "C", "text": "Trabajar en una organización estatal."}, {"letter": "D", "text": "Pagar los impuestos y contribuciones."}], "correctAnswer": null}, {"number": 15, "axis": "Formación Ciudadana", "text": "Lea el siguiente texto: “Los tribunales civiles ejercen sus facultades sobre una comuna o agrupación de comunas y conocen en única y/o primera instancia, por regla general, de todas las causas en competencia civil sometidas a su conocimiento, de las causas de comercio, de minas, de los juicios no contenciosos y de todas aquellas materias o asuntos que la ley le encomiende” Poder Judicial. Manual introductorio juzgados civiles. El texto corresponde a un manual sobre los juzgados civiles del país en el que se explican sus facultades. En base a lo explicado en el párrafo, ¿cuál de las siguientes es una competencia de estos juzgados?", "answers": [{"letter": "A", "text": "Multar a infractores del tránsito en las ciudades del país."}, {"letter": "B", "text": "Resolver los casos de competencia penal en una comuna."}, {"letter": "C", "text": "Aplicar justicia sobre las causas civiles en última instancia"}, {"letter": "D", "text": "Conocer las causas civiles en el territorio de su jurisdicción."}], "correctAnswer": null}, {"number": 16, "axis": "Formación Ciudadana", "text": "El uso de redes sociales se ha convertido en una gran oportunidad para las sociedades democráticas, sin embargo, el uso irresponsable de las mismas, ha generado profundos riesgos. Considerando lo anterior, ¿cuál es uno de los riesgos de las redes sociales para la democracia? 6", "answers": [{"letter": "A", "text": "La divulgación de noticias falsas sobre la institucionalidad."}, {"letter": "B", "text": "La disminución de la polarización política en la democracia."}, {"letter": "C", "text": "El cuestionamiento permanente de las instituciones públicas."}, {"letter": "D", "text": "El fortalecimiento de la unidad frente a discursos nacionalistas."}], "correctAnswer": null}, {"number": 17, "axis": "Formación Ciudadana", "text": "En la mayoría de los países occidentales la democracia es el régimen político predominante. Considerando las características de la democracia, ¿cuál de las siguientes es un ejemplo en común de esta estrategia de gobierno?", "answers": [{"letter": "A", "text": "La búsqueda del bien común a través de la fuerza."}, {"letter": "B", "text": "La existencia de un Estado de derecho como fundamento."}, {"letter": "C", "text": "La anulación de la oposición política por parte del Gobierno."}, {"letter": "D", "text": "La autoridad de gobiernos que aplican arbitrariamente el poder."}], "correctAnswer": null}, {"number": 18, "axis": "Historia: Mundo, América y Chile", "text": "La sociedad burguesa heredó una serie de comportamientos e ideas que aún tienen vigencia en la mayor parte de las sociedades del mundo occidental. Considerando la influencia de la burguesía del siglo XIX, ¿cuál de los siguientes principios actuales es herencia de la burguesía?", "answers": [{"letter": "A", "text": "La participación masiva en actividades religiosas."}, {"letter": "B", "text": "La valoración del trabajo agrícola en la economía."}, {"letter": "C", "text": "La búsqueda del prestigio social a través del capital."}, {"letter": "D", "text": "La instalación de gobiernos con democracia censitaria."}], "correctAnswer": null}, {"number": 19, "axis": "Historia: Mundo, América y Chile", "text": "Durante el siglo XIX, la Revolución Industrial tuvo un impacto significativo en el mundo, transformando la producción, el comercio y la vida de las personas. En este sentido, ¿cómo se relaciona la Revolución Industrial con el imperialismo del siglo XIX?", "answers": [{"letter": "A", "text": "Al ampliar los bienes, los europeos llevaron prosperidad a las colonias."}, {"letter": "B", "text": "Al aumentar su producción, las potencias necesitaron materias primas."}, {"letter": "C", "text": "Al generar una economía globalizada, se acumularon metales preciosos."}, {"letter": "D", "text": "Al incrementar la natalidad, se necesitó expandir las fronteras nacionales."}], "correctAnswer": null}, {"number": 20, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “La política colonial es hija de la industrialización. Para los Estados (...) donde abundan los capitales y se acumulan rápidamente; donde el sistema industrial está en expansión y atrae, (...) donde la propia agricultura está condenada a industrializarse para sobrevivir, la exportación es un factor esencial de la prosperidad pública. La oportunidad para hacer inversiones y ofertar empleo está en relación directa con la dimensión del mercado exterior”. Ferry, J. (1890) Tonkín y mi patria. Según la historiografía existen múltiples factores que explican el desarrollo de la expansión territorial. A partir de la fuente anterior, ¿qué factor favoreció la implementación del imperialismo?", "answers": [{"letter": "A", "text": "El interés científico por explorar nuevos territorios."}, {"letter": "B", "text": "La creación de una economía exportadora de bienes."}, {"letter": "C", "text": "La justificación de civilizar a las sociedades atrasadas."}, {"letter": "D", "text": "El desarrollo de un ideal nacionalista para conquistar."}], "correctAnswer": null}, {"number": 21, "axis": "Historia: Mundo, América y Chile", "text": "Chile, durante el período de conformación del Estado-nación, debió aplicar distintas estrategias para superar los nuevos desafíos políticos. ¿Cuál de ellas utilizó para consolidar este proceso?", "answers": [{"letter": "A", "text": "Pactó acuerdos con España para obtener apoyo político y financiero."}, {"letter": "B", "text": "Buscó el apoyo de otras naciones americanas para formar una alianza."}, {"letter": "C", "text": "Estableció soberanía por medio de la ocupación y delimitación del territorio."}, {"letter": "D", "text": "Implementó políticas de industrialización para fortalecer la economía nacional."}], "correctAnswer": null}, {"number": 22, "axis": "Historia: Mundo, América y Chile", "text": "Durante el período de organización de la república en Chile, se crearon constituciones que tuvieron una corta vigencia. ¿Cuál fue el principal propósito en la promulgación de estas normas?", "answers": [{"letter": "A", "text": "Constituir una república con una base legal."}, {"letter": "B", "text": "Reconocer al catolicismo como religión oficial."}, {"letter": "C", "text": "Establecer un gobierno autocrático dictatorial."}, {"letter": "D", "text": "Organizar una política de economía centralizada."}], "correctAnswer": null}, {"number": 23, "axis": "Historia: Mundo, América y Chile", "text": "En 1823, Estados Unidos estableció la doctrina Monroe dirigida a los países de América Latina que recién habían conseguido su emancipación. Considerando lo anterior, ¿cuál de las siguientes fue una característica de aquella política internacional? 8", "answers": [{"letter": "A", "text": "Significó el intento de EEUU por posicionar su liderazgo en el continente."}, {"letter": "B", "text": "Alertó a los países americanos sobre la intervención de potencias asiáticas."}, {"letter": "C", "text": "Incorporó a los países americanos a un programa de integración económica."}, {"letter": "D", "text": "Restringió la participación económica de Europa en el continente americano."}], "correctAnswer": null}, {"number": 24, "axis": "Historia: Mundo, América y Chile", "text": "Tras alcanzar la independencia, la élite criolla chilena comenzó a discutir el sistema político que debía aplicarse en el país. En la década de 1820 hubo muchas propuestas que tensionaron a la aristocracia nacional, cuestión que se resolvió con una guerra civil que dio la victoria a los sectores conservadores. Sobre la base de lo anterior, ¿cuál fue una política asumida por los pelucones una vez instalados en el poder?", "answers": [{"letter": "A", "text": "Contrataron científicos europeos."}, {"letter": "B", "text": "Organizaron un Congreso Nacional."}, {"letter": "C", "text": "Declararon el libre comercio en Chile."}, {"letter": "D", "text": "Redactaron una constitución autoritaria."}], "correctAnswer": null}, {"number": 25, "axis": "Historia: Mundo, América y Chile", "text": "Durante el siglo XIX, conservadores y liberales se enfrascaron en un arduo debate por el sistema de educación que debía regir en el territorio nacional. Los conservadores defendieron la libertad de enseñanza, mientras que los liberales impulsaron el principio del Estado docente. Respecto a este último, ¿cuál de los siguientes eventos se relaciona con aquel principio?", "answers": [{"letter": "A", "text": "La defensa de valores cristianos a cargo del catolicismo."}, {"letter": "B", "text": "La publicación de la Ley General de Instrucción Primaria."}, {"letter": "C", "text": "La creación de una educación técnico-profesional estatal."}, {"letter": "D", "text": "La concesión de amplias libertades educativas a privados."}], "correctAnswer": null}, {"number": 26, "axis": "Historia: Mundo, América y Chile", "text": "A lo largo del siglo XIX, la economía chilena desarrolló un proceso expansivo, lo que se tradujo en un aumento de las exportaciones y la consolidación de Valparaíso como principal puerto del Pacífico Sur. Al respecto, ¿cuál fue uno de los factores que incidieron en esta situación?", "answers": [{"letter": "A", "text": "La aplicación de una política económica de carácter neoliberal."}, {"letter": "B", "text": "La demanda de manufacturas adquiridas desde países asiáticos."}, {"letter": "C", "text": "El desarrollo de actividades extractivas con alta demanda externa."}, {"letter": "D", "text": "El incremento de los aranceles aduaneros a los bienes importados."}], "correctAnswer": null}, {"number": 27, "axis": "Historia: Mundo, América y Chile", "text": "Hacia mediados del siglo XIX, el funcionamiento comercial y productivo de Chile experimentaba importantes transformaciones respecto a las décadas anteriores. En relación con lo recién expuesto, ¿cuál de los siguientes eventos se desarrolló en dicho período?", "answers": [{"letter": "A", "text": "La aplicación de políticas estatales de fomento industrial."}, {"letter": "B", "text": "La incorporación de los modelos proteccionistas europeos."}, {"letter": "C", "text": "La dependencia con respecto a los mercados sudamericanos."}, {"letter": "D", "text": "La relevancia de las exportaciones de materias primas mineras."}], "correctAnswer": null}, {"number": 28, "axis": "Historia: Mundo, América y Chile", "text": "Al asumir el poder en la segunda mitad del siglo XIX, los liberales implementaron diversos cambios sociales, políticos y económicos vinculados a su ideología. Considerando lo anterior, ¿cuál de las siguientes opciones explica una transformación política llevada a cabo por este sector político?", "answers": [{"letter": "A", "text": "La implantación del sufragio universal e igualitario."}, {"letter": "B", "text": "La formación de una alianza entre la Iglesia y el Estado."}, {"letter": "C", "text": "El fomento a la participación política de las clases populares."}, {"letter": "D", "text": "El debilitamiento del Ejecutivo y el fortalecimiento del Congreso."}], "correctAnswer": null}, {"number": 29, "axis": "Historia: Mundo, América y Chile", "text": "A mediados del siglo XIX emergió un movimiento que ejerció una firme oposición al autoritarismo conservador, proponiendo el fin de la hegemonía de este partido. A partir de lo anterior, ¿qué evento se vincula con esta oposición?", "answers": [{"letter": "A", "text": "La influencia ejercida por los movimientos liberales europeos."}, {"letter": "B", "text": "La participación activa del mundo obrero en los eventos del país."}, {"letter": "C", "text": "La implementación de reformas aplicadas a la Constitución Política."}, {"letter": "D", "text": "La incorporación de movimientos políticos vinculados al catolicismo."}], "correctAnswer": null}, {"number": 30, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente fragmento: “La secularización no tiene como consecuencia necesaria la declinación de la religión, pero sí su privatización (…). El catolicismo tuvo que aceptar su retiro de lo público como sinónimo de lo estatal, tuvo que aceptar de hecho que no era el origen de la legitimidad política y que la igualdad ante la ley significaba el pluralismo religioso. Pero la Iglesia se fue incorporando a la esfera pública moderna, a ese espacio que no es estatal, pero que tampoco es privado en un sentido de intimista o siquiera individual o doméstico, sino a aquel que finalmente hemos terminado por llamar sociedad civil”. Serrano, S. (2008) ¿Qué hacer con Dios en la República? El texto explica el proceso de secularización desarrollado en Chile en la segunda mitad del siglo XIX. De acuerdo con lo señalado en la reseña adjunta, ¿en qué consistió dicho proceso? 10", "answers": [{"letter": "A", "text": "En el fortalecimiento del catolicismo como fundamento del poder político."}, {"letter": "B", "text": "En la decadencia del fervor religioso entre los sectores medios y populares."}, {"letter": "C", "text": "En la paulatina pérdida de influencia de la Iglesia en los asuntos del Estado."}, {"letter": "D", "text": "En la privatización de las instituciones públicas vinculadas con el catolicismo."}], "correctAnswer": null}, {"number": 31, "axis": "Historia: Mundo, América y Chile", "text": "Durante el siglo XIX Chile experimentó una importante transformación de su espacio geográfico, incorporando importantes territorios. En este contexto, ¿cuál de las siguientes alternativas responde al propósito de esta expansión?", "answers": [{"letter": "A", "text": "El desarrollo del nacionalismo que unió a campesinos, obreros e industriales."}, {"letter": "B", "text": "El deseo por conformar un territorio hegemónico dentro de latinoamericana."}, {"letter": "C", "text": "El interés por consolidar el modelo exportador con nuevos recursos naturales."}, {"letter": "D", "text": "El afán de los gobiernos del período por convertir a Chile en potencia industrial."}], "correctAnswer": null}, {"number": 32, "axis": "Historia: Mundo, América y Chile", "text": "A mediados del siglo XIX Chile desarrolló un proceso colonizado en la zona del Estrecho de Magallanes primero para luego ocupar la zona de los Lagos. Considerando lo anterior, ¿Cuál fue el objetivo estatal al desarrollar esta colonización?", "answers": [{"letter": "A", "text": "Desarrollar la investigación científica en la Patagonia y Tierra del Fuego."}, {"letter": "B", "text": "Consolidar el territorio nacional en las regiones australes del continente."}, {"letter": "C", "text": "Fomentar la integración cultural entre colonos y las comunidades indígenas."}, {"letter": "D", "text": "Promover la creación de nuevas industrias para mejorar la economía del país."}], "correctAnswer": null}, {"number": 33, "axis": "Historia: Mundo, América y Chile", "text": "Tras la Guerra del Pacífico Chile anexó ricas zonas salitreras, las que comenzaron a ser explotadas y administradas, principalmente, por empresarios británicos. El oro blanco generó una gran riqueza no solo para los europeos, sino también para el Estado chileno. Considerando lo anterior, ¿cómo se benefició el Estado en el contexto del auge salitrero?", "answers": [{"letter": "A", "text": "Con los gravámenes que se aplicaban sobre la explotación del salitre."}, {"letter": "B", "text": "Con las acciones estatales que le permitían controlar el precio del nitrato."}, {"letter": "C", "text": "Con los salarios que generaban los trabajadores estatales de las salitreras."}, {"letter": "D", "text": "Con las empresas de comercialización estatal que llevaban salitre a Europa."}], "correctAnswer": null}, {"number": 34, "axis": "Historia: Mundo, América y Chile", "text": "Analice el siguiente recuadro: CHILE: CONTRIBUCIÓN DE LA INDUSTRIA SALITRERA A LAS RENTAS ORDINARIAS DE LA NACIÓN (1880-1929) Rentas ordinarias Porcentaje de Años de la nación contribución de la industria salitrera 1880 124.593,78 5,52 % 1885 127.810,73 33,77 % 1890 201.952,80 52,06 % 1895 199.709,63 66,03 % 1905 303.505,35 56,67 % 1910 437.346,89 55,14 % 1914 404.973,56 48,66 % 11 1919 379.097,68 24,12 % 1925 695.693,71 37,18 % 1929 1.267.556,41 23,65 % Roberto Hernández, (1930) El salitre: resumen histórico desde su descubrimiento y explotación. En la tabla se expresa el aporte realizado por la industria salitrera a las rentas estatales de Chile durante algunos años del período comprendido entre 1880 y 1929. A partir del análisis de los datos, ¿cuál de las siguientes tendencias se registró en dicho período?", "answers": [{"letter": "A", "text": "Un notable aumento en la contribución del salitre a las rentas nacionales al inicio de la Gran Depresión."}, {"letter": "B", "text": "Un rápido incremento de las rentas nacionales y del aporte del salitre después de la Guerra del Pacífico."}, {"letter": "C", "text": "Un aporte mayoritario del salitre a las rentas nacionales en los años posteriores al inicio de la Primera Guerra Mundial."}, {"letter": "D", "text": "Un incremento constante del aporte del salitre a las rentas nacionales durante los años de la República Parlamentaria."}], "correctAnswer": null}, {"number": 35, "axis": "Historia: Mundo, América y Chile", "text": "Los ciclos de crecimiento de la economía nacional, durante el siglo XIX, concluyeron debido a la disminución de la demanda externa, el agotamiento de yacimientos mineros y las crisis mundiales. En este contexto, ¿qué característica de la economía chilena se relaciona con dichos fenómenos?", "answers": [{"letter": "A", "text": "La inquietud por el aumento de la producción automatizada."}, {"letter": "B", "text": "El rol de los suministros para satisfacer la demanda nacional."}, {"letter": "C", "text": "La necesidad de contar con mercados de consumo extranjeros."}, {"letter": "D", "text": "El papel central del Estado en el fomento del comercio exterior."}], "correctAnswer": null}, {"number": 36, "axis": "Historia: Mundo, América y Chile", "text": "Si bien durante gran parte del siglo XIX el ejercicio político fue monopolizado por la oligarquía también hubo espacios para la expresión y participación popular, constituyéndose varias organizaciones, entre las que destacaron las sociedades de socorros mutuos o mutuales. Respecto de estas organizaciones, ¿cuál fue una de sus características?", "answers": [{"letter": "A", "text": "Fomentar la fraternidad entre los trabajadores."}, {"letter": "B", "text": "Estar influenciadas por el pensamiento anarquista."}, {"letter": "C", "text": "Contar con apoyo económico de los partidos políticos."}, {"letter": "D", "text": "Concentrar a trabajadores de las haciendas y estancias."}], "correctAnswer": null}, {"number": 37, "axis": "Historia: Mundo, América y Chile", "text": "En pleno desarrollo del ciclo del salitre en Chile surgió una pluralidad de organizaciones 12 obreras entre las que destacaron las mancomunales. A partir de lo anterior, ¿qué rasgo distinguió a estas asociaciones?", "answers": [{"letter": "A", "text": "El rol hegemónico de las mujeres en estas organizaciones."}, {"letter": "B", "text": "La inspiración ideológica en el liberalismo radical europeo."}, {"letter": "C", "text": "La regulación de su funcionamiento por iniciativa del Estado."}, {"letter": "D", "text": "La lucha contra el empresariado bajo el influjo del socialismo."}], "correctAnswer": null}, {"number": 38, "axis": "Historia: Mundo, América y Chile", "text": "Las transformaciones demográficas desarrolladas en Chile desde fines del siglo XIX hasta 1930 ocasionaron múltiples cambios, debido, entre otros antecedentes, a la migración campo-ciudad. De las siguientes opciones, ¿cuál corresponde a una consecuencia de estas transformaciones?", "answers": [{"letter": "A", "text": "La difusión de prácticas culturales de origen europeo."}, {"letter": "B", "text": "El surgimiento de nuevas formas de sociabilidad urbana."}, {"letter": "C", "text": "La conservación de los medios de transporte tradicionales."}, {"letter": "D", "text": "El mejoramiento de la infraestructura sanitaria y habitacional."}], "correctAnswer": null}, {"number": 39, "axis": "Historia: Mundo, América y Chile", "text": "A fines del siglo XIX y principios del siglo XX, nacieron diversas organizaciones obreras, que buscaban organizarse políticamente como también ayudar a sus integrantes y familias en caso de cesantía, enfermedad o muerte, pero enfrentaron serios obstáculos. Considerando este contexto, ¿cuál fue un desafío tras el desarrollo de estas asociaciones?", "answers": [{"letter": "A", "text": "Aplicar reglamentos y estructura dentro de sus organizaciones."}, {"letter": "B", "text": "Soportar la represión ejercida por empresarios y la policía estatal."}, {"letter": "C", "text": "Imponer sus candidatos en el Congreso para una legislación favorable."}, {"letter": "D", "text": "Obtener la ayuda de organizaciones internacionales para alcanzar sus fines."}], "correctAnswer": null}, {"number": 40, "axis": "Historia: Mundo, América y Chile", "text": "El período de Paz Armada se caracteriza por el aumento del gasto público en armamento por parte de las potencias imperialistas. Considerando lo expuesto, ¿qué otra característica definió este período?", "answers": [{"letter": "A", "text": "El establecimiento de alianzas entre las principales potencias."}, {"letter": "B", "text": "La disminución del ejército al tener armas tecnológicas y letales."}, {"letter": "C", "text": "La creación de organismos de paz que eviten el conflicto armado."}, {"letter": "D", "text": "El debilitamiento de la industrialización del Reino Unido y Francia."}], "correctAnswer": null}, {"number": 41, "axis": "Historia: Mundo, América y Chile", "text": "Analice la siguiente imagen: Mujeres durante la Gran Guerra, 1914 – 1918. La imagen proyecta el aporte de algunas mujeres durante la Gran Guerra. Considerando esta participación, ¿Con cuál de las consecuencias socioeconómica de la Primera Guerra Mundial es correcto relacionar la imagen adjunta?", "answers": [{"letter": "A", "text": "Con la creciente incorporación de las mujeres al mercado laboral."}, {"letter": "B", "text": "Con la disminución de la población femenina en tareas domésticas."}, {"letter": "C", "text": "Con el mejoramiento de la calidad de vida de la población femenina."}, {"letter": "D", "text": "Con la masiva participación de las mujeres en la guerra de trincheras."}], "correctAnswer": null}, {"number": 42, "axis": "Historia: Mundo, América y Chile", "text": "Analice la siguiente fotografía: “Gratis: café y donas para los desempleados”. La fotografía refiere a una de las consecuencias de la Crisis bursátil de 1929. Tras su análisis, ¿cuál fue una consecuencia inmediata de esta crisis económica?", "answers": [{"letter": "A", "text": "La privatización de los recursos para apoyar al Estado tras la crisis."}, {"letter": "B", "text": "La creación de nuevas fuentes laborales a cargo de la Bolsa de valores. 14"}, {"letter": "C", "text": "La preocupación de algunos empresarios por asistir a los desempleados."}, {"letter": "D", "text": "La aplicación de un modelo económico centralizado para solucionar la crisis."}], "correctAnswer": null}, {"number": 43, "axis": "Historia: Mundo, América y Chile", "text": "La Gran Depresión de 1929 generó trastornos económicos y políticos por toto el mundo, siendo Alemania uno de los países más afectados. Al respecto, ¿qué factor intensificó la crisis en Alemania?", "answers": [{"letter": "A", "text": "El triunfo de la revolución socialista que privatizó las industrias alemanas."}, {"letter": "B", "text": "La importancia de las exportaciones de salitre natural hacia Estados Unidos."}, {"letter": "C", "text": "La deuda que pesaba sobre el país tras las sanciones del Tratado de Versalles."}, {"letter": "D", "text": "El deterioro generado por el gobierno alemán tras la ampliación de beneficios."}], "correctAnswer": null}, {"number": 44, "axis": "Historia: Mundo, América y Chile", "text": "En Europa, durante el período de entreguerras, surgieron sistemas políticos totalitarios que controlaron el Estado utilizando medios similares para conservar y expandir su dominio. Considerando lo recién expuesto ¿cuál fue una de las características común en estos regímenes?", "answers": [{"letter": "A", "text": "La promoción de las libertades y derechos individuales."}, {"letter": "B", "text": "La adopción del keynesianismo como modelo económico."}, {"letter": "C", "text": "El liderazgo ejercido por múltiples partidos en sus territorios."}, {"letter": "D", "text": "El uso de estrategias de represión para controlar a la población."}], "correctAnswer": null}, {"number": 45, "axis": "Historia: Mundo, América y Chile", "text": "El populismo fue un fenómeno político y social que se desarrolló durante el siglo XX en Latinoamérica y que aplicó algunas de las políticas desarrolladas por los totalitarismos europeos. Considerando lo anterior, ¿cuál de las siguientes alternativas es una característica del populismo?", "answers": [{"letter": "A", "text": "Promocionar políticas económicas neoliberales."}, {"letter": "B", "text": "Proponer un líder carismático para la población."}, {"letter": "C", "text": "Priorizar la austeridad reduciendo el gasto fiscal."}, {"letter": "D", "text": "Desarrollar políticas sociales represivas en el país."}], "correctAnswer": null}, {"number": 46, "axis": "Historia: Mundo, América y Chile", "text": "Tras finalizar la Segunda Guerra Mundial se evidenció el poder de armamento y tecnología que significó la destrucción de ciudades y un alto costo humano, lo que repercutió en la formulación de nuevos estándares para proteger a la humanidad. Considerando lo anterior, ¿cuál fue el desafío de las potencias vencedoras tras la guerra?", "answers": [{"letter": "A", "text": "Organizar una institucionalidad que promueva derechos universales."}, {"letter": "B", "text": "Fomentar el uso de energía nuclear para contrarrestar a los enemigos."}, {"letter": "C", "text": "Fortalecer las relaciones diplomáticas con los derrotados en la guerra."}, {"letter": "D", "text": "Aumentar las fuerzas armadas de los países para asegurar su protección."}], "correctAnswer": null}, {"number": 47, "axis": "Historia: Mundo, América y Chile", "text": "Los conflictos bélicos de la primera mitad del siglo XX generaron consecuencias que se 15 prolongaron por varias décadas. En este contexto, ¿cuál fue un efecto económico de la Segunda Guerra Mundial?", "answers": [{"letter": "A", "text": "La creación de la Organización de Naciones Unidas."}, {"letter": "B", "text": "La pérdida de cincuenta millones de vidas humanas."}, {"letter": "C", "text": "La destrucción de gran parte de la industria europea."}, {"letter": "D", "text": "La reducción del protagonismo de EEUU en el mundo."}], "correctAnswer": null}, {"number": 48, "axis": "Historia: Mundo, América y Chile", "text": "Tras el fin de la Segunda Guerra Mundial, se observó un proceso de decadencia de los imperios coloniales europeos. Sobre la base de lo anterior, ¿Cuál fue un factor político que influyó en este fenómeno?", "answers": [{"letter": "A", "text": "El acercamiento de Estados Unidos a las colonias para gobernarlas."}, {"letter": "B", "text": "El desinterés europeo por mantener los territorios bajo su soberanía."}, {"letter": "C", "text": "El reducido contingente militar para controlar los territorios coloniales."}, {"letter": "D", "text": "El principio de autodeterminación de los pueblos propuesto por la ONU."}], "correctAnswer": null}, {"number": 49, "axis": "Historia: Mundo, América y Chile", "text": "A mediados del siglo XX Chile experimentó un vertiginoso crecimiento de las ciudades, vinculado con los esfuerzos industrializadores desarrollados en el país los que no avanzaron de la mano con políticas habitacionales públicas lo que generó una gran marginalidad urbana. En este contexto, ¿cuál fue el desafío para los gobiernos chilenos de la época?", "answers": [{"letter": "A", "text": "Erradicar a los pobladores a ciudades aledañas."}, {"letter": "B", "text": "Frenar el traslado de campesinos a las ciudades."}, {"letter": "C", "text": "Avanzar hacia la edificación en altura en el centro."}, {"letter": "D", "text": "Reducir la marginalidad con políticas habitacionales."}], "correctAnswer": null}, {"number": 50, "axis": "Historia: Mundo, América y Chile", "text": "En la década de 1960 la sociedad chilena experimentó importantes transformaciones que reflejaron una realidad distinta a la de las primeras décadas del siglo XX. En este sentido, ¿qué diferencia se puede establecer entre la sociedad de mediados del siglo XX con respecto a la de principios de esa centuria?", "answers": [{"letter": "A", "text": "La reducción de los medios de comunicación masiva."}, {"letter": "B", "text": "El rol participativo de las mujeres en el sistema político."}, {"letter": "C", "text": "El fortalecimiento político-electoral de los conservadores."}, {"letter": "D", "text": "La disminución de la matrícula en la educación secundaria."}], "correctAnswer": null}, {"number": 51, "axis": "Historia: Mundo, América y Chile", "text": "Al asumir el poder en 1973, la Junta nacional de gobierno tuvo como principal objetivo 16 erradicar la influencia marxista del país para restablecer el orden social e institucional. Considerando este objetivo, ¿cuál de las siguientes políticas se aplicó durante la dictadura?", "answers": [{"letter": "A", "text": "La represión hacia políticos de izquierda y opositores al gobierno."}, {"letter": "B", "text": "La constitución de una asamblea dedicada a erradicar el marxismo."}, {"letter": "C", "text": "La articulación de plebiscitos para generar participación ciudadana."}, {"letter": "D", "text": "La organización de sindicatos en las empresas públicas del territorio."}], "correctAnswer": null}, {"number": 52, "axis": "Historia: Mundo, América y Chile", "text": "Durante la dictadura militar en Chile se reformuló la organización del Estado, implementando cambios decisivos en el ámbito político. En relación con lo abordado, ¿qué restructuración se realizó para validar el poder político del régimen?", "answers": [{"letter": "A", "text": "Se promulgó una nueva Constitución política para organizar el país."}, {"letter": "B", "text": "Se creó una Asamblea Constituyente para reformular el sistema judicial."}, {"letter": "C", "text": "Se designó un consejo de ministros para revisar las causas penales del país."}, {"letter": "D", "text": "Se estableció una Congreso nacional para garantizar la participación política."}], "correctAnswer": null}, {"number": 53, "axis": "Historia: Mundo, América y Chile", "text": "A fines de la década del 70, el régimen militar llevó a cabo una serie de transformaciones políticas, económicas y sociales, cuyo objetivo fue refundar el país bajo una nueva ideología. Uno de aquellos cambios consistió en la instauración de las Administradoras de Fondos de Pensiones (AFP), que organizaron un nuevo modelo previsional en el país. Sobre la base de lo anterior, ¿cuál es la principal característica de esta reforma previsional?", "answers": [{"letter": "A", "text": "Es un modelo de reparto con aporte del Estado."}, {"letter": "B", "text": "Es una política de ahorro comunitario a largo plazo."}, {"letter": "C", "text": "Es un sistema de capitalización individual obligatorio."}, {"letter": "D", "text": "Es un régimen de inversión voluntario para el ahorro."}], "correctAnswer": null}, {"number": 54, "axis": "Historia: Mundo, América y Chile", "text": "Desde el año 1973, el surgimiento de organizaciones para defender los derechos humanos tuvo relación directa con el quiebre institucional y la acción del régimen militar. Considerando el contexto referido, ¿Qué organización cumplió un rol fundamental durante la dictadura militar?", "answers": [{"letter": "A", "text": "La ONU, a través de la Corte Internacional de La Haya."}, {"letter": "B", "text": "La Iglesia católica, a través de la vicaría de la solidaridad."}, {"letter": "C", "text": "El Partido Comunista mediante las asambleas populares."}, {"letter": "D", "text": "La ONG Amnistía Internacional por medio de sus oficinas."}], "correctAnswer": null}, {"number": 55, "axis": "Historia: Mundo, América y Chile", "text": "La dictadura cívico-militar propició la instauración del modelo neoliberal en Chile, sin embargo, la aplicación de este sistema no estuvo exento de cuestionamientos. Considerando lo anterior, ¿cuál de las siguientes fue una crítica a la implementación de este modelo?", "answers": [{"letter": "A", "text": "La influencia de la oposición en la implementación de las reformas."}, {"letter": "B", "text": "La dificultad de los militares para convencer al empresariado nacional."}, {"letter": "C", "text": "La crisis económica que desató el modelo al disminuir el rol del Estado."}, {"letter": "D", "text": "La imposibilidad del régimen para generar un consenso a nivel nacional."}], "correctAnswer": null}, {"number": 56, "axis": "Historia: Mundo, América y Chile", "text": "Lea el siguiente texto: “La protesta nacional como fenómeno político y social, surgió contra la dictadura, porque se le percibía como responsable de una política económica que prácticamente había devastado al país a través de la falta de trabajo y del empobrecimiento generalizado que afectaba a los sectores populares, y porque se le veía administrando una crisis sin tener capacidad de iniciativa creíble y reprimiendo duramente las expresiones de descontento social y de oposición, sin abrir ningún canal de participación (…) Sin embargo esta crisis solo actuó como un factor precipitante del descontento que ya exista hacia el orden político imperante y hacia el mismo gobierno, que había ejercido el poder autoritariamente y por medio de la opresión y represión de amplios sectores de la sociedad”. Lunecken, G. (2000) Vicaría de la Solidaridad. El texto refiere a las protestas nacionales que se generaron durante la dictadura. De acuerdo con lo planteado en el párrafo adjunto, ¿cuál fue un factor predominante en el surgimiento de las movilizaciones y protestas contra el régimen militar?", "answers": [{"letter": "A", "text": "El desarrollo de políticas populistas implementadas por el gobierno."}, {"letter": "B", "text": "Las medidas coercitivas de opresión y represión contra la ciudadanía."}, {"letter": "C", "text": "La crisis generada por las políticas económicas aplicadas por el Estado."}, {"letter": "D", "text": "Las libertades en el acceso, distribución y publicación de la información."}], "correctAnswer": null}, {"number": 57, "axis": "Sistema Económico", "text": "Lea el siguiente texto: “Promover las instancias de dialogo social tripartito mediante los sistemas de solución alternativa de conflictos, mesas de trabajo y consejos tripartitos regionales de usuarios y usuarias, que contribuyan a impulsar el trabajo decente incorporando la perspectiva de género” Dirección del Trabajo (2025) Acerca de la DT. El párrafo corresponde al cuarto objetivo estratégico de la Dirección del Trabajo en Chile, publicado en su página web. Sobre la base de lo planteado, ¿cuál es uno de los intereses de esta institución?", "answers": [{"letter": "A", "text": "Imponer sanciones para las empresas."}, {"letter": "B", "text": "Generar espacios para el diálogo colectivo."}, {"letter": "C", "text": "Resolver las acusaciones contra un empleado."}, {"letter": "D", "text": "Proponer cargos para mujeres en las empresas."}], "correctAnswer": null}, {"number": 58, "axis": "Sistema Económico", "text": "Lea la siguiente información: “En Chile los mayores precios del petróleo y la debilidad del peso elevaron el costo de la gasolina. Los precios al consumidor subieron 3,5 % en 12 meses, en comparación con el 19 3% de diciembre, dijo el Instituto Nacional de Estadísticas del país. Los costos de transporte subieron 1,1 % en enero, ya que los precios de la gasolina subieron 2,2 %, luego de un aumento en el precio del crudo. El costo de los alimentos y las bebidas no alcohólicas se elevó 1 %, mientras que el alcohol y el tabaco aumentaron 1,3%”. Quigley, J. (…) Inflación llega al 3,5% en 12 meses y se eleva al mayor ritmo desde 2016. El texto refiere al alza en el precio de ciertos productos y servicios en el país. Considerando lo expresado en la noticia, ¿qué factor explica esta situación en la economía chilena?", "answers": [{"letter": "A", "text": "La falta de competencia en el mercado financiero."}, {"letter": "B", "text": "La manipulación de precios por parte de las empresas."}, {"letter": "C", "text": "La dependencia del país con respecto a los combustibles."}, {"letter": "D", "text": "La falta de regulaciones eficientes para regular el mercado."}], "correctAnswer": null}, {"number": 59, "axis": "Sistema Económico", "text": "Tal como en otras partes del mundo, el mercado chileno presenta una serie de características y elementos propios. Considerando lo anterior, ¿qué características posee el mercado chileno?", "answers": [{"letter": "A", "text": "Recibe la influencia del Estado."}, {"letter": "B", "text": "Mantiene una economía estable."}, {"letter": "C", "text": "Depende del mercado internacional."}, {"letter": "D", "text": "Posee una industria con gran tecnología."}], "correctAnswer": null}, {"number": 60, "axis": "Sistema Económico", "text": "En una economía de libre mercado, el funcionamiento está determinado por la ley de la oferta y la demanda, sin embargo, existen situaciones que alteran estos factores provocando monopolios y oligopolios. Con respecto a los oligopolios, ¿cuál de las siguientes afirmaciones corresponde a una de sus características?", "answers": [{"letter": "A", "text": "Existe un solo comprador, alterando los precios de los productos."}, {"letter": "B", "text": "Existe un solo oferente y puede ser reemplazado por otros actores."}, {"letter": "C", "text": "Existe un solo vendedor que dificulta la competencia en el mercado."}, {"letter": "D", "text": "Existe un número reducido de productores que controlan un mercado."}], "correctAnswer": null}, {"number": 61, "axis": "Sistema Económico", "text": "En Chile, existen instituciones que permiten el normal funcionamiento del mercado, siendo uno de ellos el Banco Central. Considerando lo anterior, ¿cuál es la importancia de esta institución en la economía nacional?", "answers": [{"letter": "A", "text": "Controla las acciones del Servicio Nacional del Consumidor."}, {"letter": "B", "text": "Establece las bases para la fiscalización a empresas estatales."}, {"letter": "C", "text": "Gestiona la economía de la Tesorería General de la República."}, {"letter": "D", "text": "Regula el sistema aplicando políticas para controla la inflación."}], "correctAnswer": null}, {"number": 62, "axis": "Sistema Económico", "text": "El acceso al crédito o la denominada “democratización del consumo” explica gran parte de los cambios experimentados por los chilenos en las últimas décadas, sin importar la 20 condición socioeconómica de las personas. Considerando lo anterior, ¿cómo afecta el uso masificado del crédito en la sociedad?", "answers": [{"letter": "A", "text": "Genera igualdad en el acceso a las tecnologías."}, {"letter": "B", "text": "Incrementa la equidad socioeconómica en el país."}, {"letter": "C", "text": "Permite a la población acceder a múltiples bienes."}, {"letter": "D", "text": "Amplifica la pobreza pues son visibles las diferencias."}], "correctAnswer": null}, {"number": 63, "axis": "Sistema Económico", "text": "La inflación se define como el aumento gradual y sostenido en los precios de bienes y servicios durante un período determinado. ¿Cuál de las siguientes situaciones en el mercado puede generar inflación en el corto plazo?", "answers": [{"letter": "A", "text": "Un aumento en los costos de producción."}, {"letter": "B", "text": "Una disminución en el gasto del Gobierno."}, {"letter": "C", "text": "Una disminución en la oferta de circulante."}, {"letter": "D", "text": "Un aumento en la productividad económica."}], "correctAnswer": null}, {"number": 64, "axis": "Sistema Económico", "text": "En la actualidad, se plantea que los consumidores deben establecer el denominado consumo responsable. Esto es tener hábitos de consumo que estén en concordancia tanto con los ingresos reales de las personas como con el cuidado del medioambiente. En relación con ello, ¿cuál de las siguientes afirmaciones corresponde a un ejemplo específico de consumo responsable?", "answers": [{"letter": "A", "text": "Utilizar el cupo asignado en la tarjeta de crédito."}, {"letter": "B", "text": "Verificar la fecha de vencimiento de los productos."}, {"letter": "C", "text": "Sacar productos a crédito para amigos y familiares."}, {"letter": "D", "text": "Adquirir productos amigables con el medioambiente."}], "correctAnswer": null}, {"number": 65, "axis": "Sistema Económico", "text": "En el contexto de una economía de libre mercado, ¿cuál es el principal elemento que se ve afectado por la colusión?", "answers": [{"letter": "A", "text": "La oferta y demanda del mercado."}, {"letter": "B", "text": "La libre competencia entre las empresas."}, {"letter": "C", "text": "La innovación y desarrollo de nuevos bienes."}, {"letter": "D", "text": "La calidad de los productos y servicios ofrecidos."}], "correctAnswer": null}]};
